const questions: BankQuestion[] = [
  {"id":"reason-syllogism-1","question":"Statements: All cats are animals. All animals are living beings. Conclusions: I. All cats are living beings. II. Some living beings are cats.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Cats ⊂ animals ⊂ living beings, so I follows, and converting it gives II.","difficulty":"easy","questionHi":"कथन: सभी बिल्लियाँ जानवर हैं। सभी जानवर जीवित प्राणी हैं। निष्कर्ष: I. सभी बिल्लियाँ जीवित प्राणी हैं। II. कुछ जीवित प्राणी बिल्लियाँ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"बिल्लियाँ ⊂ जानवर ⊂ जीवित प्राणी, इसलिए I अनुसरण करता है, और इसका परिवर्तन करने पर II प्राप्त होता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-2","question":"Statements: All pens are books. No book is a table. Conclusions: I. No pen is a table. II. Some books are pens.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Pens sit inside books, which never touch tables, so I follows; II is the conversion of “All pens are books”.","difficulty":"easy","questionHi":"कथन: सभी पेन किताबें हैं। कोई किताब मेज़ नहीं है। निष्कर्ष: I. कोई पेन मेज़ नहीं है। II. कुछ किताबें पेन हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"पेन किताबों के अंदर हैं, और किताबों का मेज़ों से कोई संबंध नहीं है, इसलिए I अनुसरण करता है; II “सभी पेन किताबें हैं” का परिवर्तन है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-3","question":"Statements: Some boys are players. All players are tall. Conclusions: I. Some boys are tall. II. All tall people are players.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The boys who are players are tall, so I follows. “All players are tall” cannot be reversed, so II does not.","difficulty":"easy","questionHi":"कथन: कुछ लड़के खिलाड़ी हैं। सभी खिलाड़ी लंबे हैं। निष्कर्ष: I. कुछ लड़के लंबे हैं। II. सभी लंबे लोग खिलाड़ी हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो लड़के खिलाड़ी हैं वे लंबे हैं, इसलिए I अनुसरण करता है। “सभी खिलाड़ी लंबे हैं” का उलटा नहीं हो सकता, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-4","question":"Statements: Some apples are mangoes. Some mangoes are bananas. Conclusions: I. Some apples are bananas. II. Some bananas are mangoes.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Two “some” statements give no link between apples and bananas. II just converts the second statement.","difficulty":"moderate","questionHi":"कथन: कुछ सेब आम हैं। कुछ आम केले हैं। निष्कर्ष: I. कुछ सेब केले हैं। II. कुछ केले आम हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"दो “कुछ” वाले कथनों से सेब और केले के बीच कोई संबंध नहीं बनता। II केवल दूसरे कथन का परिवर्तन है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-5","question":"Statements: No dog is a cat. All cats are pets. Conclusions: I. No dog is a pet. II. Some pets are not dogs.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Dogs could still be pets, so I fails. The cats are pets that are not dogs, so II follows.","difficulty":"moderate","questionHi":"कथन: कोई कुत्ता बिल्ली नहीं है। सभी बिल्लियाँ पालतू हैं। निष्कर्ष: I. कोई कुत्ता पालतू नहीं है। II. कुछ पालतू कुत्ते नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"कुत्ते फिर भी पालतू हो सकते हैं, इसलिए I अनुसरण नहीं करता। बिल्लियाँ ऐसे पालतू हैं जो कुत्ते नहीं हैं, इसलिए II अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-6","question":"Statements: All roses are flowers. Some flowers are red. Conclusions: I. Some roses are red. II. All red things are flowers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"The red flowers may or may not include roses, and nothing says every red thing is a flower.","difficulty":"moderate","questionHi":"कथन: सभी गुलाब फूल हैं। कुछ फूल लाल हैं। निष्कर्ष: I. कुछ गुलाब लाल हैं। II. सभी लाल वस्तुएँ फूल हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"लाल फूलों में गुलाब हो भी सकते हैं और नहीं भी, और यह कहीं नहीं कहा गया कि हर लाल वस्तु फूल है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-7","question":"Statements: Some teachers are doctors. No doctor is a lawyer. Conclusions: I. Some teachers are not lawyers. II. Some lawyers are teachers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The teachers who are doctors cannot be lawyers, so I follows; II is only a possibility.","difficulty":"hard","questionHi":"कथन: कुछ शिक्षक डॉक्टर हैं। कोई डॉक्टर वकील नहीं है। निष्कर्ष: I. कुछ शिक्षक वकील नहीं हैं। II. कुछ वकील शिक्षक हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो शिक्षक डॉक्टर हैं वे वकील नहीं हो सकते, इसलिए I अनुसरण करता है; II केवल एक संभावना है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-8","question":"Statements: All A are B. Some B are C. No C is D. Conclusions: I. Some B are not D. II. Some A are C.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The B that are C cannot be D, so I follows. A may or may not overlap C.","difficulty":"hard","questionHi":"कथन: सभी A, B हैं। कुछ B, C हैं। कोई C, D नहीं है। निष्कर्ष: I. कुछ B, D नहीं हैं। II. कुछ A, C हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो B, C हैं वे D नहीं हो सकते, इसलिए I अनुसरण करता है। A और C का आपस में संबंध हो भी सकता है और नहीं भी।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-9","question":"Statements: Only a few phones are laptops. All laptops are tablets. Conclusions: I. Some phones are tablets. II. All phones being laptops is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The phones that are laptops are tablets, so I follows. “Only a few” rules out all phones being laptops.","difficulty":"hard","questionHi":"कथन: केवल कुछ फ़ोन लैपटॉप हैं। सभी लैपटॉप टैबलेट हैं। निष्कर्ष: I. कुछ फ़ोन टैबलेट हैं। II. सभी फ़ोन के लैपटॉप होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो फ़ोन लैपटॉप हैं वे टैबलेट हैं, इसलिए I अनुसरण करता है। “केवल कुछ” से यह संभावना समाप्त हो जाती है कि सभी फ़ोन लैपटॉप हों।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-10","question":"Statements: All stars are planets. No planet is a moon. Some moons are satellites. Conclusions: I. Some satellites are not planets. II. No star is a moon.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The satellites that are moons cannot be planets (I). Stars sit inside planets, which never touch moons (II).","difficulty":"very-hard","questionHi":"कथन: सभी तारे ग्रह हैं। कोई ग्रह चंद्रमा नहीं है। कुछ चंद्रमा उपग्रह हैं। निष्कर्ष: I. कुछ उपग्रह ग्रह नहीं हैं। II. कोई तारा चंद्रमा नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो उपग्रह चंद्रमा हैं वे ग्रह नहीं हो सकते (I)। तारे ग्रहों के अंदर हैं, और ग्रहों का चंद्रमाओं से कोई संबंध नहीं है (II)।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-11","question":"Statements: Some X are Y. All Y are Z. No Z is W. Conclusions: I. Some X are not W. II. Some Z are X.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The X that are Y are also Z and so cannot be W (I); those same X are Z, giving II.","difficulty":"very-hard","questionHi":"कथन: कुछ X, Y हैं। सभी Y, Z हैं। कोई Z, W नहीं है। निष्कर्ष: I. कुछ X, W नहीं हैं। II. कुछ Z, X हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो X, Y हैं वे Z भी हैं और इसलिए W नहीं हो सकते (I); वही X, Z हैं, जिससे II प्राप्त होता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-12","question":"Statements: All pencils are erasers. Some erasers are sharpeners. No sharpener is a scale. Conclusions: I. All pencils being sharpeners is a possibility. II. Some erasers are not scales.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Nothing stops pencils from all being sharpeners (I). The erasers that are sharpeners cannot be scales (II).","difficulty":"very-hard","questionHi":"कथन: सभी पेंसिलें रबर हैं। कुछ रबर शार्पनर हैं। कोई शार्पनर स्केल नहीं है। निष्कर्ष: I. सभी पेंसिलों के शार्पनर होने की संभावना है। II. कुछ रबर स्केल नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"कुछ भी पेंसिलों को सभी के शार्पनर होने से नहीं रोकता (I)। जो रबर शार्पनर हैं वे स्केल नहीं हो सकते (II)।","subtopic":"possibility"},
  {"id":"reason-syllogism-13","question":"Statements: No man is a machine. Some machines are robots. All robots are smart. Conclusions: I. Some smart things are not men. II. Some machines are smart.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The machines that are robots are smart (II), and being machines they are not men, so some smart things are not men (I).","difficulty":"very-hard","questionHi":"कथन: कोई मनुष्य मशीन नहीं है। कुछ मशीनें रोबोट हैं। सभी रोबोट स्मार्ट हैं। निष्कर्ष: I. कुछ स्मार्ट वस्तुएँ मनुष्य नहीं हैं। II. कुछ मशीनें स्मार्ट हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो मशीनें रोबोट हैं वे स्मार्ट हैं (II), और मशीन होने के कारण वे मनुष्य नहीं हैं, इसलिए कुछ स्मार्ट वस्तुएँ मनुष्य नहीं हैं (I)।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-14","question":"Statements: All pens are books. Some books are tables. Conclusions: I. Some pens are tables. II. Some tables are books.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The books that are tables need not be pens, so I does not follow. II is the converse of “some books are tables” and follows.","difficulty":"very-hard","questionHi":"कथन: सभी पेन किताबें हैं। कुछ किताबें मेज़ हैं। निष्कर्ष: I. कुछ पेन मेज़ हैं। II. कुछ मेज़ किताबें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो किताबें मेज़ हैं वे पेन हों, यह आवश्यक नहीं, इसलिए I अनुसरण नहीं करता। II “कुछ किताबें मेज़ हैं” का उलटा है और अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-15","question":"Statements: No cat is a dog. All dogs are rats. Conclusions: I. Some rats are not cats. II. No rat is a cat.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The rats that are dogs are not cats, so I follows. Other rats may be cats, so II does not.","difficulty":"very-hard","questionHi":"कथन: कोई बिल्ली कुत्ता नहीं है। सभी कुत्ते चूहे हैं। निष्कर्ष: I. कुछ चूहे बिल्ली नहीं हैं। II. कोई चूहा बिल्ली नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो चूहे कुत्ते हैं वे बिल्ली नहीं हैं, इसलिए I अनुसरण करता है। अन्य चूहे बिल्लियाँ हो सकते हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-16","question":"Statements: Some A are B. No B is C. Conclusions: I. Some A are not C. II. Some C are A.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The A that are B cannot be C, so I follows. Nothing links C to A, so II does not.","difficulty":"very-hard","questionHi":"कथन: कुछ A, B हैं। कोई B, C नहीं है। निष्कर्ष: I. कुछ A, C नहीं हैं। II. कुछ C, A हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो A, B हैं वे C नहीं हो सकते, इसलिए I अनुसरण करता है। C को A से जोड़ने वाला कुछ नहीं है, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-17","question":"Statements: Some pens are pencils. All pencils are boxes. No box is a cap. Conclusions: I. No pen is a cap. II. Some boxes are pens.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The pens that are pencils are boxes, so II follows. Those pens are not caps, but the other pens may be, so I does not follow.","difficulty":"very-hard","source":"IBPS PO · SSC CGL","questionHi":"कथन: कुछ पेन पेंसिलें हैं। सभी पेंसिलें डिब्बे हैं। कोई डिब्बा टोपी नहीं है। निष्कर्ष: I. कोई पेन टोपी नहीं है। II. कुछ डिब्बे पेन हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो पेन पेंसिलें हैं वे डिब्बे हैं, इसलिए II अनुसरण करता है। वे पेन टोपी नहीं हैं, पर बाकी पेन टोपी हो सकते हैं, इसलिए I अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-18","question":"Statements: All A are B. Some B are C. No C is D. Conclusions: I. Some A being D is a possibility. II. Some B are not D.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Nothing connects A with D, so A being D remains possible (I). The B that are C cannot be D, so II follows definitely.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"कथन: सभी A, B हैं। कुछ B, C हैं। कोई C, D नहीं है। निष्कर्ष: I. कुछ A के D होने की संभावना है। II. कुछ B, D नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"A को D से जोड़ने वाला कुछ नहीं है, इसलिए A के D होने की संभावना बनी रहती है (I)। जो B, C हैं वे D नहीं हो सकते, इसलिए II निश्चित रूप से अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-19","question":"Statements: All birds have wings. All parrots are birds. Conclusions: I. All parrots have wings. II. Some winged creatures are parrots.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Parrots ⊂ birds ⊂ winged creatures, so I follows; the parrots inside the winged circle make II true as well.","difficulty":"easy","source":"SSC GD · RRB NTPC","questionHi":"कथन: सभी पक्षियों के पंख होते हैं। सभी तोते पक्षी हैं। निष्कर्ष: I. सभी तोतों के पंख होते हैं। II. कुछ पंख वाले प्राणी तोते हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"तोते ⊂ पक्षी ⊂ पंख वाले प्राणी, इसलिए I अनुसरण करता है; पंख वाले वृत्त के अंदर तोते होने से II भी सत्य है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-20","question":"Statements: No fruit is a vegetable. All mangoes are fruits. Conclusions: I. No mango is a vegetable. II. Some vegetables are mangoes.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Mangoes lie inside the fruit circle, which has no overlap with vegetables, so I follows and II is impossible.","difficulty":"easy","source":"SSC CHSL · SSC GD","questionHi":"कथन: कोई फल सब्ज़ी नहीं है। सभी आम फल हैं। निष्कर्ष: I. कोई आम सब्ज़ी नहीं है। II. कुछ सब्ज़ियाँ आम हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"आम फल वाले वृत्त के अंदर हैं, जिसका सब्ज़ियों से कोई मेल नहीं है, इसलिए I अनुसरण करता है और II असंभव है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-21","question":"Statements: All chairs are tables. Some tables are wooden. Conclusions: I. Some chairs are wooden. II. Some wooden things are tables.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The wooden part of the table circle need not touch the chair circle, so I does not follow. II is just the converse of 'some tables are wooden' and follows.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"कथन: सभी कुर्सियाँ मेज़ हैं। कुछ मेज़ लकड़ी की हैं। निष्कर्ष: I. कुछ कुर्सियाँ लकड़ी की हैं। II. कुछ लकड़ी की वस्तुएँ मेज़ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"मेज़ वाले वृत्त का लकड़ी वाला भाग कुर्सी वाले वृत्त को छुए, यह आवश्यक नहीं, इसलिए I अनुसरण नहीं करता। II केवल ‘कुछ मेज़ लकड़ी की हैं’ का उलटा है और अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-22","question":"Statements: Some books are novels. All novels are stories. Conclusions: I. Some books are stories. II. All stories are novels.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The books that are novels lie inside stories, so I follows. Stories may extend beyond novels, so II does not follow.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"कथन: कुछ किताबें उपन्यास हैं। सभी उपन्यास कहानियाँ हैं। निष्कर्ष: I. कुछ किताबें कहानियाँ हैं। II. सभी कहानियाँ उपन्यास हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो किताबें उपन्यास हैं वे कहानियों के अंदर हैं, इसलिए I अनुसरण करता है। कहानियाँ उपन्यासों से अधिक हो सकती हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-23","question":"Statements: No pen is a pencil. Some pencils are erasers. Conclusions: I. Some erasers are not pens. II. Some pens are erasers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The erasers that are pencils cannot be pens (pen and pencil circles are disjoint), so I follows. Nothing links pens to erasers, so II is only a possibility.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कथन: कोई पेन पेंसिल नहीं है। कुछ पेंसिलें रबर हैं। निष्कर्ष: I. कुछ रबर पेन नहीं हैं। II. कुछ पेन रबर हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो रबर पेंसिलें हैं वे पेन नहीं हो सकते (पेन और पेंसिल के वृत्त अलग-अलग हैं), इसलिए I अनुसरण करता है। पेन और रबर को जोड़ने वाला कुछ नहीं है, इसलिए II केवल एक संभावना है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-24","question":"Statements: Some cups are plates. All plates are spoons. Conclusions: I. Some spoons are cups. II. All cups are spoons.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Cups that are plates are inside spoons, so some spoons are cups (I). Cups outside the plate circle may lie outside spoons, so II does not follow.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"कथन: कुछ कप प्लेटें हैं। सभी प्लेटें चम्मच हैं। निष्कर्ष: I. कुछ चम्मच कप हैं। II. सभी कप चम्मच हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो कप प्लेटें हैं वे चम्मचों के अंदर हैं, इसलिए कुछ चम्मच कप हैं (I)। प्लेट वाले वृत्त से बाहर के कप चम्मचों से बाहर हो सकते हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-25","question":"Statements: All A are B. No B is C. Conclusions: I. No A is C. II. Some C are not B.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"A sits inside B and B is disjoint from C, so no A is C (I). Since no C is B, every C lies outside B, so 'some C are not B' is certainly true (II).","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"कथन: सभी A, B हैं। कोई B, C नहीं है। निष्कर्ष: I. कोई A, C नहीं है। II. कुछ C, B नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"A, B के अंदर है और B का C से कोई मेल नहीं है, इसलिए कोई A, C नहीं है (I)। चूँकि कोई C, B नहीं है, हर C, B से बाहर है, इसलिए ‘कुछ C, B नहीं हैं’ निश्चित रूप से सत्य है (II)।","subtopic":"two-statements"},
  {"id":"reason-syllogism-26","question":"Statements: Some roads are streets. No street is a lane. Conclusions: I. Some roads are not lanes. II. No road is a lane.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The roads that are streets lie outside lanes, so I follows. Roads that are not streets could still be lanes, so II does not follow.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कुछ सड़कें गलियाँ हैं। कोई गली पगडंडी नहीं है। निष्कर्ष: I. कुछ सड़कें पगडंडी नहीं हैं। II. कोई सड़क पगडंडी नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो सड़कें गलियाँ हैं वे पगडंडियों से बाहर हैं, इसलिए I अनुसरण करता है। जो सड़कें गलियाँ नहीं हैं वे फिर भी पगडंडी हो सकती हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-27","question":"Statements: All X are Y. Some Y are Z. Conclusions: I. Some Z are X. II. Some Z being X is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The Z-part of Y may or may not touch X, so I is not certain, but nothing rules it out, so II (a possibility) follows.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: सभी X, Y हैं। कुछ Y, Z हैं। निष्कर्ष: I. कुछ Z, X हैं। II. कुछ Z के X होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"Y का Z वाला भाग X को छू भी सकता है और नहीं भी, इसलिए I निश्चित नहीं है, पर कुछ भी इसे असंभव नहीं बताता, इसलिए II (संभावना) अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-28","question":"Statements: Only a few cars are buses. No bus is a truck. Conclusions: I. Some cars are not trucks. II. All cars being trucks is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"'Only a few cars are buses' means some cars are buses and some are not. The cars that are buses cannot be trucks, so I follows. Those same cars make 'all cars are trucks' impossible, so II does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ कारें बसें हैं। कोई बस ट्रक नहीं है। निष्कर्ष: I. कुछ कारें ट्रक नहीं हैं। II. सभी कारों के ट्रक होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘केवल कुछ कारें बसें हैं’ का अर्थ है कि कुछ कारें बसें हैं और कुछ नहीं हैं। जो कारें बसें हैं वे ट्रक नहीं हो सकतीं, इसलिए I अनुसरण करता है। वही कारें ‘सभी कारें ट्रक हैं’ को असंभव बना देती हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-29","question":"Statements: All keys are locks. No lock is a door. Some doors are windows. Conclusions: I. Some windows are not locks. II. Some keys being windows is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Windows that are doors lie outside locks, so I follows. Keys are inside locks, and windows that are not doors can overlap locks and keys, so II is possible and follows.","difficulty":"hard","source":"IBPS PO · SSC CGL","questionHi":"कथन: सभी चाबियाँ ताले हैं। कोई ताला दरवाज़ा नहीं है। कुछ दरवाज़े खिड़कियाँ हैं। निष्कर्ष: I. कुछ खिड़कियाँ ताले नहीं हैं। II. कुछ चाबियों के खिड़कियाँ होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो खिड़कियाँ दरवाज़े हैं वे तालों से बाहर हैं, इसलिए I अनुसरण करता है। चाबियाँ तालों के अंदर हैं, और जो खिड़कियाँ दरवाज़े नहीं हैं वे तालों और चाबियों से मेल खा सकती हैं, इसलिए II संभव है और अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-30","question":"Statements: All pens are caps. Some caps are inks. Conclusions: I. Some pens are inks. II. No pen is an ink.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"The ink part of caps may or may not touch pens, so neither conclusion is certain. But I ('some are') and II ('none are') are complementary with the same subject and predicate, so exactly one must be true: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI Clerk","questionHi":"कथन: सभी पेन टोपियाँ हैं। कुछ टोपियाँ स्याही हैं। निष्कर्ष: I. कुछ पेन स्याही हैं। II. कोई पेन स्याही नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"टोपियों का स्याही वाला भाग पेनों को छू भी सकता है और नहीं भी, इसलिए दोनों में से कोई भी निश्चित नहीं है। परंतु I (‘कुछ हैं’) और II (‘कोई नहीं है’) एक ही उद्देश्य और विधेय वाला पूरक युग्म हैं, इसलिए उनमें से ठीक एक अवश्य सत्य होगा: I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-31","question":"Statements: No apple is a grape. All grapes are berries. Conclusions: I. Some berries are not apples. II. Some apples being berries is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Berries that are grapes are not apples, so I follows. Apples can overlap the non-grape part of berries, so II is possible and follows.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: कोई सेब अंगूर नहीं है। सभी अंगूर बेरियाँ हैं। निष्कर्ष: I. कुछ बेरियाँ सेब नहीं हैं। II. कुछ सेबों के बेरी होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो बेरियाँ अंगूर हैं वे सेब नहीं हैं, इसलिए I अनुसरण करता है। सेब बेरियों के गैर-अंगूर भाग से मेल खा सकते हैं, इसलिए II संभव है और अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-32","question":"Statements: Some tables are chairs. All chairs are desks. No desk is a bench. Conclusions: I. Some tables are not benches. II. All benches being tables is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Tables that are chairs are desks, hence not benches: I follows. Benches are disjoint from desks only; they can all lie inside the non-desk part of tables, so II is possible.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ मेज़ कुर्सियाँ हैं। सभी कुर्सियाँ डेस्क हैं। कोई डेस्क बेंच नहीं है। निष्कर्ष: I. कुछ मेज़ बेंच नहीं हैं। II. सभी बेंचों के मेज़ होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो मेज़ कुर्सियाँ हैं वे डेस्क हैं, इसलिए बेंच नहीं हैं: I अनुसरण करता है। बेंच केवल डेस्कों से अलग हैं; वे सभी मेज़ों के गैर-डेस्क भाग के अंदर आ सकती हैं, इसलिए II संभव है।","subtopic":"possibility"},
  {"id":"reason-syllogism-33","question":"Statements: All flowers are leaves. All leaves are stems. No stem is a root. Conclusions: I. No flower is a root. II. Some roots are not leaves.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Flowers ⊂ leaves ⊂ stems and stems are disjoint from roots, so no flower is a root (I). Every root lies outside stems and therefore outside leaves, so 'some roots are not leaves' is certain (II).","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"कथन: सभी फूल पत्तियाँ हैं। सभी पत्तियाँ तने हैं। कोई तना जड़ नहीं है। निष्कर्ष: I. कोई फूल जड़ नहीं है। II. कुछ जड़ें पत्तियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"फूल ⊂ पत्तियाँ ⊂ तने और तने जड़ों से अलग हैं, इसलिए कोई फूल जड़ नहीं है (I)। हर जड़ तनों से बाहर है और इसलिए पत्तियों से भी बाहर है, इसलिए ‘कुछ जड़ें पत्तियाँ नहीं हैं’ निश्चित है (II)।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-34","question":"Statements: Some cats are white. All white things are soft. Conclusions: I. Some cats are soft. II. Some soft things are not cats.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The white cats are soft, so I follows. Nothing says soft things extend beyond cats: the soft circle could be entirely cats, so II is not certain.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कथन: कुछ बिल्लियाँ सफ़ेद हैं। सभी सफ़ेद वस्तुएँ मुलायम हैं। निष्कर्ष: I. कुछ बिल्लियाँ मुलायम हैं। II. कुछ मुलायम वस्तुएँ बिल्लियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"सफ़ेद बिल्लियाँ मुलायम हैं, इसलिए I अनुसरण करता है। कहीं नहीं कहा गया कि मुलायम वस्तुएँ बिल्लियों से अधिक हैं: मुलायम वाला वृत्त पूरी तरह बिल्लियाँ ही हो सकता है, इसलिए II निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-35","question":"Statements: No A is B. Some B are C. All C are D. Conclusions: I. Some D are not A. II. Some A being C is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"C that are B are D and cannot be A, so some D are not A (I). A is disjoint only from B; the part of C outside B can overlap A, so II is possible.","difficulty":"hard","source":"IBPS PO · SSC CGL","questionHi":"कथन: कोई A, B नहीं है। कुछ B, C हैं। सभी C, D हैं। निष्कर्ष: I. कुछ D, A नहीं हैं। II. कुछ A के C होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो C, B हैं वे D हैं और A नहीं हो सकते, इसलिए कुछ D, A नहीं हैं (I)। A केवल B से अलग है; C का B से बाहर वाला भाग A से मेल खा सकता है, इसलिए II संभव है।","subtopic":"possibility"},
  {"id":"reason-syllogism-36","question":"Statements: Some M are N. All N are O. Some O are P. Conclusions: I. Some M are P. II. Some P are N.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"M reaches O only through N, and the P-part of O need not touch N or M at all. Neither conclusion is certain; both are mere possibilities, and they are not a complementary pair.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"कथन: कुछ M, N हैं। सभी N, O हैं। कुछ O, P हैं। निष्कर्ष: I. कुछ M, P हैं। II. कुछ P, N हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"M, O तक केवल N के माध्यम से पहुँचता है, और O का P वाला भाग N या M को छुए ही, यह आवश्यक नहीं। दोनों में से कोई भी निष्कर्ष निश्चित नहीं है; दोनों केवल संभावनाएँ हैं, और वे पूरक युग्म नहीं हैं।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-37","question":"Statements: All books are pages. Some pages are words. No word is a letter. Conclusions: I. Some books are words. II. No book is a word.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Books sit inside pages; the word-part of pages may or may not include books, so neither I nor II is certain. Since 'some books are words' and 'no book is a word' are complementary (same subject and predicate, some/no), one of them must hold: either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी किताबें पन्ने हैं। कुछ पन्ने शब्द हैं। कोई शब्द अक्षर नहीं है। निष्कर्ष: I. कुछ किताबें शब्द हैं। II. कोई किताब शब्द नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"किताबें पन्नों के अंदर हैं; पन्नों के शब्द वाले भाग में किताबें हो भी सकती हैं और नहीं भी, इसलिए न I निश्चित है और न II। चूँकि ‘कुछ किताबें शब्द हैं’ और ‘कोई किताब शब्द नहीं है’ पूरक हैं (एक ही उद्देश्य और विधेय, कुछ/कोई नहीं), इनमें से एक अवश्य सत्य होगा: I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-38","question":"Statements: Only a few mangoes are ripe. All ripe things are sweet. No sweet thing is sour. Conclusions: I. Some mangoes are not sour. II. All mangoes being sweet is a possibility. III. Some sour things are mangoes.","options":["Only I and II follow","Only I follows","Only II and III follow","All three follow"],"answer":0,"explanation":"'Only a few mangoes are ripe' = some mangoes are ripe and some are not. Ripe mangoes are sweet, hence not sour: I follows. The unripe mangoes can still be sweet, so all mangoes being sweet is possible: II follows. III is only a possibility, not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ आम पके हैं। सभी पकी वस्तुएँ मीठी हैं। कोई मीठी वस्तु खट्टी नहीं है। निष्कर्ष: I. कुछ आम खट्टे नहीं हैं। II. सभी आमों के मीठे होने की संभावना है। III. कुछ खट्टी वस्तुएँ आम हैं।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I अनुसरण करता है","केवल II और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"‘केवल कुछ आम पके हैं’ = कुछ आम पके हैं और कुछ आम नहीं पके हैं। पके आम मीठे हैं, इसलिए खट्टे नहीं हैं: I अनुसरण करता है। कच्चे आम फिर भी मीठे हो सकते हैं, इसलिए सभी आमों का मीठा होना संभव है: II अनुसरण करता है। III केवल एक संभावना है, निश्चित नहीं।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-39","question":"Statements: All red things are blue. No blue thing is green. Some green things are yellow. Conclusions: I. Some yellow things are not red. II. No red thing is green. III. Some blue things are yellow.","options":["Only II follows","Only I and II follow","Only I and III follow","All three follow"],"answer":1,"explanation":"Red ⊂ blue and blue is disjoint from green, so no red is green (II). The yellow things that are green are outside blue, hence not red, so some yellow are not red (I). Nothing forces blue and yellow to overlap, so III does not follow.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: सभी लाल वस्तुएँ नीली हैं। कोई नीली वस्तु हरी नहीं है। कुछ हरी वस्तुएँ पीली हैं। निष्कर्ष: I. कुछ पीली वस्तुएँ लाल नहीं हैं। II. कोई लाल वस्तु हरी नहीं है। III. कुछ नीली वस्तुएँ पीली हैं।","optionsHi":["केवल II अनुसरण करता है","केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"लाल ⊂ नीला और नीला हरे से अलग है, इसलिए कोई लाल वस्तु हरी नहीं है (II)। जो पीली वस्तुएँ हरी हैं वे नीले से बाहर हैं, इसलिए लाल नहीं हैं, अतः कुछ पीली वस्तुएँ लाल नहीं हैं (I)। नीले और पीले का मेल होना आवश्यक नहीं, इसलिए III अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-40","question":"Statements: Some pens are not pencils. All pencils are markers. Conclusions: I. Some pens are not markers. II. Some markers are pencils.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Pens that are not pencils may still be markers (markers extend beyond pencils), so I does not follow. Pencils lie inside markers, so some markers are pencils (II).","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"कथन: कुछ पेन पेंसिल नहीं हैं। सभी पेंसिलें मार्कर हैं। निष्कर्ष: I. कुछ पेन मार्कर नहीं हैं। II. कुछ मार्कर पेंसिलें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो पेन पेंसिल नहीं हैं वे फिर भी मार्कर हो सकते हैं (मार्कर पेंसिलों से अधिक हैं), इसलिए I अनुसरण नहीं करता। पेंसिलें मार्करों के अंदर हैं, इसलिए कुछ मार्कर पेंसिलें हैं (II)।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-41","question":"Statements: No cup is a glass. Some glasses are bottles. All bottles are jars. Conclusions: I. All jars being cups is a possibility. II. Some jars are not cups.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The bottles that are glasses are jars and cannot be cups, so some jars are definitely not cups (II). Those same jars make 'all jars are cups' impossible, so I does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कोई कप गिलास नहीं है। कुछ गिलास बोतलें हैं। सभी बोतलें जार हैं। निष्कर्ष: I. सभी जारों के कप होने की संभावना है। II. कुछ जार कप नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो बोतलें गिलास हैं वे जार हैं और कप नहीं हो सकतीं, इसलिए कुछ जार निश्चित रूप से कप नहीं हैं (II)। वही जार ‘सभी जार कप हैं’ को असंभव बना देते हैं, इसलिए I अनुसरण नहीं करता।","subtopic":"possibility"},
  {"id":"reason-syllogism-42","question":"Statements: All trains are buses. Some buses are cars. No car is a bike. Conclusions: I. Some trains being bikes is a possibility. II. Some buses being bikes is a possibility. III. No train is a car.","options":["Only I and III follow","Only II follows","Only I and II follow","All three follow"],"answer":2,"explanation":"Bikes are disjoint only from cars. Trains (inside buses) and buses can both overlap bikes in the non-car region, so I and II are possible. Trains could lie inside the car-part of buses, so III is not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी रेलगाड़ियाँ बसें हैं। कुछ बसें कारें हैं। कोई कार बाइक नहीं है। निष्कर्ष: I. कुछ रेलगाड़ियों के बाइक होने की संभावना है। II. कुछ बसों के बाइक होने की संभावना है। III. कोई रेलगाड़ी कार नहीं है।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल II अनुसरण करता है","केवल I और II अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"बाइक केवल कारों से अलग हैं। रेलगाड़ियाँ (बसों के अंदर) और बसें दोनों गैर-कार क्षेत्र में बाइक से मेल खा सकती हैं, इसलिए I और II संभव हैं। रेलगाड़ियाँ बसों के कार वाले भाग के अंदर हो सकती हैं, इसलिए III निश्चित नहीं है।","subtopic":"possibility"},
  {"id":"reason-syllogism-43","question":"Statements: Some roses are red. All red things are bright. No bright thing is dull. Conclusions: I. Some roses are dull. II. No rose is dull.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Red roses are bright and hence not dull, so 'some roses are not dull' is certain, but that is not a listed conclusion. Roses that are not red could be dull or not, so neither I nor II is certain; as a complementary some/no pair, either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ गुलाब लाल हैं। सभी लाल वस्तुएँ चमकीली हैं। कोई चमकीली वस्तु फीकी नहीं है। निष्कर्ष: I. कुछ गुलाब फीके हैं। II. कोई गुलाब फीका नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"लाल गुलाब चमकीले हैं और इसलिए फीके नहीं हैं, इसलिए ‘कुछ गुलाब फीके नहीं हैं’ निश्चित है, पर यह दिए गए निष्कर्षों में नहीं है। जो गुलाब लाल नहीं हैं वे फीके हो भी सकते हैं और नहीं भी, इसलिए न I निश्चित है और न II; कुछ/कोई नहीं के पूरक युग्म के रूप में I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-44","question":"Statements: All A are B. All B are C. Some C are D. Conclusions: I. Some D are A. II. No D is A. III. Some C are A.","options":["Only III follows","Only I and III follow","Only III and either I or II follow","Only II and III follow"],"answer":2,"explanation":"A ⊂ B ⊂ C, so some C are A (III). The D-part of C may or may not reach A, so neither I nor II is certain, but they are a complementary some/no pair, so one of them must hold: either I or II, together with III.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी A, B हैं। सभी B, C हैं। कुछ C, D हैं। निष्कर्ष: I. कुछ D, A हैं। II. कोई D, A नहीं है। III. कुछ C, A हैं।","optionsHi":["केवल III अनुसरण करता है","केवल I और III अनुसरण करते हैं","केवल III और I या II में से कोई एक अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"A ⊂ B ⊂ C, इसलिए कुछ C, A हैं (III)। C का D वाला भाग A तक पहुँच भी सकता है और नहीं भी, इसलिए न I निश्चित है और न II, परंतु वे कुछ/कोई नहीं का पूरक युग्म हैं, इसलिए उनमें से एक अवश्य सत्य होगा: III के साथ I या II में से कोई एक।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-45","question":"Statements: No X is Y. No Y is Z. Conclusions: I. No X is Z. II. Some Z are not Y.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Two negative statements give no definite link between X and Z: X could overlap Z, so I does not follow. 'No Y is Z' means every Z is outside Y, so some Z are not Y is certain (II).","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"कथन: कोई X, Y नहीं है। कोई Y, Z नहीं है। निष्कर्ष: I. कोई X, Z नहीं है। II. कुछ Z, Y नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"दो निषेधात्मक कथनों से X और Z के बीच कोई निश्चित संबंध नहीं बनता: X, Z से मेल खा सकता है, इसलिए I अनुसरण नहीं करता। ‘कोई Y, Z नहीं है’ का अर्थ है कि हर Z, Y से बाहर है, इसलिए ‘कुछ Z, Y नहीं हैं’ निश्चित है (II)।","subtopic":"two-statements"},
  {"id":"reason-syllogism-46","question":"Statements: Some A are B. Some B are C. Some C are D. Conclusions: I. Some A are D. II. Some A are not D. III. Some D being A is a possibility.","options":["Only III follows","Only III and either I or II follow","Neither follows","Only I and III follow"],"answer":1,"explanation":"A chain of 'some' statements gives no definite conclusion between A and D, so neither I nor II is certain; nothing prevents D overlapping A, so III follows. I ('some A are D') and II ('some A are not D') are complementary, so one of them must be true: III with either I or II.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ A, B हैं। कुछ B, C हैं। कुछ C, D हैं। निष्कर्ष: I. कुछ A, D हैं। II. कुछ A, D नहीं हैं। III. कुछ D के A होने की संभावना है।","optionsHi":["केवल III अनुसरण करता है","केवल III और I या II में से कोई एक अनुसरण करते हैं","कोई भी अनुसरण नहीं करता","केवल I और III अनुसरण करते हैं"],"explanationHi":"‘कुछ’ वाले कथनों की श्रृंखला से A और D के बीच कोई निश्चित निष्कर्ष नहीं निकलता, इसलिए न I निश्चित है और न II; D के A से मेल खाने में कोई बाधा नहीं है, इसलिए III अनुसरण करता है। I (‘कुछ A, D हैं’) और II (‘कुछ A, D नहीं हैं’) पूरक हैं, इसलिए उनमें से एक अवश्य सत्य होगा: III के साथ I या II में से कोई एक।","subtopic":"possibility"},
  {"id":"reason-syllogism-47","question":"Statements: All lamps are bulbs. Only a few bulbs are tubes. No tube is a fan. Conclusions: I. Some bulbs are not fans. II. Some lamps are not tubes. III. All lamps being fans is a possibility.","options":["Only I and II follow","Only I follows","All three follow","Only I and III follow"],"answer":3,"explanation":"Bulbs that are tubes cannot be fans, so I follows. Lamps may lie entirely inside the tube-part of bulbs, so II is not certain. Lamps may lie entirely in the non-tube part of bulbs, which fans can cover, so III is possible.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी लैंप बल्ब हैं। केवल कुछ बल्ब ट्यूब हैं। कोई ट्यूब पंखा नहीं है। निष्कर्ष: I. कुछ बल्ब पंखे नहीं हैं। II. कुछ लैंप ट्यूब नहीं हैं। III. सभी लैंपों के पंखे होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I अनुसरण करता है","तीनों अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"जो बल्ब ट्यूब हैं वे पंखे नहीं हो सकते, इसलिए I अनुसरण करता है। लैंप बल्बों के ट्यूब वाले भाग के पूरी तरह अंदर हो सकते हैं, इसलिए II निश्चित नहीं है। लैंप बल्बों के गैर-ट्यूब भाग में पूरी तरह हो सकते हैं, जिसे पंखे ढक सकते हैं, इसलिए III संभव है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-48","question":"Statements: All P are Q. No Q is R. All R are S. Conclusions: I. Some P are R. II. Some S are not Q. III. Some P are S.","options":["Only II follows","Only I and II follow","Only III follows","Only II and III follow"],"answer":0,"explanation":"P ⊂ Q and Q is disjoint from R, so I is definitely false. R lies inside S and outside Q, so some S (the R-part) are not Q: II follows. P could overlap the non-R part of S, but it need not, so III is only a possibility.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: सभी P, Q हैं। कोई Q, R नहीं है। सभी R, S हैं। निष्कर्ष: I. कुछ P, R हैं। II. कुछ S, Q नहीं हैं। III. कुछ P, S हैं।","optionsHi":["केवल II अनुसरण करता है","केवल I और II अनुसरण करते हैं","केवल III अनुसरण करता है","केवल II और III अनुसरण करते हैं"],"explanationHi":"P ⊂ Q और Q, R से अलग है, इसलिए I निश्चित रूप से असत्य है। R, S के अंदर और Q के बाहर है, इसलिए कुछ S (R वाला भाग) Q नहीं हैं: II अनुसरण करता है। P, S के गैर-R भाग से मेल खा सकता है, पर आवश्यक नहीं, इसलिए III केवल एक संभावना है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-49","question":"Statements: All singers are dancers. Some dancers are actors. Conclusions: I. Some actors are dancers. II. All dancers are singers.","options":["Only conclusion II follows","Only conclusion I follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"I is the converse of 'Some dancers are actors', so it follows. Singers sit inside dancers, but dancers can be bigger than singers, so II does not follow.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"कथन: सभी गायक नर्तक हैं। कुछ नर्तक अभिनेता हैं। निष्कर्ष: I. कुछ अभिनेता नर्तक हैं। II. सभी नर्तक गायक हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"I, ‘कुछ नर्तक अभिनेता हैं’ का उलटा है, इसलिए अनुसरण करता है। गायक नर्तकों के अंदर हैं, पर नर्तक गायकों से अधिक हो सकते हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-50","question":"Statements: All books are papers. All papers are trees. Conclusions: I. Some trees are books. II. All trees are papers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Venn: books ⊂ papers ⊂ trees. Books are trees, so some trees are books (I follows). Trees may be larger than papers, so II does not follow.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"कथन: सभी किताबें कागज़ हैं। सभी कागज़ पेड़ हैं। निष्कर्ष: I. कुछ पेड़ किताबें हैं। II. सभी पेड़ कागज़ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"वेन आरेख: किताबें ⊂ कागज़ ⊂ पेड़। किताबें पेड़ हैं, इसलिए कुछ पेड़ किताबें हैं (I अनुसरण करता है)। पेड़ कागज़ से बड़े हो सकते हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"two-statements"},
  {"id":"reason-syllogism-51","question":"Statements: Some doctors are engineers. All engineers are writers. Conclusions: I. Some writers are doctors. II. Some doctors are not writers.","options":["Only conclusion II follows","Either I or II follows","Both I and II follow","Only conclusion I follows"],"answer":3,"explanation":"The doctors who are engineers lie inside writers, so some writers are doctors (I). All doctors could also be writers, so II is not certain.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कुछ डॉक्टर इंजीनियर हैं। सभी इंजीनियर लेखक हैं। निष्कर्ष: I. कुछ लेखक डॉक्टर हैं। II. कुछ डॉक्टर लेखक नहीं हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"जो डॉक्टर इंजीनियर हैं वे लेखकों के अंदर हैं, इसलिए कुछ लेखक डॉक्टर हैं (I)। सभी डॉक्टर भी लेखक हो सकते हैं, इसलिए II निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-52","question":"Statements: All lions are animals. No animal is a plant. Conclusions: I. No lion is a plant. II. Some animals are lions.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Lions ⊂ animals and animals are disjoint from plants, so no lion is a plant (I). Since all lions are animals, some animals are lions (II).","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कथन: सभी शेर जानवर हैं। कोई जानवर पौधा नहीं है। निष्कर्ष: I. कोई शेर पौधा नहीं है। II. कुछ जानवर शेर हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"शेर ⊂ जानवर और जानवर पौधों से अलग हैं, इसलिए कोई शेर पौधा नहीं है (I)। चूँकि सभी शेर जानवर हैं, कुछ जानवर शेर हैं (II)।","subtopic":"two-statements"},
  {"id":"reason-syllogism-53","question":"Statements: Some phones are cameras. Some cameras are laptops. Conclusions: I. Some phones are laptops. II. No phone is a laptop.","options":["Neither I nor II follows","Either I or II follows","Only conclusion I follows","Both I and II follow"],"answer":1,"explanation":"Two 'some' statements give no definite link between phones and laptops, so neither is certain alone. But I ('some are') and II ('no') are a complementary pair about the same terms, so one of them must be true: either I or II.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: कुछ फ़ोन कैमरे हैं। कुछ कैमरे लैपटॉप हैं। निष्कर्ष: I. कुछ फ़ोन लैपटॉप हैं। II. कोई फ़ोन लैपटॉप नहीं है।","optionsHi":["न तो I और न ही II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"दो ‘कुछ’ वाले कथनों से फ़ोन और लैपटॉप के बीच कोई निश्चित संबंध नहीं बनता, इसलिए अकेले कोई भी निश्चित नहीं है। परंतु I (‘कुछ हैं’) और II (‘कोई नहीं’) समान पदों पर आधारित पूरक युग्म हैं, इसलिए उनमें से एक अवश्य सत्य होगा: I या II में से कोई एक।","subtopic":"two-statements"},
  {"id":"reason-syllogism-54","question":"Statements: All gold is metal. Some metals are costly. Conclusions: I. Some gold is costly. II. Some costly things are metals.","options":["Only conclusion II follows","Only conclusion I follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Gold sits inside metal, but the costly part of metal may lie outside gold, so I is not certain. II is the converse of 'Some metals are costly', so it follows.","difficulty":"moderate","source":"RRB NTPC · SSC CHSL","questionHi":"कथन: सभी सोना धातु है। कुछ धातुएँ महँगी हैं। निष्कर्ष: I. कुछ सोना महँगा है। II. कुछ महँगी वस्तुएँ धातुएँ हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"सोना धातु के अंदर है, पर धातु का महँगा भाग सोने से बाहर हो सकता है, इसलिए I निश्चित नहीं है। II, ‘कुछ धातुएँ महँगी हैं’ का उलटा है, इसलिए अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-55","question":"Statement: Only a few teachers are poets. Conclusions: I. Some teachers are not poets. II. Some poets are teachers.","options":["Only conclusion I follows","Only conclusion II follows","Neither I nor II follows","Both I and II follow"],"answer":3,"explanation":"'Only a few A are B' means some A are B and some A are not B. So some teachers are not poets (I) and, by conversion, some poets are teachers (II).","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ शिक्षक कवि हैं। निष्कर्ष: I. कुछ शिक्षक कवि नहीं हैं। II. कुछ कवि शिक्षक हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो I और न ही II अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"‘केवल कुछ A, B हैं’ का अर्थ है कि कुछ A, B हैं और कुछ A, B नहीं हैं। इसलिए कुछ शिक्षक कवि नहीं हैं (I) और परिवर्तन से कुछ कवि शिक्षक हैं (II)।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-56","question":"Statements: Some pens are blue. No blue thing is red. All red things are bright. Conclusions: I. Some pens are not red. II. Some bright things are not blue.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The pens that are blue cannot be red, so I follows. Red lies inside bright and is fully outside blue, so the red part of bright is not blue: II follows.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कुछ पेन नीले हैं। कोई नीली वस्तु लाल नहीं है। सभी लाल वस्तुएँ चमकीली हैं। निष्कर्ष: I. कुछ पेन लाल नहीं हैं। II. कुछ चमकीली वस्तुएँ नीली नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो पेन नीले हैं वे लाल नहीं हो सकते, इसलिए I अनुसरण करता है। लाल, चमकीले के अंदर है और नीले से पूरी तरह बाहर है, इसलिए चमकीले का लाल भाग नीला नहीं है: II अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-57","question":"Statements: All A are B. No C is B. Some D are C. Conclusions: I. Some D are not A. II. Some A are D.","options":["Only conclusion II follows","Only conclusion I follows","Both I and II follow","Either I or II follows"],"answer":1,"explanation":"The D that are C lie outside B, and A is inside B, so those D are not A: I follows. A and D need not meet, so II does not follow.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: सभी A, B हैं। कोई C, B नहीं है। कुछ D, C हैं। निष्कर्ष: I. कुछ D, A नहीं हैं। II. कुछ A, D हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","I और II दोनों अनुसरण करते हैं","I या II में से कोई एक अनुसरण करता है"],"explanationHi":"जो D, C हैं वे B से बाहर हैं, और A, B के अंदर है, इसलिए वे D, A नहीं हैं: I अनुसरण करता है। A और D का मिलना आवश्यक नहीं, इसलिए II अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-58","question":"Statements: Only a few cups are glasses. All glasses are mugs. Conclusions: I. All cups being mugs is a possibility. II. Some mugs are cups.","options":["Both I and II follow","Only conclusion I follows","Only conclusion II follows","Neither I nor II follows"],"answer":0,"explanation":"The cups that are glasses lie inside mugs, so some mugs are cups (II). The cups that are not glasses are free to fall inside mugs too, so 'all cups are mugs' is possible (I). Both follow.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ कप गिलास हैं। सभी गिलास मग हैं। निष्कर्ष: I. सभी कपों के मग होने की संभावना है। II. कुछ मग कप हैं।","optionsHi":["I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"जो कप गिलास हैं वे मगों के अंदर हैं, इसलिए कुछ मग कप हैं (II)। जो कप गिलास नहीं हैं वे भी मगों के अंदर आ सकते हैं, इसलिए ‘सभी कप मग हैं’ संभव है (I)। दोनों अनुसरण करते हैं।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-59","question":"Statements: No tree is a shrub. All shrubs are plants. Some plants are herbs. Conclusions: I. Some herbs being trees is a possibility. II. All shrubs being herbs is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Neither I nor II follows","Both I and II follow"],"answer":3,"explanation":"Trees are barred only from shrubs, so a tree can be a herb (I possible). Shrubs sit inside plants and nothing stops all of them lying in the herb part (II possible). Both follow.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कोई पेड़ झाड़ी नहीं है। सभी झाड़ियाँ पौधे हैं। कुछ पौधे जड़ी-बूटियाँ हैं। निष्कर्ष: I. कुछ जड़ी-बूटियों के पेड़ होने की संभावना है। II. सभी झाड़ियों के जड़ी-बूटी होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो I और न ही II अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"पेड़ केवल झाड़ियों से अलग हैं, इसलिए कोई पेड़ जड़ी-बूटी हो सकता है (I संभव है)। झाड़ियाँ पौधों के अंदर हैं और कुछ भी उन सबको जड़ी-बूटी वाले भाग में होने से नहीं रोकता (II संभव है)। दोनों अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-60","question":"Statements: Some keys are locks. All locks are doors. No door is a window. Conclusions: I. No key is a window. II. Some windows being keys is a possibility.","options":["Only conclusion I follows","Either I or II follows","Only conclusion II follows","Both I and II follow"],"answer":2,"explanation":"Keys that are locks are doors and so not windows, but keys outside locks are free to be windows. So I is not certain and II is a valid possibility.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कुछ चाबियाँ ताले हैं। सभी ताले दरवाज़े हैं। कोई दरवाज़ा खिड़की नहीं है। निष्कर्ष: I. कोई चाबी खिड़की नहीं है। II. कुछ खिड़कियों के चाबी होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"जो चाबियाँ ताले हैं वे दरवाज़े हैं और इसलिए खिड़की नहीं हैं, पर तालों से बाहर की चाबियाँ खिड़की हो सकती हैं। इसलिए I निश्चित नहीं है और II एक वैध संभावना है।","subtopic":"possibility"},
  {"id":"reason-syllogism-61","question":"Statements: All apples are fruits. Some fruits are sweet. No sweet thing is bitter. Conclusions: I. Some apples are sweet. II. No apple is bitter.","options":["Only conclusion I follows","Neither I nor II follows","Only conclusion II follows","Both I and II follow"],"answer":1,"explanation":"Apples sit inside fruits but may lie wholly outside the sweet part, so I is not certain. Apples outside 'sweet' can be bitter, so II is not certain either. Neither follows.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: सभी सेब फल हैं। कुछ फल मीठे हैं। कोई मीठी वस्तु कड़वी नहीं है। निष्कर्ष: I. कुछ सेब मीठे हैं। II. कोई सेब कड़वा नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"सेब फलों के अंदर हैं, पर पूरी तरह ‘मीठे’ भाग से बाहर हो सकते हैं, इसलिए I निश्चित नहीं है। ‘मीठे’ से बाहर के सेब कड़वे हो सकते हैं, इसलिए II भी निश्चित नहीं है। कोई भी अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-62","question":"Statements: No P is Q. All Q are R. All R are S. Conclusions: I. Some S are not P. II. No P is R.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Either I or II follows"],"answer":0,"explanation":"Q ⊂ R ⊂ S and Q is outside P, so the Q part of S is not P: I follows. P is barred only from Q, so P can overlap the rest of R; II does not follow.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कोई P, Q नहीं है। सभी Q, R हैं। सभी R, S हैं। निष्कर्ष: I. कुछ S, P नहीं हैं। II. कोई P, R नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","I या II में से कोई एक अनुसरण करता है"],"explanationHi":"Q ⊂ R ⊂ S और Q, P से बाहर है, इसलिए S का Q वाला भाग P नहीं है: I अनुसरण करता है। P केवल Q से अलग है, इसलिए P, R के शेष भाग से मेल खा सकता है; II अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-63","question":"Statements: Some ideas are plans. No plan is a dream. All dreams are goals. Conclusions: I. Some goals are not plans. II. Some ideas are not dreams. III. All ideas being goals is a possibility.","options":["Only I and II follow","Only II and III follow","Only I follows","All I, II and III follow"],"answer":3,"explanation":"Dreams ⊂ goals and dreams are outside plans, so some goals (the dreams) are not plans: I. The ideas that are plans cannot be dreams: II. Plans are barred only from dreams, so ideas (including idea-plans) can all lie in the non-dream part of goals: III possible. All follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ विचार योजनाएँ हैं। कोई योजना सपना नहीं है। सभी सपने लक्ष्य हैं। निष्कर्ष: I. कुछ लक्ष्य योजनाएँ नहीं हैं। II. कुछ विचार सपने नहीं हैं। III. सभी विचारों के लक्ष्य होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल I अनुसरण करता है","I, II और III सभी अनुसरण करते हैं"],"explanationHi":"सपने ⊂ लक्ष्य और सपने योजनाओं से बाहर हैं, इसलिए कुछ लक्ष्य (सपने) योजनाएँ नहीं हैं: I। जो विचार योजनाएँ हैं वे सपने नहीं हो सकते: II। योजनाएँ केवल सपनों से अलग हैं, इसलिए विचार (योजना वाले विचारों सहित) सभी लक्ष्यों के गैर-सपना भाग में आ सकते हैं: III संभव है। सभी अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-64","question":"Statements: All circles are squares. Only a few squares are triangles. No triangle is a line. Conclusions: I. Some squares are not lines. II. All circles being triangles is a possibility. III. Some circles are lines.","options":["Only I follows","Only II and III follow","Only I and II follow","All I, II and III follow"],"answer":2,"explanation":"The squares that are triangles cannot be lines: I. Circles can all fall in the triangle part of squares, as long as some squares stay outside triangles: II possible. Circles need not touch lines, so III is not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी वृत्त वर्ग हैं। केवल कुछ वर्ग त्रिभुज हैं। कोई त्रिभुज रेखा नहीं है। निष्कर्ष: I. कुछ वर्ग रेखाएँ नहीं हैं। II. सभी वृत्तों के त्रिभुज होने की संभावना है। III. कुछ वृत्त रेखाएँ हैं।","optionsHi":["केवल I अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","I, II और III सभी अनुसरण करते हैं"],"explanationHi":"जो वर्ग त्रिभुज हैं वे रेखाएँ नहीं हो सकते: I। वृत्त सभी वर्गों के त्रिभुज वाले भाग में आ सकते हैं, बशर्ते कुछ वर्ग त्रिभुजों से बाहर रहें: II संभव है। वृत्तों का रेखाओं से मिलना आवश्यक नहीं, इसलिए III निश्चित नहीं है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-65","question":"Statements: No man is perfect. Some perfect beings are gods. Conclusions: I. Some gods are not men. II. No god is a man. III. Some men being gods is a possibility.","options":["Only I and II follow","Only I and III follow","Only II follows","Only III follows"],"answer":1,"explanation":"The gods who are perfect cannot be men: I. Gods outside 'perfect' are free to be men, so II is not certain while III is a valid possibility.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कोई मनुष्य पूर्ण नहीं है। कुछ पूर्ण प्राणी देवता हैं। निष्कर्ष: I. कुछ देवता मनुष्य नहीं हैं। II. कोई देवता मनुष्य नहीं है। III. कुछ मनुष्यों के देवता होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल II अनुसरण करता है","केवल III अनुसरण करता है"],"explanationHi":"जो देवता पूर्ण हैं वे मनुष्य नहीं हो सकते: I। ‘पूर्ण’ से बाहर के देवता मनुष्य हो सकते हैं, इसलिए II निश्चित नहीं है जबकि III एक वैध संभावना है।","subtopic":"possibility"},
  {"id":"reason-syllogism-66","question":"Statements: All roads are paths. All paths are lanes. Some lanes are streets. No street is a highway. Conclusions: I. Some lanes are not highways. II. Some roads being streets is a possibility. III. All paths being highways is a possibility.","options":["All I, II and III follow","Only I and II follow","Only I and III follow","Only I follows"],"answer":0,"explanation":"The lanes that are streets are not highways: I. Roads ⊂ paths ⊂ lanes, and roads may overlap the street part: II possible. Paths may sit wholly in the non-street part of lanes and all be highways: III possible.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी सड़कें रास्ते हैं। सभी रास्ते पगडंडियाँ हैं। कुछ पगडंडियाँ गलियाँ हैं। कोई गली राजमार्ग नहीं है। निष्कर्ष: I. कुछ पगडंडियाँ राजमार्ग नहीं हैं। II. कुछ सड़कों के गली होने की संभावना है। III. सभी रास्तों के राजमार्ग होने की संभावना है।","optionsHi":["I, II और III सभी अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल I अनुसरण करता है"],"explanationHi":"जो पगडंडियाँ गलियाँ हैं वे राजमार्ग नहीं हैं: I। सड़कें ⊂ रास्ते ⊂ पगडंडियाँ, और सड़कें गली वाले भाग से मेल खा सकती हैं: II संभव है। रास्ते पगडंडियों के गैर-गली भाग में पूरी तरह हो सकते हैं और सब राजमार्ग हो सकते हैं: III संभव है।","subtopic":"possibility"},
  {"id":"reason-syllogism-67","question":"Statements: Some A are B. All B are C. Some C are D. No D is E. Conclusions: I. Some A are C. II. Some C are not E. III. Some A are not E.","options":["Only I follows","All I, II and III follow","Only II and III follow","Only I and II follow"],"answer":3,"explanation":"A–B lies inside C: I. The C that are D are outside E: II. But A (even A–B) may lie in the non-D part of C and be wholly E, so III is not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ A, B हैं। सभी B, C हैं। कुछ C, D हैं। कोई D, E नहीं है। निष्कर्ष: I. कुछ A, C हैं। II. कुछ C, E नहीं हैं। III. कुछ A, E नहीं हैं।","optionsHi":["केवल I अनुसरण करता है","I, II और III सभी अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं"],"explanationHi":"A–B वाला भाग C के अंदर है: I। जो C, D हैं वे E से बाहर हैं: II। परंतु A (A–B सहित) C के गैर-D भाग में हो सकता है और पूरी तरह E हो सकता है, इसलिए III निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-68","question":"Statements: All teachers are learners. No learner is lazy. Some lazy people are rich. Conclusions: I. Some rich people are not teachers. II. No teacher is lazy. III. Some learners are rich.","options":["Only II follows","All I, II and III follow","Only I and II follow","Only I and III follow"],"answer":2,"explanation":"Teachers ⊂ learners and learners are outside lazy, so no teacher is lazy: II. The rich who are lazy are outside learners, hence not teachers: I. Learners may or may not be rich, so III is only a possibility.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: सभी शिक्षक विद्यार्थी हैं। कोई विद्यार्थी आलसी नहीं है। कुछ आलसी लोग अमीर हैं। निष्कर्ष: I. कुछ अमीर लोग शिक्षक नहीं हैं। II. कोई शिक्षक आलसी नहीं है। III. कुछ विद्यार्थी अमीर हैं।","optionsHi":["केवल II अनुसरण करता है","I, II और III सभी अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"शिक्षक ⊂ विद्यार्थी और विद्यार्थी आलसी लोगों से बाहर हैं, इसलिए कोई शिक्षक आलसी नहीं है: II। जो अमीर लोग आलसी हैं वे विद्यार्थियों से बाहर हैं, इसलिए शिक्षक नहीं हैं: I। विद्यार्थी अमीर हो भी सकते हैं और नहीं भी, इसलिए III केवल एक संभावना है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-69","question":"Statements: Some birds are crows. All crows are black. Conclusions: I. Some birds are not black. II. All birds are black.","options":["Neither I nor II follows","Either I or II follows","Only conclusion II follows","Both I and II follow"],"answer":1,"explanation":"The crow-birds are black, but the other birds are undecided, so neither I nor II is definite. I ('some birds are not black') and II ('all birds are black') are exact opposites, so one must be true: either I or II.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ पक्षी कौए हैं। सभी कौए काले हैं। निष्कर्ष: I. कुछ पक्षी काले नहीं हैं। II. सभी पक्षी काले हैं।","optionsHi":["न तो I और न ही II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं"],"explanationHi":"कौए वाले पक्षी काले हैं, पर बाकी पक्षियों के बारे में कुछ तय नहीं है, इसलिए न I निश्चित है और न II। I (‘कुछ पक्षी काले नहीं हैं’) और II (‘सभी पक्षी काले हैं’) एक-दूसरे के ठीक विपरीत हैं, इसलिए एक अवश्य सत्य होगा: I या II में से कोई एक।","subtopic":"two-statements"},
  {"id":"reason-syllogism-70","question":"Statements: Only a few books are novels. No novel is a comic. All comics are magazines. Conclusions: I. Some books are not comics. II. All books being magazines is a possibility. III. Some magazines are not novels.","options":["All I, II and III follow","Only I and III follow","Only I and II follow","Only III follows"],"answer":0,"explanation":"The books that are novels are not comics: I. Novels are barred only from comics, so books (including novel-books) can all be magazines outside the comic part: II possible. Comics ⊂ magazines and comics are not novels: III.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ किताबें उपन्यास हैं। कोई उपन्यास कॉमिक नहीं है। सभी कॉमिक पत्रिकाएँ हैं। निष्कर्ष: I. कुछ किताबें कॉमिक नहीं हैं। II. सभी किताबों के पत्रिका होने की संभावना है। III. कुछ पत्रिकाएँ उपन्यास नहीं हैं।","optionsHi":["I, II और III सभी अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल III अनुसरण करता है"],"explanationHi":"जो किताबें उपन्यास हैं वे कॉमिक नहीं हैं: I। उपन्यास केवल कॉमिक से अलग हैं, इसलिए किताबें (उपन्यास वाली किताबों सहित) कॉमिक वाले भाग से बाहर सभी पत्रिकाएँ हो सकती हैं: II संभव है। कॉमिक ⊂ पत्रिकाएँ और कॉमिक उपन्यास नहीं हैं: III।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-71","question":"Statements: No pen is a pencil. No pencil is an eraser. Conclusions: I. Some pens are erasers. II. No pen is an eraser.","options":["Only conclusion II follows","Neither I nor II follows","Both I and II follow","Either I or II follows"],"answer":3,"explanation":"Two negative statements give no link between pens and erasers, so neither conclusion is certain on its own. But I ('some are') and II ('no') form a complementary pair, so either I or II follows.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: कोई पेन पेंसिल नहीं है। कोई पेंसिल रबर नहीं है। निष्कर्ष: I. कुछ पेन रबर हैं। II. कोई पेन रबर नहीं है।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","न तो I और न ही II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","I या II में से कोई एक अनुसरण करता है"],"explanationHi":"दो निषेधात्मक कथनों से पेन और रबर के बीच कोई संबंध नहीं बनता, इसलिए अकेले कोई भी निष्कर्ष निश्चित नहीं है। परंतु I (‘कुछ हैं’) और II (‘कोई नहीं’) एक पूरक युग्म हैं, इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-72","question":"Which pair of statements definitely leads to the conclusion 'Some cats are dogs'?","options":["All cats are animals; some animals are dogs","All dogs are pets; some pets are cats","Some cats are pets; all pets are dogs","No cat is a bird; some birds are dogs"],"answer":2,"explanation":"Some cats are pets and all pets lie inside dogs, so those cats are dogs. In the other pairs the middle term (animals, pets, birds) may connect to cats and dogs in different parts, so no definite link.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सा कथन-युग्म निश्चित रूप से निष्कर्ष ‘कुछ बिल्लियाँ कुत्ते हैं’ तक पहुँचाता है?","optionsHi":["सभी बिल्लियाँ जानवर हैं; कुछ जानवर कुत्ते हैं","सभी कुत्ते पालतू हैं; कुछ पालतू बिल्लियाँ हैं","कुछ बिल्लियाँ पालतू हैं; सभी पालतू कुत्ते हैं","कोई बिल्ली पक्षी नहीं है; कुछ पक्षी कुत्ते हैं"],"explanationHi":"कुछ बिल्लियाँ पालतू हैं और सभी पालतू कुत्तों के अंदर हैं, इसलिए वे बिल्लियाँ कुत्ते हैं। अन्य युग्मों में मध्य पद (जानवर, पालतू, पक्षी) बिल्लियों और कुत्तों से अलग-अलग भागों में जुड़ सकता है, इसलिए कोई निश्चित संबंध नहीं बनता।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-73","question":"Statements: All X are Y. Some Y are not Z. Conclusions: I. Some X are not Z. II. All X being Z is a possibility. III. Some Y are not X.","options":["Only I follows","Only II follows","Only II and III follow","Only I and III follow"],"answer":1,"explanation":"The Y that are not Z may lie outside X, so I is not certain and 'all X are Z' stays possible: II. X may be the whole of Y, so III is not certain either.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: सभी X, Y हैं। कुछ Y, Z नहीं हैं। निष्कर्ष: I. कुछ X, Z नहीं हैं। II. सभी X के Z होने की संभावना है। III. कुछ Y, X नहीं हैं।","optionsHi":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"जो Y, Z नहीं हैं वे X से बाहर हो सकते हैं, इसलिए I निश्चित नहीं है और ‘सभी X, Z हैं’ संभव बना रहता है: II। X पूरा Y भी हो सकता है, इसलिए III भी निश्चित नहीं है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-74","question":"Statement: Only doctors are surgeons. Conclusions: I. All surgeons are doctors. II. All doctors are surgeons.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"'Only doctors are surgeons' means every surgeon is a doctor, so I follows. It does not say every doctor is a surgeon, so II does not.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"कथन: केवल डॉक्टर सर्जन हैं। निष्कर्ष: I. सभी सर्जन डॉक्टर हैं। II. सभी डॉक्टर सर्जन हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘केवल डॉक्टर सर्जन हैं’ का अर्थ है कि हर सर्जन डॉक्टर है, इसलिए I अनुसरण करता है। यह नहीं कहा गया कि हर डॉक्टर सर्जन है, इसलिए II अनुसरण नहीं करता।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-75","question":"Statement: Not all birds can fly. Conclusions: I. No bird can fly. II. Some birds cannot fly.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither conclusion I nor II follows"],"answer":1,"explanation":"'Not all birds can fly' means at least some birds cannot fly, so II follows. It does not rule out that some birds fly, so I does not.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"कथन: हर पक्षी उड़ नहीं सकता। निष्कर्ष: I. कोई पक्षी उड़ नहीं सकता। II. कुछ पक्षी उड़ नहीं सकते।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘हर पक्षी उड़ नहीं सकता’ का अर्थ है कि कम से कम कुछ पक्षी उड़ नहीं सकते, इसलिए II अनुसरण करता है। यह इस बात को नकारता नहीं कि कुछ पक्षी उड़ते हैं, इसलिए I अनुसरण नहीं करता।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-76","question":"Statement: All engineers are graduates. Conclusions: I. Some graduates are engineers. II. Some engineers are graduates.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"From 'All engineers are graduates', 'Some engineers are graduates' follows directly, and its converse 'Some graduates are engineers' follows too.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: सभी इंजीनियर स्नातक हैं। निष्कर्ष: I. कुछ स्नातक इंजीनियर हैं। II. कुछ इंजीनियर स्नातक हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘सभी इंजीनियर स्नातक हैं’ से ‘कुछ इंजीनियर स्नातक हैं’ सीधे प्राप्त होता है, और इसका उलटा ‘कुछ स्नातक इंजीनियर हैं’ भी अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-77","question":"Statements: None but the brave deserve the fair. Rahul deserves the fair. Conclusions: I. All brave people deserve the fair. II. Rahul is brave.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"'None but the brave deserve the fair' means everyone who deserves the fair is brave. Rahul deserves the fair, so he is brave (II). It does not say every brave person deserves the fair (I).","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कथन: केवल बहादुर ही सुंदरी के योग्य होते हैं। राहुल सुंदरी के योग्य है। निष्कर्ष: I. सभी बहादुर लोग सुंदरी के योग्य हैं। II. राहुल बहादुर है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘केवल बहादुर ही सुंदरी के योग्य होते हैं’ का अर्थ है कि जो भी सुंदरी के योग्य है वह बहादुर है। राहुल सुंदरी के योग्य है, इसलिए वह बहादुर है (II)। यह नहीं कहा गया कि हर बहादुर व्यक्ति सुंदरी के योग्य है (I)।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-78","question":"Statements: Some pens are not costly. All useful things are costly. Conclusions: I. Some pens are not useful. II. Some costly things are useful.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Useful things lie wholly inside costly things, so the pens that are not costly cannot be useful: I follows. 'All useful things are costly' converts to 'Some costly things are useful': II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ पेन महँगे नहीं हैं। सभी उपयोगी वस्तुएँ महँगी हैं। निष्कर्ष: I. कुछ पेन उपयोगी नहीं हैं। II. कुछ महँगी वस्तुएँ उपयोगी हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"उपयोगी वस्तुएँ पूरी तरह महँगी वस्तुओं के अंदर हैं, इसलिए जो पेन महँगे नहीं हैं वे उपयोगी नहीं हो सकते: I अनुसरण करता है। ‘सभी उपयोगी वस्तुएँ महँगी हैं’ का परिवर्तन ‘कुछ महँगी वस्तुएँ उपयोगी हैं’ है: II अनुसरण करता है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-79","question":"Statements: Some actors are singers. No singer is a dancer. Which conclusion definitely follows?","options":["No actor is a dancer","Some dancers are actors","Some singers are dancers","Some actors are not dancers"],"answer":3,"explanation":"The actors who are singers cannot be dancers, so 'Some actors are not dancers' is certain. The other actors may or may not dance, so the first two are only possible, and the third contradicts the second statement.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ अभिनेता गायक हैं। कोई गायक नर्तक नहीं है। निम्नलिखित में से कौन-सा निष्कर्ष निश्चित रूप से अनुसरण करता है?","optionsHi":["कोई अभिनेता नर्तक नहीं है","कुछ नर्तक अभिनेता हैं","कुछ गायक नर्तक हैं","कुछ अभिनेता नर्तक नहीं हैं"],"explanationHi":"जो अभिनेता गायक हैं वे नर्तक नहीं हो सकते, इसलिए ‘कुछ अभिनेता नर्तक नहीं हैं’ निश्चित है। अन्य अभिनेता नाच भी सकते हैं और नहीं भी, इसलिए पहले दो केवल संभावनाएँ हैं, और तीसरा दूसरे कथन का खंडन करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-80","question":"Statements: Some cars are red. Some cars are not red. Conclusions: I. All cars being red is a possibility. II. Some red things are cars.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"'Some red things are cars' is the converse of 'Some cars are red', so II follows. I is ruled out by the second statement, since some cars are definitely not red.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: कुछ कारें लाल हैं। कुछ कारें लाल नहीं हैं। निष्कर्ष: I. सभी कारों के लाल होने की संभावना है। II. कुछ लाल वस्तुएँ कारें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘कुछ लाल वस्तुएँ कारें हैं’ ‘कुछ कारें लाल हैं’ का उलटा है, इसलिए II अनुसरण करता है। I दूसरे कथन से असंभव हो जाता है, क्योंकि कुछ कारें निश्चित रूप से लाल नहीं हैं।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-81","question":"Statements: At least some politicians are honest. All honest people are respected. Conclusions: I. Some politicians are respected. II. All politicians being honest is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The honest politicians are respected, so I follows. Nothing stops every politician from being honest, so II is a valid possibility.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कथन: कम से कम कुछ नेता ईमानदार हैं। सभी ईमानदार लोग सम्मानित हैं। निष्कर्ष: I. कुछ नेता सम्मानित हैं। II. सभी नेताओं के ईमानदार होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"ईमानदार नेता सम्मानित हैं, इसलिए I अनुसरण करता है। कुछ भी हर नेता को ईमानदार होने से नहीं रोकता, इसलिए II एक वैध संभावना है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-82","question":"Statements: No fish is a bird. No bird is a reptile. Conclusions: I. Some fish being reptiles is a possibility. II. No reptile is a fish.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Two negative statements give no definite link between fish and reptiles, so II does not follow. For the same reason a fish–reptile overlap cannot be ruled out, so I (a possibility) follows.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: कोई मछली पक्षी नहीं है। कोई पक्षी सरीसृप नहीं है। निष्कर्ष: I. कुछ मछलियों के सरीसृप होने की संभावना है। II. कोई सरीसृप मछली नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"दो निषेधात्मक कथनों से मछली और सरीसृप के बीच कोई निश्चित संबंध नहीं बनता, इसलिए II अनुसरण नहीं करता। इसी कारण मछली और सरीसृप के मेल को नकारा नहीं जा सकता, इसलिए I (एक संभावना) अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-83","question":"Statements: All A are B. Some B are not C. All C are D. Conclusions: I. Some D are not A. II. Some B are D. III. All A being C is a possibility.","options":["Only I follows","Only II follows","Only III follows","Only II and III follow"],"answer":2,"explanation":"All of D could lie inside A (with C inside D and A inside B), so I fails. B and D need not meet at all, so II fails. A can sit inside C while some other B stays outside C, so III is possible.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी A, B हैं। कुछ B, C नहीं हैं। सभी C, D हैं। निष्कर्ष: I. कुछ D, A नहीं हैं। II. कुछ B, D हैं। III. सभी A के C होने की संभावना है।","optionsHi":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","केवल III अनुसरण करता है","केवल II और III अनुसरण करते हैं"],"explanationHi":"सभी D, A के अंदर हो सकते हैं (C, D के अंदर और A, B के अंदर रहते हुए), इसलिए I असत्य हो सकता है। B और D का मिलना आवश्यक नहीं, इसलिए II अनुसरण नहीं करता। A, C के अंदर हो सकता है जबकि कोई अन्य B, C से बाहर रहे, इसलिए III संभव है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-84","question":"Statements: Only gold is yellow. Some ornaments are yellow. Conclusions: I. All gold is yellow. II. Some ornaments are gold.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"'Only gold is yellow' means every yellow thing is gold. The yellow ornaments are therefore gold, so II follows. It does not say all gold is yellow, so I does not.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल सोना पीला होता है। कुछ आभूषण पीले हैं। निष्कर्ष: I. सभी सोना पीला है। II. कुछ आभूषण सोना हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘केवल सोना पीला होता है’ का अर्थ है कि हर पीली वस्तु सोना है। इसलिए पीले आभूषण सोना हैं, अतः II अनुसरण करता है। यह नहीं कहा गया कि सारा सोना पीला है, इसलिए I अनुसरण नहीं करता।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-85","question":"Statements: All P are Q. Some R are not Q. Conclusions: I. Some R are not P. II. Some P are not R.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"P lies inside Q, so the R that lie outside Q are also outside P: I follows. All P may well be R, so II does not.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: सभी P, Q हैं। कुछ R, Q नहीं हैं। निष्कर्ष: I. कुछ R, P नहीं हैं। II. कुछ P, R नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"P, Q के अंदर है, इसलिए जो R, Q से बाहर हैं वे P से भी बाहर हैं: I अनुसरण करता है। सभी P, R भी हो सकते हैं, इसलिए II अनुसरण नहीं करता।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-86","question":"Statements: Many teachers are researchers. No researcher is idle. Conclusions: I. Some teachers are not idle. II. All idle people being teachers is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"'Many' is read as 'some'. The teachers who are researchers are not idle, so I follows. The idle people can all be teachers who are not researchers, so II is possible.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: बहुत से शिक्षक शोधकर्ता हैं। कोई शोधकर्ता निष्क्रिय नहीं है। निष्कर्ष: I. कुछ शिक्षक निष्क्रिय नहीं हैं। II. सभी निष्क्रिय लोगों के शिक्षक होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"‘बहुत से’ को ‘कुछ’ पढ़ा जाता है। जो शिक्षक शोधकर्ता हैं वे निष्क्रिय नहीं हैं, इसलिए I अनुसरण करता है। सभी निष्क्रिय लोग वे शिक्षक हो सकते हैं जो शोधकर्ता नहीं हैं, इसलिए II संभव है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-87","question":"Statements: All circles are triangles. All triangles are squares. Conclusions: I. All squares are circles. II. All circles are squares. III. Some squares are triangles. IV. All squares being circles is a possibility.","options":["Only II and III follow","Only II, III and IV follow","All four follow","Only II follows"],"answer":1,"explanation":"Circles ⊂ triangles ⊂ squares, so II and III follow. I is not certain, but if the three sets are equal it holds, so IV (a possibility) follows.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी वृत्त त्रिभुज हैं। सभी त्रिभुज वर्ग हैं। निष्कर्ष: I. सभी वर्ग वृत्त हैं। II. सभी वृत्त वर्ग हैं। III. कुछ वर्ग त्रिभुज हैं। IV. सभी वर्गों के वृत्त होने की संभावना है।","optionsHi":["केवल II और III अनुसरण करते हैं","केवल II, III और IV अनुसरण करते हैं","चारों अनुसरण करते हैं","केवल II अनुसरण करता है"],"explanationHi":"वृत्त ⊂ त्रिभुज ⊂ वर्ग, इसलिए II और III अनुसरण करते हैं। I निश्चित नहीं है, पर यदि तीनों समुच्चय बराबर हों तो यह सत्य होता है, इसलिए IV (संभावना) अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-88","question":"Statements: Some A are not B. Some B are not C. Conclusions: I. Some A are not C. II. Some C are not A.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"Two particular negative statements give no valid conclusion. A could lie wholly inside C, and C wholly inside A, so neither I nor II is certain.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: कुछ A, B नहीं हैं। कुछ B, C नहीं हैं। निष्कर्ष: I. कुछ A, C नहीं हैं। II. कुछ C, A नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I और II दोनों अनुसरण करते हैं","न तो I और न ही II अनुसरण करता है"],"explanationHi":"दो विशिष्ट निषेधात्मक कथनों से कोई वैध निष्कर्ष नहीं निकलता। A पूरी तरह C के अंदर हो सकता है, और C पूरी तरह A के अंदर, इसलिए न I निश्चित है और न II।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-89","question":"Which pair of statements definitely leads to the conclusion 'Some flowers are not red'?","options":["All flowers are plants; some plants are not red","Some red things are flowers; some flowers are roses","No red thing is a lily; some lilies are not flowers","Some flowers are roses; no rose is red"],"answer":3,"explanation":"The flowers that are roses cannot be red, so 'Some flowers are not red' is certain. In the other pairs every flower could still be red.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सा कथन-युग्म निश्चित रूप से निष्कर्ष ‘कुछ फूल लाल नहीं हैं’ तक पहुँचाता है?","optionsHi":["सभी फूल पौधे हैं; कुछ पौधे लाल नहीं हैं","कुछ लाल वस्तुएँ फूल हैं; कुछ फूल गुलाब हैं","कोई लाल वस्तु लिली नहीं है; कुछ लिली फूल नहीं हैं","कुछ फूल गुलाब हैं; कोई गुलाब लाल नहीं है"],"explanationHi":"जो फूल गुलाब हैं वे लाल नहीं हो सकते, इसलिए ‘कुछ फूल लाल नहीं हैं’ निश्चित है। अन्य युग्मों में हर फूल फिर भी लाल हो सकता है।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-90","question":"Statements: All A are B. All C are B. No B is D. Conclusions: I. No A is D. II. Some A are C. III. No C is D.","options":["Only I follows","Only I and III follow","Only III follows","All three follow"],"answer":1,"explanation":"A and C both lie inside B, and B shares nothing with D, so neither A nor C can be D: I and III follow. A and C may not overlap, so II does not.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"कथन: सभी A, B हैं। सभी C, B हैं। कोई B, D नहीं है। निष्कर्ष: I. कोई A, D नहीं है। II. कुछ A, C हैं। III. कोई C, D नहीं है।","optionsHi":["केवल I अनुसरण करता है","केवल I और III अनुसरण करते हैं","केवल III अनुसरण करता है","तीनों अनुसरण करते हैं"],"explanationHi":"A और C दोनों B के अंदर हैं, और B का D से कुछ भी साझा नहीं है, इसलिए न A, D हो सकता है और न C: I और III अनुसरण करते हैं। A और C का मेल न भी हो, इसलिए II अनुसरण नहीं करता।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-91","question":"Statements: Only a few doctors are surgeons. Only a few surgeons are professors. Conclusions: I. Some doctors are not surgeons. II. Some surgeons are professors. III. Some doctors are professors.","options":["Only I and II follow","Only I and III follow","Only II and III follow","All three follow"],"answer":0,"explanation":"'Only a few X are Y' means some X are Y and some X are not Y. So I and II follow directly. The professor-surgeons need not be doctors, so III is not certain.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कथन: केवल कुछ डॉक्टर सर्जन हैं। केवल कुछ सर्जन प्रोफ़ेसर हैं। निष्कर्ष: I. कुछ डॉक्टर सर्जन नहीं हैं। II. कुछ सर्जन प्रोफ़ेसर हैं। III. कुछ डॉक्टर प्रोफ़ेसर हैं।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"‘केवल कुछ X, Y हैं’ का अर्थ है कि कुछ X, Y हैं और कुछ X, Y नहीं हैं। इसलिए I और II सीधे अनुसरण करते हैं। जो सर्जन प्रोफ़ेसर हैं वे डॉक्टर हों, यह आवश्यक नहीं, इसलिए III निश्चित नहीं है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-92","question":"Statements: All P are Q. Some Q are R. No R is S. All S are T. Conclusions: I. Some T are not R. II. Some P being S is a possibility. III. Some Q are not S.","options":["Only I and II follow","Only I and III follow","Only II and III follow","All I, II and III follow"],"answer":3,"explanation":"I: S lies inside T and outside R, so those T are not R. III: the Q that are R cannot be S. II: nothing forbids a P that is also S, so the possibility holds. All three follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी P, Q हैं। कुछ Q, R हैं। कोई R, S नहीं है। सभी S, T हैं। निष्कर्ष: I. कुछ T, R नहीं हैं। II. कुछ P के S होने की संभावना है। III. कुछ Q, S नहीं हैं।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","I, II और III सभी अनुसरण करते हैं"],"explanationHi":"I: S, T के अंदर और R के बाहर है, इसलिए वे T, R नहीं हैं। III: जो Q, R हैं वे S नहीं हो सकते। II: कुछ भी किसी P को S होने से नहीं रोकता, इसलिए संभावना बनी रहती है। तीनों अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-93","question":"Statements: Some coins are not gold. All gold is precious. No precious thing is cheap. Conclusions: I. Some coins are not cheap. II. All coins being precious is a possibility. III. Some precious things are not cheap.","options":["Only I follows","Only II and III follow","Only I and III follow","All three follow"],"answer":1,"explanation":"III: gold exists, is precious and is not cheap. II: the non-gold coins could still be precious. I fails: the coins could all be non-gold and cheap without breaking any statement.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ सिक्के सोना नहीं हैं। सारा सोना कीमती है। कोई कीमती वस्तु सस्ती नहीं है। निष्कर्ष: I. कुछ सिक्के सस्ते नहीं हैं। II. सभी सिक्कों के कीमती होने की संभावना है। III. कुछ कीमती वस्तुएँ सस्ती नहीं हैं।","optionsHi":["केवल I अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"III: सोना है, कीमती है और सस्ता नहीं है। II: जो सिक्के सोना नहीं हैं वे भी कीमती हो सकते हैं। I असत्य हो सकता है: सिक्के सब गैर-सोना और सस्ते हो सकते हैं, और किसी कथन का उल्लंघन नहीं होता।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-94","question":"Statements: All A are B. Some B are C. Conclusions: I. Some A are not C. II. All A are C.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Neither follows by itself, since A may or may not lie inside C. But I and II are exact opposites (a 'some … not' and an 'all' on the same terms), so one of them must be true: Either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी A, B हैं। कुछ B, C हैं। निष्कर्ष: I. कुछ A, C नहीं हैं। II. सभी A, C हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"अकेले कोई भी अनुसरण नहीं करता, क्योंकि A, C के अंदर हो भी सकता है और नहीं भी। परंतु I और II ठीक विपरीत हैं (समान पदों पर ‘कुछ … नहीं’ और ‘सभी’), इसलिए उनमें से एक अवश्य सत्य होगा: I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-95","question":"Statements: Some boys are tall. Some tall people are smart. Conclusions: I. Some boys are smart. II. Some boys are not smart.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":3,"explanation":"Neither follows. 'Either' would need the two to be a complementary pair, but here both could be true together (some boys smart, others not), so they are not opposites. Answer: neither.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ लड़के लंबे हैं। कुछ लंबे लोग स्मार्ट हैं। निष्कर्ष: I. कुछ लड़के स्मार्ट हैं। II. कुछ लड़के स्मार्ट नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","I या II में से कोई एक अनुसरण करता है","न तो I और न ही II अनुसरण करता है"],"explanationHi":"कोई भी अनुसरण नहीं करता। ‘I या II’ तभी होता जब दोनों पूरक युग्म होते, पर यहाँ दोनों एक साथ सत्य हो सकते हैं (कुछ लड़के स्मार्ट, कुछ नहीं), इसलिए वे विपरीत नहीं हैं। उत्तर: कोई भी नहीं।","subtopic":"two-statements"},
  {"id":"reason-syllogism-96","question":"Statements: All hills are mountains. No mountain is a valley. Some valleys are rivers. All rivers are streams. Conclusions: I. Some streams are not hills. II. No hill is a river. III. Some streams are valleys.","options":["Only I and II follow","Only I and III follow","Only II and III follow","All three follow"],"answer":1,"explanation":"The valley-rivers are streams (III), and being valleys they are not mountains, hence not hills (I). Rivers that are not valleys may be hills, so II is not certain.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"कथन: सभी पहाड़ियाँ पर्वत हैं। कोई पर्वत घाटी नहीं है। कुछ घाटियाँ नदियाँ हैं। सभी नदियाँ धाराएँ हैं। निष्कर्ष: I. कुछ धाराएँ पहाड़ियाँ नहीं हैं। II. कोई पहाड़ी नदी नहीं है। III. कुछ धाराएँ घाटियाँ हैं।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"जो नदियाँ घाटियाँ हैं वे धाराएँ हैं (III), और घाटियाँ होने के कारण वे पर्वत नहीं हैं, इसलिए पहाड़ियाँ भी नहीं हैं (I)। जो नदियाँ घाटियाँ नहीं हैं वे पहाड़ियाँ हो सकती हैं, इसलिए II निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-97","question":"Statement: All teachers are punctual. Which additional statement, together with it, makes the conclusion 'No teacher is lazy' definitely true?","options":["All lazy people are punctual","Some punctual people are not lazy","No punctual person is lazy","Some lazy people are not teachers"],"answer":2,"explanation":"If no punctual person is lazy, then teachers, who all lie inside 'punctual', cannot be lazy. The other options leave room for a lazy teacher.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी शिक्षक समय के पाबंद हैं। इसके साथ कौन-सा अतिरिक्त कथन निष्कर्ष ‘कोई शिक्षक आलसी नहीं है’ को निश्चित रूप से सत्य बनाता है?","optionsHi":["सभी आलसी लोग समय के पाबंद हैं","कुछ समय के पाबंद लोग आलसी नहीं हैं","कोई समय का पाबंद व्यक्ति आलसी नहीं है","कुछ आलसी लोग शिक्षक नहीं हैं"],"explanationHi":"यदि कोई समय का पाबंद व्यक्ति आलसी नहीं है, तो शिक्षक, जो सभी ‘समय के पाबंद’ के अंदर हैं, आलसी नहीं हो सकते। अन्य विकल्प किसी आलसी शिक्षक की गुंजाइश छोड़ देते हैं।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-98","question":"Statements: Some doors are windows. All windows are walls. No wall is a roof. Some roofs are floors. Conclusions: I. Some floors are not walls. II. Some doors are not roofs. III. Some floors being doors is a possibility. IV. All windows being floors is a possibility.","options":["Only I and II follow","Only I, II and III follow","All four follow","Only II and IV follow"],"answer":2,"explanation":"I: roof-floors are not walls. II: door-windows are walls, hence not roofs. III: a door outside the windows can be a floor. IV: floors may cover all of the windows (inside the walls, away from the roofs). All four follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ दरवाज़े खिड़कियाँ हैं। सभी खिड़कियाँ दीवारें हैं। कोई दीवार छत नहीं है। कुछ छतें फ़र्श हैं। निष्कर्ष: I. कुछ फ़र्श दीवारें नहीं हैं। II. कुछ दरवाज़े छतें नहीं हैं। III. कुछ फ़र्शों के दरवाज़े होने की संभावना है। IV. सभी खिड़कियों के फ़र्श होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I, II और III अनुसरण करते हैं","चारों अनुसरण करते हैं","केवल II और IV अनुसरण करते हैं"],"explanationHi":"I: जो फ़र्श छतें हैं वे दीवारें नहीं हैं। II: जो दरवाज़े खिड़कियाँ हैं वे दीवारें हैं, इसलिए छतें नहीं हैं। III: खिड़कियों से बाहर का कोई दरवाज़ा फ़र्श हो सकता है। IV: फ़र्श सभी खिड़कियों को ढक सकते हैं (दीवारों के अंदर, छतों से दूर)। चारों अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-99","question":"Statements: No A is B. Some B are C. Some C are D. Conclusions: I. Some C are not A. II. Some D are not A. III. All D being B is a possibility.","options":["Only I and III follow","Only I follows","Only I and II follow","Only II and III follow"],"answer":0,"explanation":"I: the C that are B cannot be A. II fails: D could lie wholly inside A (meeting C outside B). III: D can lie wholly inside B, overlapping C there. So I and III.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कोई A, B नहीं है। कुछ B, C हैं। कुछ C, D हैं। निष्कर्ष: I. कुछ C, A नहीं हैं। II. कुछ D, A नहीं हैं। III. सभी D के B होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल I अनुसरण करता है","केवल I और II अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I: जो C, B हैं वे A नहीं हो सकते। II असत्य हो सकता है: D पूरी तरह A के अंदर हो सकता है (C से B के बाहर मिलते हुए)। III: D पूरी तरह B के अंदर हो सकता है और वहीं C से मेल खा सकता है। इसलिए I और III।","subtopic":"possibility"},
  {"id":"reason-syllogism-100","question":"Statement: All that glitters is not gold. Conclusions: I. Some glittering things are not gold. II. No glittering thing is gold. III. Some glittering things being gold is a possibility.","options":["Only I follows","Only II follows","Only II and III follow","Only I and III follow"],"answer":3,"explanation":"The proverb means 'not everything that glitters is gold', i.e. some glittering things are not gold (I). It does not say none is gold, so II fails and the possibility in III stays open.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"कथन: हर चमकती चीज़ सोना नहीं होती। निष्कर्ष: I. कुछ चमकती चीज़ें सोना नहीं हैं। II. कोई चमकती चीज़ सोना नहीं है। III. कुछ चमकती चीज़ों के सोना होने की संभावना है।","optionsHi":["केवल I अनुसरण करता है","केवल II अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"इस कहावत का अर्थ है ‘हर चमकती चीज़ सोना नहीं होती’, यानी कुछ चमकती चीज़ें सोना नहीं हैं (I)। यह नहीं कहती कि कोई भी सोना नहीं है, इसलिए II अनुसरण नहीं करता और III की संभावना खुली रहती है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-101","question":"Statements: Some X are Y. No Y is Z. All Z are X. Conclusions: I. Some X are not Z. II. Some X are not Y. III. Some Y are Z.","options":["Only I follows","Only I and II follow","Only II and III follow","All three follow"],"answer":1,"explanation":"I: the X that are Y cannot be Z. II: Z lies inside X and outside Y, so those X are not Y. III directly contradicts 'No Y is Z'.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कुछ X, Y हैं। कोई Y, Z नहीं है। सभी Z, X हैं। निष्कर्ष: I. कुछ X, Z नहीं हैं। II. कुछ X, Y नहीं हैं। III. कुछ Y, Z हैं।","optionsHi":["केवल I अनुसरण करता है","केवल I और II अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","तीनों अनुसरण करते हैं"],"explanationHi":"I: जो X, Y हैं वे Z नहीं हो सकते। II: Z, X के अंदर और Y के बाहर है, इसलिए वे X, Y नहीं हैं। III सीधे ‘कोई Y, Z नहीं है’ का खंडन करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-102","question":"Statements: All mangoes are fruits. Only fruits are sweet. Conclusions: I. All sweet things are fruits. II. Some sweet things are mangoes. III. All mangoes being sweet is a possibility.","options":["Only I and III follow","Only I and II follow","Only II follows","All three follow"],"answer":0,"explanation":"'Only fruits are sweet' means all sweet things are fruits (I). Mangoes and sweet things both sit inside fruits but need not meet, so II fails, while III remains possible.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: सभी आम फल हैं। केवल फल ही मीठे होते हैं। निष्कर्ष: I. सभी मीठी वस्तुएँ फल हैं। II. कुछ मीठी वस्तुएँ आम हैं। III. सभी आमों के मीठे होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल II अनुसरण करता है","तीनों अनुसरण करते हैं"],"explanationHi":"‘केवल फल ही मीठे होते हैं’ का अर्थ है कि सभी मीठी वस्तुएँ फल हैं (I)। आम और मीठी वस्तुएँ दोनों फलों के अंदर हैं, पर उनका मिलना आवश्यक नहीं, इसलिए II अनुसरण नहीं करता, जबकि III संभव बना रहता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-103","question":"Statements: No P is Q. All Q are R. Some R are S. No S is T. Conclusions: I. Some R are not P. II. Some R are not T. III. All P being S is a possibility.","options":["Only I and II follow","Only II and III follow","All three follow","Only I follows"],"answer":2,"explanation":"I: the R that are Q are not P. II: the R that are S are not T. III: P only has to avoid Q, so it can lie wholly inside S. All three follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"कथन: कोई P, Q नहीं है। सभी Q, R हैं। कुछ R, S हैं। कोई S, T नहीं है। निष्कर्ष: I. कुछ R, P नहीं हैं। II. कुछ R, T नहीं हैं। III. सभी P के S होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","तीनों अनुसरण करते हैं","केवल I अनुसरण करता है"],"explanationHi":"I: जो R, Q हैं वे P नहीं हैं। II: जो R, S हैं वे T नहीं हैं। III: P को केवल Q से बचना है, इसलिए वह पूरी तरह S के अंदर हो सकता है। तीनों अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-104","question":"Statements: Some boxes are not pens. Some pens are bags. Conclusions: I. Some bags are pens. II. Some bags are not boxes.","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows"],"answer":0,"explanation":"I: follows from 'Some pens are bags'. II: all bags could be boxes without breaking any statement, so it is not definite.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ डिब्बे पेन नहीं हैं। कुछ पेन थैले हैं। निष्कर्ष: I. कुछ थैले पेन हैं। II. कुछ थैले डिब्बे नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: ‘कुछ पेन थैले हैं’ से अनुसरण करता है। II: सभी थैले डिब्बे हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-105","question":"Statements: All rats are cats. All rats are bats. Conclusions: I. Some rats are bats. II. Some bats are rats.","options":["Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows","Only conclusion I follows"],"answer":1,"explanation":"I: follows from 'All rats are bats'. II: follows from 'All rats are bats'.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी चूहे बिल्लियाँ हैं। सभी चूहे चमगादड़ हैं। निष्कर्ष: I. कुछ चूहे चमगादड़ हैं। II. कुछ चमगादड़ चूहे हैं।","optionsHi":["निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I: ‘सभी चूहे चमगादड़ हैं’ से अनुसरण करता है। II: ‘सभी चूहे चमगादड़ हैं’ से अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-106","question":"Statements: Some teachers are dancers. No singers are dancers. Conclusions: I. Some singers are not teachers. II. Some dancers are not singers.","options":["Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":2,"explanation":"I: all singers could be teachers without breaking any statement, so it is not definite. II: follows from 'No singers are dancers'.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ शिक्षक नर्तक हैं। कोई गायक नर्तक नहीं है। निष्कर्ष: I. कुछ गायक शिक्षक नहीं हैं। II. कुछ नर्तक गायक नहीं हैं।","optionsHi":["निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: सभी गायक शिक्षक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘कोई गायक नर्तक नहीं है’ से अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-107","question":"Statements: Some pilots are lawyers. All pilots are writers. Conclusions: I. Some lawyers are not pilots. II. All writers are lawyers.","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I: all lawyers could be pilots without breaking any statement, so it is not definite. II: some writers could lie outside lawyers without breaking any statement, so it is not definite.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ पायलट वकील हैं। सभी पायलट लेखक हैं। निष्कर्ष: I. कुछ वकील पायलट नहीं हैं। II. सभी लेखक वकील हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: सभी वकील पायलट हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ लेखक वकीलों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-108","question":"Statements: Some planets are stars. Some planets are moons. Conclusions: I. Some moons are planets. II. All moons are stars.","options":["Only conclusion I follows","Only conclusion II follows","Neither conclusion I nor II follows","Both conclusions I and II follow"],"answer":0,"explanation":"I: follows from 'Some planets are moons'. II: some moons could lie outside stars without breaking any statement, so it is not definite.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ ग्रह तारे हैं। कुछ ग्रह चंद्रमा हैं। निष्कर्ष: I. कुछ चंद्रमा ग्रह हैं। II. सभी चंद्रमा तारे हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: ‘कुछ ग्रह चंद्रमा हैं’ से अनुसरण करता है। II: कुछ चंद्रमा तारों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-109","question":"Statements: Some tablets are watches. All laptops are watches. Conclusions: I. No laptops are tablets. II. Some laptops are tablets.","options":["Both conclusions I and II follow","Either conclusion I or II follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":1,"explanation":"I: some laptops could be tablets without breaking any statement, so it is not definite. II: laptops and tablets could have nothing in common without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ टैबलेट घड़ियाँ हैं। सभी लैपटॉप घड़ियाँ हैं। निष्कर्ष: I. कोई लैपटॉप टैबलेट नहीं है। II. कुछ लैपटॉप टैबलेट हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: कुछ लैपटॉप टैबलेट हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: लैपटॉप और टैबलेट में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-110","question":"Statements: All singers are doctors. Some singers are teachers. Conclusions: I. All singers are teachers. II. Some doctors are singers.","options":["Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows","Either conclusion I or II follows"],"answer":2,"explanation":"I: some singers could lie outside teachers without breaking any statement, so it is not definite. II: follows from 'All singers are doctors'.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी गायक डॉक्टर हैं। कुछ गायक शिक्षक हैं। निष्कर्ष: I. सभी गायक शिक्षक हैं। II. कुछ डॉक्टर गायक हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है"],"explanationHi":"I: कुछ गायक शिक्षकों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी गायक डॉक्टर हैं’ से अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-111","question":"Statements: Only a few writers are pilots. All actors are writers. Conclusions: I. Some actors are writers. II. Some writers are pilots.","options":["Only conclusion II follows","Neither conclusion I nor II follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":3,"explanation":"I: follows from 'All actors are writers'. II: follows from 'Only a few writers are pilots'.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: केवल कुछ लेखक पायलट हैं। सभी अभिनेता लेखक हैं। निष्कर्ष: I. कुछ अभिनेता लेखक हैं। II. कुछ लेखक पायलट हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: ‘सभी अभिनेता लेखक हैं’ से अनुसरण करता है। II: ‘केवल कुछ लेखक पायलट हैं’ से अनुसरण करता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-112","question":"Statements: Some seas are lakes. All rivers are seas. Conclusions: I. No lakes are rivers. II. Some rivers are lakes.","options":["Neither conclusion I nor II follows","Either conclusion I or II follows","Only conclusion II follows","Both conclusions I and II follow"],"answer":0,"explanation":"I: some lakes could be rivers without breaking any statement, so it is not definite. II: rivers and lakes could have nothing in common without breaking any statement, so it is not definite.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ समुद्र झीलें हैं। सभी नदियाँ समुद्र हैं। निष्कर्ष: I. कोई झील नदी नहीं है। II. कुछ नदियाँ झीलें हैं।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: कुछ झीलें नदियाँ हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: नदियों और झीलों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-113","question":"Statements: Some lilies are roses. Some lilies are tulips. Conclusions: I. Some tulips are lilies. II. All roses are tulips.","options":["Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":1,"explanation":"I: follows from 'Some lilies are tulips'. II: some roses could lie outside tulips without breaking any statement, so it is not definite.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ लिली गुलाब हैं। कुछ लिली ट्यूलिप हैं। निष्कर्ष: I. कुछ ट्यूलिप लिली हैं। II. सभी गुलाब ट्यूलिप हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: ‘कुछ लिली ट्यूलिप हैं’ से अनुसरण करता है। II: कुछ गुलाब ट्यूलिपों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-114","question":"Statements: No tables are beds. No tables are chairs. Conclusions: I. Some beds are chairs. II. No beds are chairs.","options":["Neither conclusion I nor II follows","Only conclusion II follows","Either conclusion I or II follows","Only conclusion I follows"],"answer":2,"explanation":"I: beds and chairs could have nothing in common without breaking any statement, so it is not definite. II: some beds could be chairs without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई मेज़ पलंग नहीं है। कोई मेज़ कुर्सी नहीं है। निष्कर्ष: I. कुछ पलंग कुर्सियाँ हैं। II. कोई पलंग कुर्सी नहीं है।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I: पलंग और कुर्सियों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ पलंग कुर्सियाँ हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-115","question":"Statements: Some moons are planets. No moons are stars. Conclusions: I. All moons are planets. II. Some planets are stars.","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I: some moons could lie outside planets without breaking any statement, so it is not definite. II: planets and stars could have nothing in common without breaking any statement, so it is not definite.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ चंद्रमा ग्रह हैं। कोई चंद्रमा तारा नहीं है। निष्कर्ष: I. सभी चंद्रमा ग्रह हैं। II. कुछ ग्रह तारे हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: कुछ चंद्रमा ग्रहों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ग्रहों और तारों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-116","question":"Statements: Only a few bowls are plates. All cups are plates. Conclusions: I. Some bowls are not plates. II. Some plates are bowls.","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":0,"explanation":"I: follows from 'Only a few bowls are plates'. II: follows from 'Only a few bowls are plates'.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: केवल कुछ कटोरे प्लेटें हैं। सभी कप प्लेटें हैं। निष्कर्ष: I. कुछ कटोरे प्लेटें नहीं हैं। II. कुछ प्लेटें कटोरे हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: ‘केवल कुछ कटोरे प्लेटें हैं’ से अनुसरण करता है। II: ‘केवल कुछ कटोरे प्लेटें हैं’ से अनुसरण करता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-117","question":"Statements: Some beds are chairs. Only a few tables are chairs. No tables are sofas. Conclusions: I. Some beds being sofas is a possibility. II. Some chairs are not beds.","options":["Only conclusion II follows","Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow"],"answer":1,"explanation":"I: a diagram in which some beds are sofas fits all the statements, so as a possibility it follows. II: all chairs could be beds without breaking any statement, so it is not definite.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ पलंग कुर्सियाँ हैं। केवल कुछ मेज़ कुर्सियाँ हैं। कोई मेज़ सोफ़ा नहीं है। निष्कर्ष: I. कुछ पलंगों के सोफ़े होने की संभावना है। II. कुछ कुर्सियाँ पलंग नहीं हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: ऐसा आरेख जिसमें कुछ पलंग सोफ़े हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: सभी कुर्सियाँ पलंग हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-118","question":"Statements: No jeans are caps. All caps are socks. Some socks are shirts. Conclusions: I. Some jeans are shirts. II. Some caps are socks.","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":2,"explanation":"I: jeans and shirts could have nothing in common without breaking any statement, so it is not definite. II: follows from 'All caps are socks'.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई जीन्स कैप नहीं है। सभी कैप मोज़े हैं। कुछ मोज़े कमीज़ें हैं। निष्कर्ष: I. कुछ जीन्स कमीज़ें हैं। II. कुछ कैप मोज़े हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: जीन्स और कमीज़ों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी कैप मोज़े हैं’ से अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-119","question":"Statements: All pilots are writers. All lawyers are writers. No lawyers are actors. Conclusions: I. Some pilots are lawyers. II. No pilots are lawyers.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Either conclusion I or II follows"],"answer":3,"explanation":"I: pilots and lawyers could have nothing in common without breaking any statement, so it is not definite. II: some pilots could be lawyers without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी पायलट लेखक हैं। सभी वकील लेखक हैं। कोई वकील अभिनेता नहीं है। निष्कर्ष: I. कुछ पायलट वकील हैं। II. कोई पायलट वकील नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है"],"explanationHi":"I: पायलट और वकीलों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ पायलट वकील हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-120","question":"Statements: All coins are notes. All notes are cheques. No cheques are cards. Conclusions: I. No cheques being notes is a possibility. II. All notes being cards is a possibility.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows"],"answer":0,"explanation":"I: 'All notes are cheques' rules this out, so it does not follow. II: 'All notes are cheques' and 'No cheques are cards' rule this out, so it does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी सिक्के नोट हैं। सभी नोट चेक हैं। कोई चेक कार्ड नहीं है। निष्कर्ष: I. किसी चेक के नोट न होने की संभावना है। II. सभी नोटों के कार्ड होने की संभावना है।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: ‘सभी नोट चेक हैं’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। II: ‘सभी नोट चेक हैं’ और ‘कोई चेक कार्ड नहीं है’ इसे असंभव बना देते हैं, इसलिए यह अनुसरण नहीं करता।","subtopic":"possibility"},
  {"id":"reason-syllogism-121","question":"Statements: All trucks are cars. All trains are trucks. No trains are buses. Conclusions: I. Some buses being cars is a possibility. II. No buses being trucks is a possibility.","options":["Only conclusion I follows","Both conclusions I and II follow","Only conclusion II follows","Either conclusion I or II follows"],"answer":1,"explanation":"I: a diagram in which some buses are cars fits all the statements, so as a possibility it follows. II: a diagram in which no buses are trucks fits all the statements, so as a possibility it follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी ट्रक कारें हैं। सभी रेलगाड़ियाँ ट्रक हैं। कोई रेलगाड़ी बस नहीं है। निष्कर्ष: I. कुछ बसों के कारें होने की संभावना है। II. किसी बस के ट्रक न होने की संभावना है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें कुछ बसें कारें हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ऐसा आरेख जिसमें कोई बस ट्रक न हो, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-122","question":"Statements: No sofas are tables. No beds are tables. All beds are chairs. Conclusions: I. Some sofas are not chairs. II. All sofas are chairs.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Either conclusion I or II follows","Only conclusion II follows"],"answer":2,"explanation":"I: all sofas could be chairs without breaking any statement, so it is not definite. II: some sofas could lie outside chairs without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई सोफ़ा मेज़ नहीं है। कोई पलंग मेज़ नहीं है। सभी पलंग कुर्सियाँ हैं। निष्कर्ष: I. कुछ सोफ़े कुर्सियाँ नहीं हैं। II. सभी सोफ़े कुर्सियाँ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: सभी सोफ़े कुर्सियाँ हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ सोफ़े कुर्सियों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-123","question":"Statements: No actors are pilots. All actors are lawyers. Conclusions: I. No pilots are lawyers. II. Some lawyers are not pilots.","options":["Only conclusion I follows","Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":3,"explanation":"I: some pilots could be lawyers without breaking any statement, so it is not definite. II: follows from 'No actors are pilots' and 'All actors are lawyers'.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई अभिनेता पायलट नहीं है। सभी अभिनेता वकील हैं। निष्कर्ष: I. कोई पायलट वकील नहीं है। II. कुछ वकील पायलट नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: कुछ पायलट वकील हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘कोई अभिनेता पायलट नहीं है’ और ‘सभी अभिनेता वकील हैं’ से अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-124","question":"Statements: Some apples are mangoes. All melons are apples. Some melons are grapes. Conclusions: I. Some apples are grapes. II. All mangoes are apples.","options":["Only conclusion I follows","Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion II follows"],"answer":0,"explanation":"I: follows from 'All melons are apples' and 'Some melons are grapes'. II: some mangoes could lie outside apples without breaking any statement, so it is not definite.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ सेब आम हैं। सभी खरबूजे सेब हैं। कुछ खरबूजे अंगूर हैं। निष्कर्ष: I. कुछ सेब अंगूर हैं। II. सभी आम सेब हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: ‘सभी खरबूजे सेब हैं’ और ‘कुछ खरबूजे अंगूर हैं’ से अनुसरण करता है। II: कुछ आम सेबों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-125","question":"Statements: No singers are dancers. All doctors are dancers. All teachers are doctors. Conclusions: I. All doctors are teachers. II. All dancers are teachers.","options":["Either conclusion I or II follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":1,"explanation":"I: some doctors could lie outside teachers without breaking any statement, so it is not definite. II: some dancers could lie outside teachers without breaking any statement, so it is not definite.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई गायक नर्तक नहीं है। सभी डॉक्टर नर्तक हैं। सभी शिक्षक डॉक्टर हैं। निष्कर्ष: I. सभी डॉक्टर शिक्षक हैं। II. सभी नर्तक शिक्षक हैं।","optionsHi":["निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I: कुछ डॉक्टर शिक्षकों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ नर्तक शिक्षकों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-126","question":"Statements: All writers are lawyers. All writers are pilots. Some pilots are actors. Conclusions: I. Some lawyers are pilots. II. Some writers are pilots.","options":["Neither conclusion I nor II follows","Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":2,"explanation":"I: follows from 'All writers are lawyers' and 'All writers are pilots'. II: follows from 'All writers are pilots'.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी लेखक वकील हैं। सभी लेखक पायलट हैं। कुछ पायलट अभिनेता हैं। निष्कर्ष: I. कुछ वकील पायलट हैं। II. कुछ लेखक पायलट हैं।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I: ‘सभी लेखक वकील हैं’ और ‘सभी लेखक पायलट हैं’ से अनुसरण करता है। II: ‘सभी लेखक पायलट हैं’ से अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-127","question":"Statements: No laptops are phones. All phones are watches. No watches are tablets. Conclusions: I. All laptops are watches. II. Some phones are watches.","options":["Only conclusion I follows","Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":3,"explanation":"I: some laptops could lie outside watches without breaking any statement, so it is not definite. II: follows from 'All phones are watches'.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई लैपटॉप फ़ोन नहीं है। सभी फ़ोन घड़ियाँ हैं। कोई घड़ी टैबलेट नहीं है। निष्कर्ष: I. सभी लैपटॉप घड़ियाँ हैं। II. कुछ फ़ोन घड़ियाँ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: कुछ लैपटॉप घड़ियों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी फ़ोन घड़ियाँ हैं’ से अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-128","question":"Statements: All rivers are ponds. Some rivers are lakes. All lakes are seas. Conclusions: I. Some seas are not lakes. II. All seas are lakes.","options":["Either conclusion I or II follows","Only conclusion II follows","Only conclusion I follows","Both conclusions I and II follow"],"answer":0,"explanation":"I: all seas could be lakes without breaking any statement, so it is not definite. II: some seas could lie outside lakes without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी नदियाँ तालाब हैं। कुछ नदियाँ झीलें हैं। सभी झीलें समुद्र हैं। निष्कर्ष: I. कुछ समुद्र झीलें नहीं हैं। II. सभी समुद्र झीलें हैं।","optionsHi":["निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: सभी समुद्र झीलें हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ समुद्र झीलों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-129","question":"Statements: Only a few tablets are laptops. Only a few phones are tablets. All phones are watches. Conclusions: I. No laptops are phones. II. Some laptops are phones.","options":["Both conclusions I and II follow","Either conclusion I or II follows","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":1,"explanation":"I: some laptops could be phones without breaking any statement, so it is not definite. II: laptops and phones could have nothing in common without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: केवल कुछ टैबलेट लैपटॉप हैं। केवल कुछ फ़ोन टैबलेट हैं। सभी फ़ोन घड़ियाँ हैं। निष्कर्ष: I. कोई लैपटॉप फ़ोन नहीं है। II. कुछ लैपटॉप फ़ोन हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: कुछ लैपटॉप फ़ोन हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: लैपटॉप और फ़ोन में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-130","question":"Statements: Some grapes are not mangoes. Some apples are grapes. All apples are melons. Conclusions: I. All melons being apples is a possibility. II. No melons being apples is a possibility.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows"],"answer":2,"explanation":"I: a diagram in which all melons are apples fits all the statements, so as a possibility it follows. II: 'All apples are melons' rules this out, so it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ अंगूर आम नहीं हैं। कुछ सेब अंगूर हैं। सभी सेब खरबूजे हैं। निष्कर्ष: I. सभी खरबूजों के सेब होने की संभावना है। II. किसी खरबूजे के सेब न होने की संभावना है।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें सभी खरबूजे सेब हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ‘सभी सेब खरबूजे हैं’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-131","question":"Statements: No plates are spoons. No cups are spoons. All bowls are cups. Conclusions: I. Some bowls are not plates. II. Some bowls are cups.","options":["Both conclusions I and II follow","Neither conclusion I nor II follows","Only conclusion I follows","Only conclusion II follows"],"answer":3,"explanation":"I: all bowls could be plates without breaking any statement, so it is not definite. II: follows from 'All bowls are cups'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई प्लेट चम्मच नहीं है। कोई कप चम्मच नहीं है। सभी कटोरे कप हैं। निष्कर्ष: I. कुछ कटोरे प्लेटें नहीं हैं। II. कुछ कटोरे कप हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: सभी कटोरे प्लेटें हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी कटोरे कप हैं’ से अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-132","question":"Statements: No comets are planets. Some stars are planets. No stars are moons. Conclusions: I. Some moons are not comets. II. All stars being comets is a possibility.","options":["Neither conclusion I nor II follows","Only conclusion II follows","Either conclusion I or II follows","Both conclusions I and II follow"],"answer":0,"explanation":"I: all moons could be comets without breaking any statement, so it is not definite. II: 'No comets are planets' and 'Some stars are planets' rule this out, so it does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई धूमकेतु ग्रह नहीं है। कुछ तारे ग्रह हैं। कोई तारा चंद्रमा नहीं है। निष्कर्ष: I. कुछ चंद्रमा धूमकेतु नहीं हैं। II. सभी तारों के धूमकेतु होने की संभावना है।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I: सभी चंद्रमा धूमकेतु हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘कोई धूमकेतु ग्रह नहीं है’ और ‘कुछ तारे ग्रह हैं’ इसे असंभव बना देते हैं, इसलिए यह अनुसरण नहीं करता।","subtopic":"possibility"},
  {"id":"reason-syllogism-133","question":"Statements: Some caps are not jeans. Some socks are caps. All shirts are socks. Conclusions: I. All socks being shirts is a possibility. II. All jeans being caps is a possibility.","options":["Either conclusion I or II follows","Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":1,"explanation":"I: a diagram in which all socks are shirts fits all the statements, so as a possibility it follows. II: a diagram in which all jeans are caps fits all the statements, so as a possibility it follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ कैप जीन्स नहीं हैं। कुछ मोज़े कैप हैं। सभी कमीज़ें मोज़े हैं। निष्कर्ष: I. सभी मोज़ों के कमीज़ें होने की संभावना है। II. सभी जीन्स के कैप होने की संभावना है।","optionsHi":["निष्कर्ष I या II में से कोई एक अनुसरण करता है","दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें सभी मोज़े कमीज़ें हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ऐसा आरेख जिसमें सभी जीन्स कैप हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-134","question":"Statements: No orchids are tulips. All tulips are lilies. Some roses are lilies. Conclusions: I. Some roses are not tulips. II. All roses are tulips.","options":["Both conclusions I and II follow","Only conclusion II follows","Either conclusion I or II follows","Only conclusion I follows"],"answer":2,"explanation":"I: all roses could be tulips without breaking any statement, so it is not definite. II: some roses could lie outside tulips without breaking any statement, so it is not definite. The two conclusions form a complementary pair on the same terms (exactly one of them must be true), so either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई ऑर्किड ट्यूलिप नहीं है। सभी ट्यूलिप लिली हैं। कुछ गुलाब लिली हैं। निष्कर्ष: I. कुछ गुलाब ट्यूलिप नहीं हैं। II. सभी गुलाब ट्यूलिप हैं।","optionsHi":["दोनों निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I: सभी गुलाब ट्यूलिप हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ गुलाब ट्यूलिपों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। दोनों निष्कर्ष समान पदों पर आधारित पूरक युग्म हैं (उनमें से ठीक एक अवश्य सत्य होगा), इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-135","question":"Statements: No cups are bowls. Some spoons are not cups. Some plates are spoons. Conclusions: I. Some bowls are not spoons. II. No spoons are bowls.","options":["Only conclusion I follows","Only conclusion II follows","Either conclusion I or II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I: all bowls could be spoons without breaking any statement, so it is not definite. II: some spoons could be bowls without breaking any statement, so it is not definite.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई कप कटोरा नहीं है। कुछ चम्मच कप नहीं हैं। कुछ प्लेटें चम्मच हैं। निष्कर्ष: I. कुछ कटोरे चम्मच नहीं हैं। II. कोई चम्मच कटोरा नहीं है।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I: सभी कटोरे चम्मच हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ चम्मच कटोरे हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-136","question":"Statements: No moons are planets. Some stars are planets. No stars are comets. Conclusions: I. Some stars are not comets. II. Some comets are planets.","options":["Only conclusion I follows","Either conclusion I or II follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":0,"explanation":"I: follows from 'No stars are comets'. II: comets and planets could have nothing in common without breaking any statement, so it is not definite.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई चंद्रमा ग्रह नहीं है। कुछ तारे ग्रह हैं। कोई तारा धूमकेतु नहीं है। निष्कर्ष: I. कुछ तारे धूमकेतु नहीं हैं। II. कुछ धूमकेतु ग्रह हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I या II में से कोई एक अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I: ‘कोई तारा धूमकेतु नहीं है’ से अनुसरण करता है। II: धूमकेतुओं और ग्रहों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-137","question":"Statements: Some rivers are ponds. Only a few seas are rivers. Which of the following conclusions follow? I. Some ponds are seas. II. All rivers being ponds is a possibility. III. All rivers are seas.","options":["Only I and II follow","Only II follows","Only III follows","All follow"],"answer":1,"explanation":"I: ponds and seas could have nothing in common without breaking any statement, so it is not definite. II: a diagram in which all rivers are ponds fits all the statements, so as a possibility it follows. III: some rivers could lie outside seas without breaking any statement, so it is not definite. Hence: Only II follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ नदियाँ तालाब हैं। केवल कुछ समुद्र नदियाँ हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ तालाब समुद्र हैं। II. सभी नदियों के तालाब होने की संभावना है। III. सभी नदियाँ समुद्र हैं।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल II अनुसरण करता है","केवल III अनुसरण करता है","सभी अनुसरण करते हैं"],"explanationHi":"I: तालाबों और समुद्रों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ऐसा आरेख जिसमें सभी नदियाँ तालाब हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: कुछ नदियाँ समुद्रों से बाहर हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल II अनुसरण करता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-138","question":"Statements: Some ponds are rivers. No seas are rivers. Which of the following conclusions follow? I. Some seas being ponds is a possibility. II. No rivers being ponds is a possibility. III. Some ponds are seas.","options":["Only I and III follow","Only I and II follow","Only I follows","Only II follows"],"answer":2,"explanation":"I: a diagram in which some seas are ponds fits all the statements, so as a possibility it follows. II: 'Some ponds are rivers' rules this out, so it does not follow. III: ponds and seas could have nothing in common without breaking any statement, so it is not definite. Hence: Only I follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ तालाब नदियाँ हैं। कोई समुद्र नदी नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ समुद्रों के तालाब होने की संभावना है। II. किसी नदी के तालाब न होने की संभावना है। III. कुछ तालाब समुद्र हैं।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल I अनुसरण करता है","केवल II अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें कुछ समुद्र तालाब हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ‘कुछ तालाब नदियाँ हैं’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। III: तालाबों और समुद्रों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल I अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-139","question":"Statements: Some phones are not watches. All phones are tablets. Which of the following conclusions follow? I. Some phones are tablets. II. Some watches are phones. III. All tablets are phones.","options":["Only I and III follow","All follow","Only II follows","Only I follows"],"answer":3,"explanation":"I: follows from 'All phones are tablets'. II: watches and phones could have nothing in common without breaking any statement, so it is not definite. III: some tablets could lie outside phones without breaking any statement, so it is not definite. Hence: Only I follows.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ फ़ोन घड़ियाँ नहीं हैं। सभी फ़ोन टैबलेट हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ फ़ोन टैबलेट हैं। II. कुछ घड़ियाँ फ़ोन हैं। III. सभी टैबलेट फ़ोन हैं।","optionsHi":["केवल I और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल II अनुसरण करता है","केवल I अनुसरण करता है"],"explanationHi":"I: ‘सभी फ़ोन टैबलेट हैं’ से अनुसरण करता है। II: घड़ियों और फ़ोनों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: कुछ टैबलेट फ़ोनों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल I अनुसरण करता है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-140","question":"Statements: Some singers are teachers. All singers are dancers. No doctors are dancers. Which of the following conclusions follow? I. Some teachers are dancers. II. Some teachers are not singers. III. Some singers are not teachers.","options":["Only I follows","Only III follows","Only I and II follow","All follow"],"answer":0,"explanation":"I: follows from 'Some singers are teachers' and 'All singers are dancers'. II: all teachers could be singers without breaking any statement, so it is not definite. III: all singers could be teachers without breaking any statement, so it is not definite. Hence: Only I follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ गायक शिक्षक हैं। सभी गायक नर्तक हैं। कोई डॉक्टर नर्तक नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ शिक्षक नर्तक हैं। II. कुछ शिक्षक गायक नहीं हैं। III. कुछ गायक शिक्षक नहीं हैं।","optionsHi":["केवल I अनुसरण करता है","केवल III अनुसरण करता है","केवल I और II अनुसरण करते हैं","सभी अनुसरण करते हैं"],"explanationHi":"I: ‘कुछ गायक शिक्षक हैं’ और ‘सभी गायक नर्तक हैं’ से अनुसरण करता है। II: सभी शिक्षक गायक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: सभी गायक शिक्षक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल I अनुसरण करता है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-141","question":"Statements: All sofas are tables. Some tables are not chairs. Some chairs are beds. Which of the following conclusions follow? I. Some beds are chairs. II. No sofas are beds. III. All beds are tables.","options":["All follow","Only I follows","Only III follows","Only I and II follow"],"answer":1,"explanation":"I: follows from 'Some chairs are beds'. II: some sofas could be beds without breaking any statement, so it is not definite. III: some beds could lie outside tables without breaking any statement, so it is not definite. Hence: Only I follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी सोफ़े मेज़ हैं। कुछ मेज़ कुर्सियाँ नहीं हैं। कुछ कुर्सियाँ पलंग हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ पलंग कुर्सियाँ हैं। II. कोई सोफ़ा पलंग नहीं है। III. सभी पलंग मेज़ हैं।","optionsHi":["सभी अनुसरण करते हैं","केवल I अनुसरण करता है","केवल III अनुसरण करता है","केवल I और II अनुसरण करते हैं"],"explanationHi":"I: ‘कुछ कुर्सियाँ पलंग हैं’ से अनुसरण करता है। II: कुछ सोफ़े पलंग हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: कुछ पलंग मेज़ों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल I अनुसरण करता है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-142","question":"Statements: No dancers are doctors. Some singers are dancers. All teachers are singers. Which of the following conclusions follow? I. No doctors are singers. II. No teachers are dancers. III. All dancers being singers is a possibility.","options":["All follow","Only II and III follow","Only III follows","Only I follows"],"answer":2,"explanation":"I: some doctors could be singers without breaking any statement, so it is not definite. II: some teachers could be dancers without breaking any statement, so it is not definite. III: a diagram in which all dancers are singers fits all the statements, so as a possibility it follows. Hence: Only III follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई नर्तक डॉक्टर नहीं है। कुछ गायक नर्तक हैं। सभी शिक्षक गायक हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कोई डॉक्टर गायक नहीं है। II. कोई शिक्षक नर्तक नहीं है। III. सभी नर्तकों के गायक होने की संभावना है।","optionsHi":["सभी अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल III अनुसरण करता है","केवल I अनुसरण करता है"],"explanationHi":"I: कुछ डॉक्टर गायक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ शिक्षक नर्तक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ऐसा आरेख जिसमें सभी नर्तक गायक हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल III अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-143","question":"Statements: Some mangoes are not grapes. Some melons are grapes. Some melons are apples. Which of the following conclusions follow? I. All mangoes being melons is a possibility. II. No grapes are mangoes. III. All apples being grapes is a possibility. IV. No mangoes being grapes is a possibility.","options":["Only I and IV follow","Only I, II and III follow","Only III and IV follow","Only I, III and IV follow"],"answer":3,"explanation":"I: a diagram in which all mangoes are melons fits all the statements, so as a possibility it follows. II: some grapes could be mangoes without breaking any statement, so it is not definite. III: a diagram in which all apples are grapes fits all the statements, so as a possibility it follows. IV: a diagram in which no mangoes are grapes fits all the statements, so as a possibility it follows. Hence: Only I, III and IV follow.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ आम अंगूर नहीं हैं। कुछ खरबूजे अंगूर हैं। कुछ खरबूजे सेब हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. सभी आमों के खरबूजे होने की संभावना है। II. कोई अंगूर आम नहीं है। III. सभी सेबों के अंगूर होने की संभावना है। IV. किसी आम के अंगूर न होने की संभावना है।","optionsHi":["केवल I और IV अनुसरण करते हैं","केवल I, II और III अनुसरण करते हैं","केवल III और IV अनुसरण करते हैं","केवल I, III और IV अनुसरण करते हैं"],"explanationHi":"I: ऐसा आरेख जिसमें सभी आम खरबूजे हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: कुछ अंगूर आम हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ऐसा आरेख जिसमें सभी सेब अंगूर हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। IV: ऐसा आरेख जिसमें कोई आम अंगूर न हो, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल I, III और IV अनुसरण करते हैं।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-144","question":"Statements: All writers are actors. No pilots are actors. All pilots are lawyers. Which of the following conclusions follow? I. Some actors being pilots is a possibility. II. No lawyers being writers is a possibility. III. All lawyers being actors is a possibility.","options":["Only II follows","Only I and III follow","Only I and II follow","Only I follows"],"answer":0,"explanation":"I: 'No pilots are actors' rules this out, so it does not follow. II: a diagram in which no lawyers are writers fits all the statements, so as a possibility it follows. III: 'No pilots are actors' and 'All pilots are lawyers' rule this out, so it does not follow. Hence: Only II follows.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी लेखक अभिनेता हैं। कोई पायलट अभिनेता नहीं है। सभी पायलट वकील हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ अभिनेताओं के पायलट होने की संभावना है। II. किसी वकील के लेखक न होने की संभावना है। III. सभी वकीलों के अभिनेता होने की संभावना है।","optionsHi":["केवल II अनुसरण करता है","केवल I और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल I अनुसरण करता है"],"explanationHi":"I: ‘कोई पायलट अभिनेता नहीं है’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। II: ऐसा आरेख जिसमें कोई वकील लेखक न हो, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: ‘कोई पायलट अभिनेता नहीं है’ और ‘सभी पायलट वकील हैं’ इसे असंभव बना देते हैं, इसलिए यह अनुसरण नहीं करता। अतः: केवल II अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-145","question":"Statements: Some cats are not bats. All dogs are cats. All rats are dogs. Which of the following conclusions follow? I. All dogs being bats is a possibility. II. Some bats being rats is a possibility. III. All bats are cats. IV. Some cats are bats.","options":["Only IV follows","Only I and II follow","Only III and IV follow","Only II follows"],"answer":1,"explanation":"I: a diagram in which all dogs are bats fits all the statements, so as a possibility it follows. II: a diagram in which some bats are rats fits all the statements, so as a possibility it follows. III: some bats could lie outside cats without breaking any statement, so it is not definite. IV: cats and bats could have nothing in common without breaking any statement, so it is not definite. Hence: Only I and II follow.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ बिल्लियाँ चमगादड़ नहीं हैं। सभी कुत्ते बिल्लियाँ हैं। सभी चूहे कुत्ते हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. सभी कुत्तों के चमगादड़ होने की संभावना है। II. कुछ चमगादड़ों के चूहे होने की संभावना है। III. सभी चमगादड़ बिल्लियाँ हैं। IV. कुछ बिल्लियाँ चमगादड़ हैं।","optionsHi":["केवल IV अनुसरण करता है","केवल I और II अनुसरण करते हैं","केवल III और IV अनुसरण करते हैं","केवल II अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें सभी कुत्ते चमगादड़ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ऐसा आरेख जिसमें कुछ चमगादड़ चूहे हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: कुछ चमगादड़ बिल्लियों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: बिल्लियों और चमगादड़ों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल I और II अनुसरण करते हैं।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-146","question":"Statements: All sofas are chairs. Some chairs are beds. No beds are tables. Which of the following conclusions follow? I. All chairs are beds. II. Some tables being sofas is a possibility. III. No tables being chairs is a possibility. IV. Some chairs are not sofas.","options":["Only I, III and IV follow","Only I, II and IV follow","Only II and III follow","Only I and III follow"],"answer":2,"explanation":"I: some chairs could lie outside beds without breaking any statement, so it is not definite. II: a diagram in which some tables are sofas fits all the statements, so as a possibility it follows. III: a diagram in which no tables are chairs fits all the statements, so as a possibility it follows. IV: all chairs could be sofas without breaking any statement, so it is not definite. Hence: Only II and III follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी सोफ़े कुर्सियाँ हैं। कुछ कुर्सियाँ पलंग हैं। कोई पलंग मेज़ नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. सभी कुर्सियाँ पलंग हैं। II. कुछ मेज़ों के सोफ़े होने की संभावना है। III. किसी मेज़ के कुर्सी न होने की संभावना है। IV. कुछ कुर्सियाँ सोफ़े नहीं हैं।","optionsHi":["केवल I, III और IV अनुसरण करते हैं","केवल I, II और IV अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"I: कुछ कुर्सियाँ पलंगों से बाहर हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ऐसा आरेख जिसमें कुछ मेज़ सोफ़े हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: ऐसा आरेख जिसमें कोई मेज़ कुर्सी न हो, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। IV: सभी कुर्सियाँ सोफ़े हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल II और III अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-147","question":"Statements: All caps are jeans. No socks are jeans. All socks are shirts. Which of the following conclusions follow? I. Some jeans being shirts is a possibility. II. Some socks being jeans is a possibility. III. Some shirts are caps. IV. All caps being socks is a possibility.","options":["Only I, II and III follow","Only I, II and IV follow","Only II follows","Only I follows"],"answer":3,"explanation":"I: a diagram in which some jeans are shirts fits all the statements, so as a possibility it follows. II: 'No socks are jeans' rules this out, so it does not follow. III: shirts and caps could have nothing in common without breaking any statement, so it is not definite. IV: 'All caps are jeans' and 'No socks are jeans' rule this out, so it does not follow. Hence: Only I follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी कैप जीन्स हैं। कोई मोज़ा जीन्स नहीं है। सभी मोज़े कमीज़ें हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ जीन्स के कमीज़ें होने की संभावना है। II. कुछ मोज़ों के जीन्स होने की संभावना है। III. कुछ कमीज़ें कैप हैं। IV. सभी कैपों के मोज़े होने की संभावना है।","optionsHi":["केवल I, II और III अनुसरण करते हैं","केवल I, II और IV अनुसरण करते हैं","केवल II अनुसरण करता है","केवल I अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें कुछ जीन्स कमीज़ें हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: ‘कोई मोज़ा जीन्स नहीं है’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। III: कमीज़ों और कैपों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: ‘सभी कैप जीन्स हैं’ और ‘कोई मोज़ा जीन्स नहीं है’ इसे असंभव बना देते हैं, इसलिए यह अनुसरण नहीं करता। अतः: केवल I अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-148","question":"Statements: Some phones are laptops. No tablets are laptops. Some tablets are watches. Which of the following conclusions follow? I. Some watches are phones. II. All laptops being phones is a possibility. III. Some phones are not laptops. IV. All laptops being watches is a possibility.","options":["Only II and IV follow","Only II, III and IV follow","Only I and IV follow","Only II follows"],"answer":0,"explanation":"I: watches and phones could have nothing in common without breaking any statement, so it is not definite. II: a diagram in which all laptops are phones fits all the statements, so as a possibility it follows. III: all phones could be laptops without breaking any statement, so it is not definite. IV: a diagram in which all laptops are watches fits all the statements, so as a possibility it follows. Hence: Only II and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ फ़ोन लैपटॉप हैं। कोई टैबलेट लैपटॉप नहीं है। कुछ टैबलेट घड़ियाँ हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ घड़ियाँ फ़ोन हैं। II. सभी लैपटॉपों के फ़ोन होने की संभावना है। III. कुछ फ़ोन लैपटॉप नहीं हैं। IV. सभी लैपटॉपों के घड़ियाँ होने की संभावना है।","optionsHi":["केवल II और IV अनुसरण करते हैं","केवल II, III और IV अनुसरण करते हैं","केवल I और IV अनुसरण करते हैं","केवल II अनुसरण करता है"],"explanationHi":"I: घड़ियों और फ़ोनों में कुछ भी समान न हो, तब भी किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ऐसा आरेख जिसमें सभी लैपटॉप फ़ोन हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: सभी फ़ोन लैपटॉप हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: ऐसा आरेख जिसमें सभी लैपटॉप घड़ियाँ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल II और IV अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-149","question":"Statements: All boxes are books. All pens are books. Some pens are bags. Which of the following conclusions follow? I. Some bags are not books. II. Some books are pens. III. All pens being boxes is a possibility.","options":["Only I and III follow","Only II and III follow","All follow","Only III follows"],"answer":1,"explanation":"I: all bags could be books without breaking any statement, so it is not definite. II: follows from 'All pens are books'. III: a diagram in which all pens are boxes fits all the statements, so as a possibility it follows. Hence: Only II and III follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी डिब्बे किताबें हैं। सभी पेन किताबें हैं। कुछ पेन थैले हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ थैले किताबें नहीं हैं। II. कुछ किताबें पेन हैं। III. सभी पेनों के डिब्बे होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल III अनुसरण करता है"],"explanationHi":"I: सभी थैले किताबें हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी पेन किताबें हैं’ से अनुसरण करता है। III: ऐसा आरेख जिसमें सभी पेन डिब्बे हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल II और III अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-150","question":"Statements: All bowls are cups. All plates are cups. No plates are spoons. Which of the following conclusions follow? I. All cups are bowls. II. All spoons are cups. III. No bowls being cups is a possibility. IV. Some plates are cups.","options":["Only III follows","Only II follows","Only IV follows","Only I follows"],"answer":2,"explanation":"I: some cups could lie outside bowls without breaking any statement, so it is not definite. II: some spoons could lie outside cups without breaking any statement, so it is not definite. III: 'All bowls are cups' rules this out, so it does not follow. IV: follows from 'All plates are cups'. Hence: Only IV follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी कटोरे कप हैं। सभी प्लेटें कप हैं। कोई प्लेट चम्मच नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. सभी कप कटोरे हैं। II. सभी चम्मच कप हैं। III. किसी कटोरे के कप न होने की संभावना है। IV. कुछ प्लेटें कप हैं।","optionsHi":["केवल III अनुसरण करता है","केवल II अनुसरण करता है","केवल IV अनुसरण करता है","केवल I अनुसरण करता है"],"explanationHi":"I: कुछ कप कटोरों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ चम्मच कपों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ‘सभी कटोरे कप हैं’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। IV: ‘सभी प्लेटें कप हैं’ से अनुसरण करता है। अतः: केवल IV अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-151","question":"Statements: No sofas are chairs. Some tables are chairs. Some beds are tables. Which of the following conclusions follow? I. Some sofas are not tables. II. Some chairs being beds is a possibility. III. Some tables are not chairs. IV. All beds being chairs is a possibility.","options":["Only IV follows","Only II, III and IV follow","Only I, III and IV follow","Only II and IV follow"],"answer":3,"explanation":"I: all sofas could be tables without breaking any statement, so it is not definite. II: a diagram in which some chairs are beds fits all the statements, so as a possibility it follows. III: all tables could be chairs without breaking any statement, so it is not definite. IV: a diagram in which all beds are chairs fits all the statements, so as a possibility it follows. Hence: Only II and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई सोफ़ा कुर्सी नहीं है। कुछ मेज़ कुर्सियाँ हैं। कुछ पलंग मेज़ हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ सोफ़े मेज़ नहीं हैं। II. कुछ कुर्सियों के पलंग होने की संभावना है। III. कुछ मेज़ कुर्सियाँ नहीं हैं। IV. सभी पलंगों के कुर्सी होने की संभावना है।","optionsHi":["केवल IV अनुसरण करता है","केवल II, III और IV अनुसरण करते हैं","केवल I, III और IV अनुसरण करते हैं","केवल II और IV अनुसरण करते हैं"],"explanationHi":"I: सभी सोफ़े मेज़ हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ऐसा आरेख जिसमें कुछ कुर्सियाँ पलंग हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: सभी मेज़ कुर्सियाँ हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: ऐसा आरेख जिसमें सभी पलंग कुर्सियाँ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल II और IV अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-152","question":"Statements: Some watches are phones. No laptops are watches. No laptops are tablets. Which of the following conclusions follow? I. Some tablets are not phones. II. Some tablets being watches is a possibility. III. No phones are tablets. IV. Some phones being laptops is a possibility.","options":["Only II and IV follow","Only I and III follow","Only III and IV follow","Only II and III follow"],"answer":0,"explanation":"I: all tablets could be phones without breaking any statement, so it is not definite. II: a diagram in which some tablets are watches fits all the statements, so as a possibility it follows. III: some phones could be tablets without breaking any statement, so it is not definite. IV: a diagram in which some phones are laptops fits all the statements, so as a possibility it follows. Hence: Only II and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ घड़ियाँ फ़ोन हैं। कोई लैपटॉप घड़ी नहीं है। कोई लैपटॉप टैबलेट नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ टैबलेट फ़ोन नहीं हैं। II. कुछ टैबलेटों के घड़ियाँ होने की संभावना है। III. कोई फ़ोन टैबलेट नहीं है। IV. कुछ फ़ोनों के लैपटॉप होने की संभावना है।","optionsHi":["केवल II और IV अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल III और IV अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I: सभी टैबलेट फ़ोन हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ऐसा आरेख जिसमें कुछ टैबलेट घड़ियाँ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: कुछ फ़ोन टैबलेट हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: ऐसा आरेख जिसमें कुछ फ़ोन लैपटॉप हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल II और IV अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-153","question":"Statements: All beds are chairs. Some beds are not sofas. All sofas are tables. Which of the following conclusions follow? I. No beds being sofas is a possibility. II. No chairs are sofas. III. Some chairs are beds. IV. All tables being sofas is a possibility.","options":["Only I, II and III follow","Only I, III and IV follow","Only I, II and IV follow","Only IV follows"],"answer":1,"explanation":"I: a diagram in which no beds are sofas fits all the statements, so as a possibility it follows. II: some chairs could be sofas without breaking any statement, so it is not definite. III: follows from 'All beds are chairs'. IV: a diagram in which all tables are sofas fits all the statements, so as a possibility it follows. Hence: Only I, III and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी पलंग कुर्सियाँ हैं। कुछ पलंग सोफ़े नहीं हैं। सभी सोफ़े मेज़ हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. किसी पलंग के सोफ़ा न होने की संभावना है। II. कोई कुर्सी सोफ़ा नहीं है। III. कुछ कुर्सियाँ पलंग हैं। IV. सभी मेज़ों के सोफ़े होने की संभावना है।","optionsHi":["केवल I, II और III अनुसरण करते हैं","केवल I, III और IV अनुसरण करते हैं","केवल I, II और IV अनुसरण करते हैं","केवल IV अनुसरण करता है"],"explanationHi":"I: ऐसा आरेख जिसमें कोई पलंग सोफ़ा न हो, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: कुछ कुर्सियाँ सोफ़े हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ‘सभी पलंग कुर्सियाँ हैं’ से अनुसरण करता है। IV: ऐसा आरेख जिसमें सभी मेज़ सोफ़े हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल I, III और IV अनुसरण करते हैं।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-154","question":"Statements: All laptops are watches. Some watches are phones. All phones are tablets. Which of the following conclusions follow? I. Some watches are not phones. II. Some phones are tablets. III. All phones are watches. IV. All tablets being watches is a possibility.","options":["Only II, III and IV follow","Only II follows","Only II and IV follow","Only III and IV follow"],"answer":2,"explanation":"I: all watches could be phones without breaking any statement, so it is not definite. II: follows from 'All phones are tablets'. III: some phones could lie outside watches without breaking any statement, so it is not definite. IV: a diagram in which all tablets are watches fits all the statements, so as a possibility it follows. Hence: Only II and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी लैपटॉप घड़ियाँ हैं। कुछ घड़ियाँ फ़ोन हैं। सभी फ़ोन टैबलेट हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ घड़ियाँ फ़ोन नहीं हैं। II. कुछ फ़ोन टैबलेट हैं। III. सभी फ़ोन घड़ियाँ हैं। IV. सभी टैबलेटों के घड़ियाँ होने की संभावना है।","optionsHi":["केवल II, III और IV अनुसरण करते हैं","केवल II अनुसरण करता है","केवल II और IV अनुसरण करते हैं","केवल III और IV अनुसरण करते हैं"],"explanationHi":"I: सभी घड़ियाँ फ़ोन हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: ‘सभी फ़ोन टैबलेट हैं’ से अनुसरण करता है। III: कुछ फ़ोन घड़ियों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: ऐसा आरेख जिसमें सभी टैबलेट घड़ियाँ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल II और IV अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-155","question":"Statements: All dancers are teachers. Some doctors are not teachers. No singers are doctors. Which of the following conclusions follow? I. Some singers are not teachers. II. All dancers are singers. III. All teachers being doctors is a possibility.","options":["Only II follows","All follow","Only I follows","Only III follows"],"answer":3,"explanation":"I: all singers could be teachers without breaking any statement, so it is not definite. II: some dancers could lie outside singers without breaking any statement, so it is not definite. III: a diagram in which all teachers are doctors fits all the statements, so as a possibility it follows. Hence: Only III follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: सभी नर्तक शिक्षक हैं। कुछ डॉक्टर शिक्षक नहीं हैं। कोई गायक डॉक्टर नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ गायक शिक्षक नहीं हैं। II. सभी नर्तक गायक हैं। III. सभी शिक्षकों के डॉक्टर होने की संभावना है।","optionsHi":["केवल II अनुसरण करता है","सभी अनुसरण करते हैं","केवल I अनुसरण करता है","केवल III अनुसरण करता है"],"explanationHi":"I: सभी गायक शिक्षक हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। II: कुछ नर्तक गायकों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ऐसा आरेख जिसमें सभी शिक्षक डॉक्टर हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल III अनुसरण करता है।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-156","question":"Statements: Some plates are spoons. Some cups are spoons. No bowls are cups. Which of the following conclusions follow? I. All cups being bowls is a possibility. II. Some bowls being plates is a possibility. III. Some plates are not bowls. IV. All cups are spoons.","options":["Only II follows","Only II and IV follow","Only I and IV follow","Only I and II follow"],"answer":0,"explanation":"I: 'No bowls are cups' rules this out, so it does not follow. II: a diagram in which some bowls are plates fits all the statements, so as a possibility it follows. III: all plates could be bowls without breaking any statement, so it is not definite. IV: some cups could lie outside spoons without breaking any statement, so it is not definite. Hence: Only II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ प्लेटें चम्मच हैं। कुछ कप चम्मच हैं। कोई कटोरा कप नहीं है। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. सभी कपों के कटोरे होने की संभावना है। II. कुछ कटोरों के प्लेट होने की संभावना है। III. कुछ प्लेटें कटोरे नहीं हैं। IV. सभी कप चम्मच हैं।","optionsHi":["केवल II अनुसरण करता है","केवल II और IV अनुसरण करते हैं","केवल I और IV अनुसरण करते हैं","केवल I और II अनुसरण करते हैं"],"explanationHi":"I: ‘कोई कटोरा कप नहीं है’ इसे असंभव बना देता है, इसलिए यह अनुसरण नहीं करता। II: ऐसा आरेख जिसमें कुछ कटोरे प्लेटें हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। III: सभी प्लेटें कटोरे हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। IV: कुछ कप चम्मचों से बाहर हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। अतः: केवल II अनुसरण करता है।","subtopic":"possibility"},
  {"id":"reason-syllogism-157","question":"Statements: No ponds are lakes. All lakes are seas. All rivers are seas. Which of the following conclusions follow? I. Some rivers being lakes is a possibility. II. Some ponds are not seas. III. All lakes being rivers is a possibility. IV. Some lakes are seas.","options":["Only I and III follow","Only I, III and IV follow","Only II and IV follow","Only III and IV follow"],"answer":1,"explanation":"I: a diagram in which some rivers are lakes fits all the statements, so as a possibility it follows. II: all ponds could be seas without breaking any statement, so it is not definite. III: a diagram in which all lakes are rivers fits all the statements, so as a possibility it follows. IV: follows from 'All lakes are seas'. Hence: Only I, III and IV follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कोई तालाब झील नहीं है। सभी झीलें समुद्र हैं। सभी नदियाँ समुद्र हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ नदियों के झील होने की संभावना है। II. कुछ तालाब समुद्र नहीं हैं। III. सभी झीलों के नदियाँ होने की संभावना है। IV. कुछ झीलें समुद्र हैं।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल I, III और IV अनुसरण करते हैं","केवल II और IV अनुसरण करते हैं","केवल III और IV अनुसरण करते हैं"],"explanationHi":"I: ऐसा आरेख जिसमें कुछ नदियाँ झीलें हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। II: सभी तालाब समुद्र हो सकते हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ऐसा आरेख जिसमें सभी झीलें नदियाँ हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। IV: ‘सभी झीलें समुद्र हैं’ से अनुसरण करता है। अतः: केवल I, III और IV अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-158","question":"Statements: Some tablets are watches. All tablets are laptops. Some laptops are phones. Which of the following conclusions follow? I. Some laptops are tablets. II. All watches are laptops. III. All watches being phones is a possibility.","options":["Only I follows","All follow","Only I and III follow","Only III follows"],"answer":2,"explanation":"I: follows from 'All tablets are laptops'. II: some watches could lie outside laptops without breaking any statement, so it is not definite. III: a diagram in which all watches are phones fits all the statements, so as a possibility it follows. Hence: Only I and III follow.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"कथन: कुछ टैबलेट घड़ियाँ हैं। सभी टैबलेट लैपटॉप हैं। कुछ लैपटॉप फ़ोन हैं। निम्नलिखित में से कौन-से निष्कर्ष अनुसरण करते हैं? I. कुछ लैपटॉप टैबलेट हैं। II. सभी घड़ियाँ लैपटॉप हैं। III. सभी घड़ियों के फ़ोन होने की संभावना है।","optionsHi":["केवल I अनुसरण करता है","सभी अनुसरण करते हैं","केवल I और III अनुसरण करते हैं","केवल III अनुसरण करता है"],"explanationHi":"I: ‘सभी टैबलेट लैपटॉप हैं’ से अनुसरण करता है। II: कुछ घड़ियाँ लैपटॉपों से बाहर हो सकती हैं और किसी कथन का उल्लंघन नहीं होता, इसलिए यह निश्चित नहीं है। III: ऐसा आरेख जिसमें सभी घड़ियाँ फ़ोन हों, सभी कथनों के अनुकूल है, इसलिए संभावना के रूप में यह अनुसरण करता है। अतः: केवल I और III अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-159","question":"Statements: All coins are keys. Some keys are locks. No locks are chains. Conclusions: I. Some coins being locks is a possibility. II. Some keys are not chains. III. All coins being chains is a possibility.","options":["Only I and III follow","All follow","Only II and III follow","Only I and II follow"],"answer":1,"explanation":"I: coins may overlap the key-lock region. II: the keys that are locks cannot be chains, so some keys are not chains (definite). III: coins can sit in the part of keys outside locks and inside chains, so it is possible. All follow.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: सभी सिक्के चाबियाँ हैं। कुछ चाबियाँ ताले हैं। कोई ताला ज़ंजीर नहीं है। निष्कर्ष: I. कुछ सिक्कों के ताले होने की संभावना है। II. कुछ चाबियाँ ज़ंजीरें नहीं हैं। III. सभी सिक्कों के ज़ंजीर होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं"],"explanationHi":"I: सिक्के चाबी-ताला वाले भाग से मेल खा सकते हैं। II: जो चाबियाँ ताले हैं वे ज़ंजीरें नहीं हो सकतीं, इसलिए कुछ चाबियाँ ज़ंजीरें नहीं हैं (निश्चित)। III: सिक्के चाबियों के उस भाग में हो सकते हैं जो तालों से बाहर और ज़ंजीरों के अंदर है, इसलिए यह संभव है। सभी अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-160","question":"Statements: Only a few rivers are lakes. All lakes are ponds. No ponds are seas. Conclusions: I. Some rivers are not seas. II. All rivers being ponds is a possibility. III. Some lakes being seas is a possibility.","options":["Only I and II follow","All follow","Only II follows","Only I follows"],"answer":0,"explanation":"I: the rivers that are lakes are ponds, hence not seas. II: the non-lake rivers may still lie inside ponds, so possible. III: lakes ⊂ ponds and ponds never meet seas, so a lake can never be a sea.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: केवल कुछ नदियाँ झीलें हैं। सभी झीलें तालाब हैं। कोई तालाब समुद्र नहीं है। निष्कर्ष: I. कुछ नदियाँ समुद्र नहीं हैं। II. सभी नदियों के तालाब होने की संभावना है। III. कुछ झीलों के समुद्र होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल II अनुसरण करता है","केवल I अनुसरण करता है"],"explanationHi":"I: जो नदियाँ झीलें हैं वे तालाब हैं, इसलिए समुद्र नहीं हैं। II: गैर-झील नदियाँ भी तालाबों के अंदर हो सकती हैं, इसलिए यह संभव है। III: झीलें ⊂ तालाब और तालाब कभी समुद्रों से नहीं मिलते, इसलिए कोई झील कभी समुद्र नहीं हो सकती।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-161","question":"Statements: No pencils are erasers. Some erasers are sharpeners. All sharpeners are scales. Conclusions: I. Some scales are not pencils. II. Some sharpeners are not pencils. III. No pencils are scales.","options":["All follow","Only I follows","Only II follows","Only I and II follow"],"answer":3,"explanation":"The erasers that are sharpeners are scales and are not pencils, which gives both I and II. Pencils may still be scales (outside the eraser region), so III is not definite.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कोई पेंसिल रबर नहीं है। कुछ रबर शार्पनर हैं। सभी शार्पनर स्केल हैं। निष्कर्ष: I. कुछ स्केल पेंसिलें नहीं हैं। II. कुछ शार्पनर पेंसिलें नहीं हैं। III. कोई पेंसिल स्केल नहीं है।","optionsHi":["सभी अनुसरण करते हैं","केवल I अनुसरण करता है","केवल II अनुसरण करता है","केवल I और II अनुसरण करते हैं"],"explanationHi":"जो रबर शार्पनर हैं वे स्केल हैं और पेंसिलें नहीं हैं, जिससे I और II दोनों प्राप्त होते हैं। पेंसिलें (रबर वाले भाग से बाहर) फिर भी स्केल हो सकती हैं, इसलिए III निश्चित नहीं है।","subtopic":"three-plus-statements"},
  {"id":"reason-syllogism-162","question":"Statements: Some caps are hats. No hats are scarves. Conclusions: I. Some caps are scarves. II. No caps are scarves. III. Some caps are not scarves.","options":["Only III follows","Either I or II follows, and III follows","Only II and III follow","Only I and III follow"],"answer":1,"explanation":"III: the caps that are hats cannot be scarves, so it is definite. I and II are not definite separately, but they form a complementary pair on the same terms (Some / No), so either I or II follows.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ कैप हैट हैं। कोई हैट स्कार्फ़ नहीं है। निष्कर्ष: I. कुछ कैप स्कार्फ़ हैं। II. कोई कैप स्कार्फ़ नहीं है। III. कुछ कैप स्कार्फ़ नहीं हैं।","optionsHi":["केवल III अनुसरण करता है","I या II में से कोई एक अनुसरण करता है, और III अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल I और III अनुसरण करते हैं"],"explanationHi":"III: जो कैप हैट हैं वे स्कार्फ़ नहीं हो सकतीं, इसलिए यह निश्चित है। I और II अलग-अलग निश्चित नहीं हैं, पर वे समान पदों पर आधारित पूरक युग्म (कुछ / कोई नहीं) हैं, इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-163","question":"Statements: Only a few books are novels. No novels are magazines. Conclusions: I. Some books are not magazines. II. All books being magazines is a possibility. III. Some magazines being books is a possibility.","options":["Only III follows","All follow","Only I follows","Only I and III follow"],"answer":3,"explanation":"I: the books that are novels cannot be magazines. II fails for the same reason: those books can never be magazines. III: the books that are not novels may be magazines, so it is possible.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: केवल कुछ किताबें उपन्यास हैं। कोई उपन्यास पत्रिका नहीं है। निष्कर्ष: I. कुछ किताबें पत्रिकाएँ नहीं हैं। II. सभी किताबों के पत्रिका होने की संभावना है। III. कुछ पत्रिकाओं के किताबें होने की संभावना है।","optionsHi":["केवल III अनुसरण करता है","सभी अनुसरण करते हैं","केवल I अनुसरण करता है","केवल I और III अनुसरण करते हैं"],"explanationHi":"I: जो किताबें उपन्यास हैं वे पत्रिकाएँ नहीं हो सकतीं। II इसी कारण असत्य है: वे किताबें कभी पत्रिकाएँ नहीं हो सकतीं। III: जो किताबें उपन्यास नहीं हैं वे पत्रिकाएँ हो सकती हैं, इसलिए यह संभव है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-164","question":"Statements: All tigers are cats. All cats are mammals. Some mammals are pets. Conclusions: I. Some cats are pets. II. All tigers being pets is a possibility. III. Some mammals are tigers.","options":["Only III follows","All follow","Only II and III follow","Only II follows"],"answer":2,"explanation":"II: pets overlap mammals and can be drawn to contain all tigers. III: tigers ⊂ cats ⊂ mammals and tigers exist, so some mammals are tigers. I is only possible, not definite: the pets may lie in the non-cat part of mammals.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: सभी बाघ बिल्लियाँ हैं। सभी बिल्लियाँ स्तनधारी हैं। कुछ स्तनधारी पालतू हैं। निष्कर्ष: I. कुछ बिल्लियाँ पालतू हैं। II. सभी बाघों के पालतू होने की संभावना है। III. कुछ स्तनधारी बाघ हैं।","optionsHi":["केवल III अनुसरण करता है","सभी अनुसरण करते हैं","केवल II और III अनुसरण करते हैं","केवल II अनुसरण करता है"],"explanationHi":"II: पालतू स्तनधारियों से मेल खाते हैं और ऐसे बनाए जा सकते हैं कि उनमें सभी बाघ आ जाएँ। III: बाघ ⊂ बिल्लियाँ ⊂ स्तनधारी और बाघ होते हैं, इसलिए कुछ स्तनधारी बाघ हैं। I केवल संभव है, निश्चित नहीं: पालतू स्तनधारियों के गैर-बिल्ली भाग में हो सकते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-165","question":"Statements: Some doors are windows. Some windows are walls. Some walls are roofs. Conclusions: I. Some doors are roofs. II. No doors are roofs. III. All windows being roofs is a possibility.","options":["Only II and III follow","Either I or II follows, and III follows","Only I and III follow","Either I or II follows"],"answer":1,"explanation":"Chains of 'some' give no definite link between doors and roofs, but I and II are a complementary Some/No pair, so either I or II follows. III: nothing stops roofs from covering all windows.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ दरवाज़े खिड़कियाँ हैं। कुछ खिड़कियाँ दीवारें हैं। कुछ दीवारें छतें हैं। निष्कर्ष: I. कुछ दरवाज़े छतें हैं। II. कोई दरवाज़ा छत नहीं है। III. सभी खिड़कियों के छत होने की संभावना है।","optionsHi":["केवल II और III अनुसरण करते हैं","I या II में से कोई एक अनुसरण करता है, और III अनुसरण करता है","केवल I और III अनुसरण करते हैं","I या II में से कोई एक अनुसरण करता है"],"explanationHi":"‘कुछ’ वाले कथनों की श्रृंखला से दरवाज़ों और छतों के बीच कोई निश्चित संबंध नहीं बनता, पर I और II ‘कुछ / कोई नहीं’ का पूरक युग्म हैं, इसलिए I या II में से कोई एक अनुसरण करता है। III: कुछ भी छतों को सभी खिड़कियों को ढकने से नहीं रोकता।","subtopic":"possibility"},
  {"id":"reason-syllogism-166","question":"Statements: No shirts are trousers. All trousers are jeans. Some jeans are jackets. Conclusions: I. Some jeans are not shirts. II. All shirts being jeans is a possibility. III. Some jackets are trousers. IV. All jackets being shirts is a possibility.","options":["Only I and II follow","Only I and IV follow","All follow","Only I, II and IV follow"],"answer":3,"explanation":"I: trousers are jeans that are not shirts. II: shirts may lie in the non-trouser part of jeans. III is only possible. IV: the jackets may all lie in jeans outside trousers and inside shirts, so possible.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कोई कमीज़ पतलून नहीं है। सभी पतलूनें जीन्स हैं। कुछ जीन्स जैकेट हैं। निष्कर्ष: I. कुछ जीन्स कमीज़ें नहीं हैं। II. सभी कमीज़ों के जीन्स होने की संभावना है। III. कुछ जैकेट पतलूनें हैं। IV. सभी जैकेटों के कमीज़ होने की संभावना है।","optionsHi":["केवल I और II अनुसरण करते हैं","केवल I और IV अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I, II और IV अनुसरण करते हैं"],"explanationHi":"I: पतलूनें ऐसी जीन्स हैं जो कमीज़ें नहीं हैं। II: कमीज़ें जीन्स के गैर-पतलून भाग में हो सकती हैं। III केवल संभव है। IV: जैकेट सभी जीन्स में पतलूनों से बाहर और कमीज़ों के अंदर हो सकती हैं, इसलिए संभव है।","subtopic":"possibility"},
  {"id":"reason-syllogism-167","question":"Statements: All bottles are jars. No jars are cups. All cups are mugs. Conclusions: I. No bottles are cups. II. Some mugs are not jars. III. Some bottles being mugs is a possibility. IV. All mugs being jars is a possibility.","options":["Only I and III follow","All follow","Only I, II and III follow","Only II and III follow"],"answer":2,"explanation":"I: bottles ⊂ jars and jars never meet cups. II: the cups inside mugs are not jars. III: mugs may extend over bottles. IV fails: some mugs (the cups) can never be jars.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: सभी बोतलें जार हैं। कोई जार कप नहीं है। सभी कप मग हैं। निष्कर्ष: I. कोई बोतल कप नहीं है। II. कुछ मग जार नहीं हैं। III. कुछ बोतलों के मग होने की संभावना है। IV. सभी मगों के जार होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I, II और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I: बोतलें ⊂ जार और जार कभी कपों से नहीं मिलते। II: मगों के अंदर के कप जार नहीं हैं। III: मग बोतलों तक फैल सकते हैं। IV असत्य है: कुछ मग (कप) कभी जार नहीं हो सकते।","subtopic":"possibility"},
  {"id":"reason-syllogism-168","question":"Statements: Some stars are moons. All moons are planets. Only a few planets are comets. Conclusions: I. Some planets are stars. II. All moons being comets is a possibility. III. All stars being planets is a possibility. IV. Some comets are not planets.","options":["Only I, II and III follow","All follow","Only I and II follow","Only II and III follow"],"answer":0,"explanation":"I: the stars that are moons are planets. II: the non-comet part of planets can lie outside moons, so all moons may be comets. III: possible. IV: 'only a few planets are comets' says nothing about comets outside planets, so it is not definite.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ तारे चंद्रमा हैं। सभी चंद्रमा ग्रह हैं। केवल कुछ ग्रह धूमकेतु हैं। निष्कर्ष: I. कुछ ग्रह तारे हैं। II. सभी चंद्रमाओं के धूमकेतु होने की संभावना है। III. सभी तारों के ग्रह होने की संभावना है। IV. कुछ धूमकेतु ग्रह नहीं हैं।","optionsHi":["केवल I, II और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I: जो तारे चंद्रमा हैं वे ग्रह हैं। II: ग्रहों का गैर-धूमकेतु भाग चंद्रमाओं से बाहर हो सकता है, इसलिए सभी चंद्रमा धूमकेतु हो सकते हैं। III: संभव है। IV: ‘केवल कुछ ग्रह धूमकेतु हैं’ ग्रहों से बाहर के धूमकेतुओं के बारे में कुछ नहीं कहता, इसलिए यह निश्चित नहीं है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-169","question":"Statements: No bats are balls. No balls are gloves. Conclusions: I. No bats are gloves. II. Some bats are gloves. III. Some gloves being balls is a possibility.","options":["Only I follows","None follows","Either I or II follows, and III follows","Either I or II follows"],"answer":3,"explanation":"Two negative statements give no relation between bats and gloves, so I and II are not definite but form a complementary pair: either I or II follows. III is impossible since no ball is a glove.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कोई बल्ला गेंद नहीं है। कोई गेंद दस्ताना नहीं है। निष्कर्ष: I. कोई बल्ला दस्ताना नहीं है। II. कुछ बल्ले दस्ताने हैं। III. कुछ दस्तानों के गेंद होने की संभावना है।","optionsHi":["केवल I अनुसरण करता है","कोई भी अनुसरण नहीं करता","I या II में से कोई एक अनुसरण करता है, और III अनुसरण करता है","I या II में से कोई एक अनुसरण करता है"],"explanationHi":"दो निषेधात्मक कथनों से बल्लों और दस्तानों के बीच कोई संबंध नहीं बनता, इसलिए I और II निश्चित नहीं हैं, पर वे पूरक युग्म हैं: I या II में से कोई एक अनुसरण करता है। III असंभव है, क्योंकि कोई गेंद दस्ताना नहीं है।","subtopic":"possibility"},
  {"id":"reason-syllogism-170","question":"Statements: All engineers are graduates. Some graduates are teachers. No teachers are farmers. Conclusions: I. Some engineers are not farmers. II. Some graduates are not farmers. III. All farmers being graduates is a possibility.","options":["Only II and III follow","All follow","Only III follows","Only II follows"],"answer":0,"explanation":"II: the graduates who are teachers cannot be farmers. III: farmers may lie in the non-teacher part of graduates. I fails: engineers may sit outside teachers and be entirely farmers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: सभी इंजीनियर स्नातक हैं। कुछ स्नातक शिक्षक हैं। कोई शिक्षक किसान नहीं है। निष्कर्ष: I. कुछ इंजीनियर किसान नहीं हैं। II. कुछ स्नातक किसान नहीं हैं। III. सभी किसानों के स्नातक होने की संभावना है।","optionsHi":["केवल II और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल III अनुसरण करता है","केवल II अनुसरण करता है"],"explanationHi":"II: जो स्नातक शिक्षक हैं वे किसान नहीं हो सकते। III: किसान स्नातकों के गैर-शिक्षक भाग में हो सकते हैं। I असत्य हो सकता है: इंजीनियर शिक्षकों से बाहर हो सकते हैं और पूरी तरह किसान हो सकते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-171","question":"Statements: Some metals are alloys. Some alloys are not magnets. All magnets are tools. Conclusions: I. Some metals are not magnets. II. Some tools being alloys is a possibility. III. All alloys being tools is a possibility. IV. All metals being magnets is a possibility.","options":["Only II and IV follow","All follow","Only II, III and IV follow","Only II and III follow"],"answer":2,"explanation":"I fails: the alloys that are not magnets need not be metals. II and III: tools may extend beyond magnets to cover alloys. IV: the metal-alloy overlap may lie in the magnet part of alloys, so all metals could be magnets.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ धातुएँ मिश्रधातुएँ हैं। कुछ मिश्रधातुएँ चुंबक नहीं हैं। सभी चुंबक औज़ार हैं। निष्कर्ष: I. कुछ धातुएँ चुंबक नहीं हैं। II. कुछ औज़ारों के मिश्रधातु होने की संभावना है। III. सभी मिश्रधातुओं के औज़ार होने की संभावना है। IV. सभी धातुओं के चुंबक होने की संभावना है।","optionsHi":["केवल II और IV अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल II, III और IV अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I असत्य हो सकता है: जो मिश्रधातुएँ चुंबक नहीं हैं उनका धातु होना आवश्यक नहीं। II और III: औज़ार चुंबकों से आगे फैलकर मिश्रधातुओं को ढक सकते हैं। IV: धातु-मिश्रधातु वाला साझा भाग मिश्रधातुओं के चुंबक वाले भाग में हो सकता है, इसलिए सभी धातुएँ चुंबक हो सकती हैं।","subtopic":"negative-statements"},
  {"id":"reason-syllogism-172","question":"Statements: Only a few shops are malls. All malls are markets. Conclusions: I. All shops being markets is a possibility. II. Some markets are shops. III. All malls being shops is a possibility. IV. No shops are markets.","options":["Only II and III follow","All follow","Only I, II and III follow","Only I and II follow"],"answer":2,"explanation":"I: the non-mall shops may still be markets. II: the shops that are malls are markets. III: malls may lie wholly inside shops (some shops would still be non-malls). IV contradicts II.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: केवल कुछ दुकानें मॉल हैं। सभी मॉल बाज़ार हैं। निष्कर्ष: I. सभी दुकानों के बाज़ार होने की संभावना है। II. कुछ बाज़ार दुकानें हैं। III. सभी मॉलों के दुकान होने की संभावना है। IV. कोई दुकान बाज़ार नहीं है।","optionsHi":["केवल II और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I, II और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं"],"explanationHi":"I: गैर-मॉल दुकानें भी बाज़ार हो सकती हैं। II: जो दुकानें मॉल हैं वे बाज़ार हैं। III: मॉल पूरी तरह दुकानों के अंदर हो सकते हैं (तब भी कुछ दुकानें गैर-मॉल रहेंगी)। IV, II का खंडन करता है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-173","question":"Statements: All violins are guitars. All guitars are drums. No drums are flutes. Conclusions: I. No violins are flutes. II. Some flutes are not guitars. III. All drums being violins is a possibility. IV. Some guitars are violins.","options":["Only I, II and III follow","Only I, II and IV follow","All follow","Only II, III and IV follow"],"answer":2,"explanation":"I: violins ⊂ drums, which never meet flutes. II: flutes exist and lie outside drums ⊃ guitars. III: drums, guitars and violins may coincide. IV: violins exist and are guitars. All follow.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: सभी वायलिन गिटार हैं। सभी गिटार ढोल हैं। कोई ढोल बाँसुरी नहीं है। निष्कर्ष: I. कोई वायलिन बाँसुरी नहीं है। II. कुछ बाँसुरियाँ गिटार नहीं हैं। III. सभी ढोलों के वायलिन होने की संभावना है। IV. कुछ गिटार वायलिन हैं।","optionsHi":["केवल I, II और III अनुसरण करते हैं","केवल I, II और IV अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल II, III और IV अनुसरण करते हैं"],"explanationHi":"I: वायलिन ⊂ ढोल, जो कभी बाँसुरियों से नहीं मिलते। II: बाँसुरियाँ होती हैं और ढोल ⊃ गिटार के बाहर हैं। III: ढोल, गिटार और वायलिन एक-दूसरे के बराबर हो सकते हैं। IV: वायलिन होते हैं और गिटार हैं। सभी अनुसरण करते हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-174","question":"Statements: Some papers are files. All files are folders. No folders are bags. Conclusions: I. Some papers are bags. II. All papers being folders is a possibility. III. Some bags being papers is a possibility. IV. All files being bags is a possibility.","options":["Only II and III follow","Only III follows","Only I, II and III follow","Only II follows"],"answer":0,"explanation":"II: papers may lie wholly inside folders. III: the non-file papers may be bags. I is only possible; IV is impossible because files ⊂ folders, which never meet bags.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ कागज़ फ़ाइलें हैं। सभी फ़ाइलें फ़ोल्डर हैं। कोई फ़ोल्डर थैला नहीं है। निष्कर्ष: I. कुछ कागज़ थैले हैं। II. सभी कागज़ों के फ़ोल्डर होने की संभावना है। III. कुछ थैलों के कागज़ होने की संभावना है। IV. सभी फ़ाइलों के थैले होने की संभावना है।","optionsHi":["केवल II और III अनुसरण करते हैं","केवल III अनुसरण करता है","केवल I, II और III अनुसरण करते हैं","केवल II अनुसरण करता है"],"explanationHi":"II: कागज़ पूरी तरह फ़ोल्डरों के अंदर हो सकते हैं। III: गैर-फ़ाइल कागज़ थैले हो सकते हैं। I केवल संभव है; IV असंभव है, क्योंकि फ़ाइलें ⊂ फ़ोल्डर, जो कभी थैलों से नहीं मिलते।","subtopic":"possibility"},
  {"id":"reason-syllogism-175","question":"Statements: Some birds are parrots. No parrots are crows. All sparrows are birds. Conclusions: I. Some birds are not crows. II. Some sparrows are not parrots. III. All crows being birds is a possibility.","options":["Only III follows","Only I and III follow","All follow","Only I follows"],"answer":1,"explanation":"I: the birds that are parrots are not crows. III: crows may lie in the non-parrot part of birds. II fails: sparrows could all be parrots.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ पक्षी तोते हैं। कोई तोता कौआ नहीं है। सभी गौरैया पक्षी हैं। निष्कर्ष: I. कुछ पक्षी कौए नहीं हैं। II. कुछ गौरैया तोते नहीं हैं। III. सभी कौओं के पक्षी होने की संभावना है।","optionsHi":["केवल III अनुसरण करता है","केवल I और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I अनुसरण करता है"],"explanationHi":"I: जो पक्षी तोते हैं वे कौए नहीं हैं। III: कौए पक्षियों के गैर-तोता भाग में हो सकते हैं। II असत्य हो सकता है: सभी गौरैया तोते हो सकती हैं।","subtopic":"possibility"},
  {"id":"reason-syllogism-176","question":"Statements: Some kites are toys. All toys are gifts. Conclusions: I. All kites are gifts. II. Some kites are not gifts. III. Some gifts are kites.","options":["Either I or II follows, and III follows","Only II and III follow","Only III follows","Only I and III follow"],"answer":0,"explanation":"III: the kites that are toys are gifts. I and II are not definite on their own, but they are an All / Some-not pair on the same terms, so either I or II follows.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कुछ पतंगें खिलौने हैं। सभी खिलौने उपहार हैं। निष्कर्ष: I. सभी पतंगें उपहार हैं। II. कुछ पतंगें उपहार नहीं हैं। III. कुछ उपहार पतंगें हैं।","optionsHi":["I या II में से कोई एक अनुसरण करता है, और III अनुसरण करता है","केवल II और III अनुसरण करते हैं","केवल III अनुसरण करता है","केवल I और III अनुसरण करते हैं"],"explanationHi":"III: जो पतंगें खिलौने हैं वे उपहार हैं। I और II अलग-अलग निश्चित नहीं हैं, पर वे समान पदों पर ‘सभी / कुछ … नहीं’ का युग्म हैं, इसलिए I या II में से कोई एक अनुसरण करता है।","subtopic":"two-statements"},
  {"id":"reason-syllogism-177","question":"Statements: No villages are cities. Some cities are towns. All towns are districts. Conclusions: I. Some districts are not villages. II. Some towns being villages is a possibility. III. All villages being districts is a possibility. IV. No towns are villages.","options":["Only I and III follow","Only I and II follow","Only I, II and III follow","Only II and III follow"],"answer":2,"explanation":"I: the towns that are cities are districts and not villages. II: the non-city part of towns may be villages. III: possible. IV is therefore not definite.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: कोई गाँव शहर नहीं है। कुछ शहर कस्बे हैं। सभी कस्बे ज़िले हैं। निष्कर्ष: I. कुछ ज़िले गाँव नहीं हैं। II. कुछ कस्बों के गाँव होने की संभावना है। III. सभी गाँवों के ज़िले होने की संभावना है। IV. कोई कस्बा गाँव नहीं है।","optionsHi":["केवल I और III अनुसरण करते हैं","केवल I और II अनुसरण करते हैं","केवल I, II और III अनुसरण करते हैं","केवल II और III अनुसरण करते हैं"],"explanationHi":"I: जो कस्बे शहर हैं वे ज़िले हैं और गाँव नहीं हैं। II: कस्बों का गैर-शहर भाग गाँव हो सकता है। III: संभव है। इसलिए IV निश्चित नहीं है।","subtopic":"possibility"},
  {"id":"reason-syllogism-178","question":"Statements: Only a few seeds are plants. Only a few plants are trees. Conclusions: I. Some plants are not trees. II. No seeds are trees. III. Some seeds being trees is a possibility.","options":["Only I and III follow","All follow","Only I follows","Only III follows"],"answer":0,"explanation":"I is part of 'only a few plants are trees'. III: seeds and trees can overlap, so II (No seeds are trees) is not definite.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"कथन: केवल कुछ बीज पौधे हैं। केवल कुछ पौधे पेड़ हैं। निष्कर्ष: I. कुछ पौधे पेड़ नहीं हैं। II. कोई बीज पेड़ नहीं है। III. कुछ बीजों के पेड़ होने की संभावना है।","optionsHi":["केवल I और III अनुसरण करते हैं","सभी अनुसरण करते हैं","केवल I अनुसरण करता है","केवल III अनुसरण करता है"],"explanationHi":"I, ‘केवल कुछ पौधे पेड़ हैं’ का भाग है। III: बीज और पेड़ मेल खा सकते हैं, इसलिए II (कोई बीज पेड़ नहीं है) निश्चित नहीं है।","subtopic":"only-a-few"},
  {"id":"reason-syllogism-179","question":"Which of the following sets of statements makes BOTH conclusions follow? Conclusions: I. Some cups are not plates. II. All plates being bowls is a possibility.","options":["All cups are bowls. Some bowls are not plates.","Some cups are bowls. No bowls are plates.","Some plates are bowls. All cups are plates.","Some cups are spoons. No spoons are plates."],"answer":3,"explanation":"With 'Some cups are spoons; no spoons are plates', the cups that are spoons are not plates (I), and nothing ties bowls to plates, so II stays possible. 'No bowls are plates' kills II; the other two sets do not force any cup to lie outside plates.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"निम्नलिखित में से किस कथन-समूह से दोनों निष्कर्ष निकलते हैं? निष्कर्ष: I. कुछ कप प्लेटें नहीं हैं। II. सभी प्लेटों के कटोरे होने की संभावना है।","optionsHi":["सभी कप कटोरे हैं। कुछ कटोरे प्लेटें नहीं हैं।","कुछ कप कटोरे हैं। कोई कटोरा प्लेट नहीं है।","कुछ प्लेटें कटोरे हैं। सभी कप प्लेटें हैं।","कुछ कप चम्मच हैं। कोई चम्मच प्लेट नहीं है।"],"explanationHi":"‘कुछ कप चम्मच हैं; कोई चम्मच प्लेट नहीं है’ के साथ, जो कप चम्मच हैं वे प्लेटें नहीं हैं (I), और कुछ भी कटोरों को प्लेटों से नहीं जोड़ता, इसलिए II संभव बना रहता है। ‘कोई कटोरा प्लेट नहीं है’ II को असंभव बना देता है; अन्य दो समूह किसी कप को प्लेटों से बाहर होने के लिए बाध्य नहीं करते।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-180","question":"Which of the following sets of statements makes BOTH conclusions follow? Conclusions: I. Some roses are lilies. II. Some lilies are not tulips.","options":["Some roses are lilies. Some roses are not tulips.","All roses are lilies. Some roses are not tulips.","Some lilies are tulips. All tulips are roses.","All lilies are roses. Some roses are not tulips."],"answer":1,"explanation":"If all roses are lilies, roses exist inside lilies (I), and the roses that are not tulips are lilies that are not tulips (II). In the other sets the non-tulip roses (or the lilies) can avoid each other, so II is not forced.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"निम्नलिखित में से किस कथन-समूह से दोनों निष्कर्ष निकलते हैं? निष्कर्ष: I. कुछ गुलाब लिली हैं। II. कुछ लिली ट्यूलिप नहीं हैं।","optionsHi":["कुछ गुलाब लिली हैं। कुछ गुलाब ट्यूलिप नहीं हैं।","सभी गुलाब लिली हैं। कुछ गुलाब ट्यूलिप नहीं हैं।","कुछ लिली ट्यूलिप हैं। सभी ट्यूलिप गुलाब हैं।","सभी लिली गुलाब हैं। कुछ गुलाब ट्यूलिप नहीं हैं।"],"explanationHi":"यदि सभी गुलाब लिली हैं, तो गुलाब लिलियों के अंदर होते हैं (I), और जो गुलाब ट्यूलिप नहीं हैं वे ऐसी लिली हैं जो ट्यूलिप नहीं हैं (II)। अन्य समूहों में गैर-ट्यूलिप गुलाब (या लिली) एक-दूसरे से बच सकते हैं, इसलिए II अनिवार्य नहीं है।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-181","question":"Which of the following sets of statements makes BOTH conclusions follow? Conclusions: I. Some fans are not coolers. II. All coolers being heaters is a possibility.","options":["No coolers are heaters. Some fans are heaters.","No fans are heaters. All coolers are heaters.","Some coolers are heaters. No heaters are fans.","Some fans are heaters. All heaters are coolers."],"answer":1,"explanation":"Coolers ⊂ heaters and heaters never meet fans, so no fan is a cooler, giving I, and II is even definite. 'No coolers are heaters' kills II; in the last two sets the fans may all be coolers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains · SSC CGL Tier 2","questionHi":"निम्नलिखित में से किस कथन-समूह से दोनों निष्कर्ष निकलते हैं? निष्कर्ष: I. कुछ पंखे कूलर नहीं हैं। II. सभी कूलरों के हीटर होने की संभावना है।","optionsHi":["कोई कूलर हीटर नहीं है। कुछ पंखे हीटर हैं।","कोई पंखा हीटर नहीं है। सभी कूलर हीटर हैं।","कुछ कूलर हीटर हैं। कोई हीटर पंखा नहीं है।","कुछ पंखे हीटर हैं। सभी हीटर कूलर हैं।"],"explanationHi":"कूलर ⊂ हीटर और हीटर कभी पंखों से नहीं मिलते, इसलिए कोई पंखा कूलर नहीं है, जिससे I प्राप्त होता है, और II तो निश्चित भी है। ‘कोई कूलर हीटर नहीं है’ II को असंभव बना देता है; अंतिम दो समूहों में सभी पंखे कूलर हो सकते हैं।","subtopic":"reverse-syllogism"},
  {"id":"reason-syllogism-182","question":"Statements: All birds are tables. No bird is a nest. Conclusions: I. All nests are tables. II. Some nests are not birds.","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":1,"explanation":"I does not follow: a diagram with something that is a nest but not a table or a bird; something that is a table and a bird but not a nest satisfies all the statements but makes it false. II follows: No bird is a nest gives \"Some nests are not birds\".","difficulty":"moderate","questionHi":"कथन: सभी चिड़ियाँ मेज़ें हैं। कोई भी चिड़िया घोंसला नहीं है। निष्कर्ष: I. सभी घोंसले मेज़ें हैं। II. कुछ घोंसले चिड़ियाँ नहीं हैं।","optionsHi":["निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो घोंसला है पर मेज़ या चिड़िया नहीं है; ऐसी वस्तु जो मेज़ और चिड़िया है पर घोंसला नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कोई भी चिड़िया घोंसला नहीं है से \"कुछ घोंसले चिड़ियाँ नहीं हैं\" प्राप्त होता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-183","question":"Statements: No apple is a dog. Some roads are not dogs. Conclusions: I. Some apples are roads. II. Some apples are not dogs.","options":["Only conclusion I follows","Only conclusion II follows","Neither conclusion I nor II follows","Both conclusions I and II follow"],"answer":1,"explanation":"I does not follow: a diagram with something that is a dog but not a road or an apple; something that is a road but not a dog or an apple; something that is an apple but not a dog or a road satisfies all the statements but makes it false. II follows: No apple is a dog gives \"Some apples are not dogs\".","difficulty":"moderate","questionHi":"कथन: कोई भी सेब कुत्ता नहीं है। कुछ सड़कें कुत्ते नहीं हैं। निष्कर्ष: I. कुछ सेब सड़कें हैं। II. कुछ सेब कुत्ते नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो कुत्ता है पर सड़क या सेब नहीं है; ऐसी वस्तु जो सड़क है पर कुत्ता या सेब नहीं है; ऐसी वस्तु जो सेब है पर कुत्ता या सड़क नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कोई भी सेब कुत्ता नहीं है से \"कुछ सेब कुत्ते नहीं हैं\" प्राप्त होता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-184","question":"Statements: All lamps are birds. No table is a lamp. Conclusions: I. Some tables are not birds. II. All birds are lamps.","options":["Only conclusion I follows","Only conclusion II follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a bird and a lamp but not a table; something that is a bird and a table but not a lamp satisfies all the statements but makes it false. II does not follow: a diagram with something that is a bird and a lamp but not a table; something that is a bird and a table but not a lamp satisfies all the statements but makes it false.","difficulty":"moderate","questionHi":"कथन: सभी लैंप चिड़ियाँ हैं। कोई भी मेज़ लैंप नहीं है। निष्कर्ष: I. कुछ मेज़ें चिड़ियाँ नहीं हैं। II. सभी चिड़ियाँ लैंप हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो चिड़िया और लैंप है पर मेज़ नहीं है; ऐसी वस्तु जो चिड़िया और मेज़ है पर लैंप नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: ऐसी वस्तु जो चिड़िया और लैंप है पर मेज़ नहीं है; ऐसी वस्तु जो चिड़िया और मेज़ है पर लैंप नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-185","question":"Statements: Some gates are birds. All clocks are birds. Conclusions: I. No bird is a gate. II. All clocks are gates.","options":["Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":2,"explanation":"I does not follow: a diagram with something that is a clock, a gate and a bird satisfies all the statements but makes it false. II does not follow: a diagram with something that is a clock and a bird but not a gate; something that is a gate and a bird but not a clock satisfies all the statements but makes it false.","difficulty":"moderate","questionHi":"कथन: कुछ दरवाज़े चिड़ियाँ हैं। सभी घड़ियाँ चिड़ियाँ हैं। निष्कर्ष: I. कोई भी चिड़िया दरवाज़ा नहीं है। II. सभी घड़ियाँ दरवाज़े हैं।","optionsHi":["निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो घड़ी, दरवाज़ा और चिड़िया है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: ऐसी वस्तु जो घड़ी और चिड़िया है पर दरवाज़ा नहीं है; ऐसी वस्तु जो दरवाज़ा और चिड़िया है पर घड़ी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-186","question":"Statements: Some hills are books. No bus is a hill. Conclusions: I. No hill is a bus. II. Some buses are hills.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":0,"explanation":"I follows: No bus is a hill gives \"No hill is a bus\". II does not follow: a diagram with something that is a bus but not a book or a hill; something that is a book and a hill but not a bus satisfies all the statements but makes it false.","difficulty":"moderate","questionHi":"कथन: कुछ पहाड़ियाँ किताबें हैं। कोई भी बस पहाड़ी नहीं है। निष्कर्ष: I. कोई भी पहाड़ी बस नहीं है। II. कुछ बसें पहाड़ियाँ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: कोई भी बस पहाड़ी नहीं है से \"कोई भी पहाड़ी बस नहीं है\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो बस है पर किताब या पहाड़ी नहीं है; ऐसी वस्तु जो किताब और पहाड़ी है पर बस नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-187","question":"Statements: Some trains are flowers. Some hills are not flowers. Conclusions: I. No train is a flower. II. All flowers are trains.","options":["Only conclusion I follows","Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a hill but not a flower or a train; something that is a flower and a train but not a hill satisfies all the statements but makes it false. II does not follow: a diagram with something that is a flower but not a hill or a train; something that is a hill but not a flower or a train; something that is a flower and a train but not a hill satisfies all the statements but makes it false.","difficulty":"moderate","questionHi":"कथन: कुछ ट्रेनें फूल हैं। कुछ पहाड़ियाँ फूल नहीं हैं। निष्कर्ष: I. कोई भी ट्रेन फूल नहीं है। II. सभी फूल ट्रेनें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो पहाड़ी है पर फूल या ट्रेन नहीं है; ऐसी वस्तु जो फूल और ट्रेन है पर पहाड़ी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: ऐसी वस्तु जो फूल है पर पहाड़ी या ट्रेन नहीं है; ऐसी वस्तु जो पहाड़ी है पर फूल या ट्रेन नहीं है; ऐसी वस्तु जो फूल और ट्रेन है पर पहाड़ी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-188","question":"Statements: Some bells are not rivers. All tables are rivers. Conclusions: I. All tables are bells. II. Some tables are rivers.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a bell but not a river or a table; something that is a river and a table but not a bell satisfies all the statements but makes it false. II follows: All tables are rivers gives \"Some tables are rivers\".","difficulty":"moderate","questionHi":"कथन: कुछ घंटियाँ नदियाँ नहीं हैं। सभी मेज़ें नदियाँ हैं। निष्कर्ष: I. सभी मेज़ें घंटियाँ हैं। II. कुछ मेज़ें नदियाँ हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो घंटी है पर नदी या मेज़ नहीं है; ऐसी वस्तु जो नदी और मेज़ है पर घंटी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: सभी मेज़ें नदियाँ हैं से \"कुछ मेज़ें नदियाँ हैं\" प्राप्त होता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-189","question":"Statements: Some birds are rocks. No chair is a rock. Conclusions: I. Some birds are not chairs. II. Some chairs are not birds.","options":["Only conclusion II follows","Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":2,"explanation":"I follows: No chair is a rock gives \"No rock is a chair\"; Some birds are rocks and No rock is a chair gives \"Some birds are not chairs\". II does not follow: a diagram with something that is a chair and a bird but not a rock; something that is a rock and a bird but not a chair satisfies all the statements but makes it false.","difficulty":"hard","questionHi":"कथन: कुछ चिड़ियाँ चट्टानें हैं। कोई भी कुर्सी चट्टान नहीं है। निष्कर्ष: I. कुछ चिड़ियाँ कुर्सियाँ नहीं हैं। II. कुछ कुर्सियाँ चिड़ियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: कोई भी कुर्सी चट्टान नहीं है से \"कोई भी चट्टान कुर्सी नहीं है\" प्राप्त होता है; कुछ चिड़ियाँ चट्टानें हैं और कोई भी चट्टान कुर्सी नहीं है से \"कुछ चिड़ियाँ कुर्सियाँ नहीं हैं\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो कुर्सी और चिड़िया है पर चट्टान नहीं है; ऐसी वस्तु जो चट्टान और चिड़िया है पर कुर्सी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"two-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-190","question":"Statements: No kite is a train. Some kites are not dogs. All trains are birds. Conclusions: I. Some kites are not trains. II. Some trains are not kites. III. Some kites are dogs.","options":["Only conclusions I and II follow","Only conclusion II follows","Only conclusions II and III follow","Only conclusion I follows"],"answer":0,"explanation":"I follows: No kite is a train gives \"Some kites are not trains\". II follows: No kite is a train gives \"Some trains are not kites\". III does not follow: a diagram with something that is a kite but not a train, a dog or a bird; something that is a train, a dog and a bird but not a kite satisfies all the statements but makes it false.","difficulty":"very-hard","questionHi":"कथन: कोई भी पतंग ट्रेन नहीं है। कुछ पतंगें कुत्ते नहीं हैं। सभी ट्रेनें चिड़ियाँ हैं। निष्कर्ष: I. कुछ पतंगें ट्रेनें नहीं हैं। II. कुछ ट्रेनें पतंगें नहीं हैं। III. कुछ पतंगें कुत्ते हैं।","optionsHi":["केवल निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष II और III अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: कोई भी पतंग ट्रेन नहीं है से \"कुछ पतंगें ट्रेनें नहीं हैं\" प्राप्त होता है। II अनुसरण करता है: कोई भी पतंग ट्रेन नहीं है से \"कुछ ट्रेनें पतंगें नहीं हैं\" प्राप्त होता है। III अनुसरण नहीं करता: ऐसी वस्तु जो पतंग है पर ट्रेन, कुत्ता या चिड़िया नहीं है; ऐसी वस्तु जो ट्रेन, कुत्ता और चिड़िया है पर पतंग नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-191","question":"Statements: All gates are boats. Some gates are birds. All drums are boats. Conclusions: I. Some gates are not birds. II. All birds are drums. III. Some birds are gates.","options":["Only conclusion II follows","Only conclusion I follows","Only conclusions I and II follow","Only conclusion III follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a gate, a bird, a boat and a drum satisfies all the statements but makes it false. II does not follow: a diagram with something that is a gate, a bird and a boat but not a drum; something that is a boat and a drum but not a gate or a bird satisfies all the statements but makes it false. III follows: Some gates are birds gives \"Some birds are gates\".","difficulty":"very-hard","questionHi":"कथन: सभी दरवाज़े नावें हैं। कुछ दरवाज़े चिड़ियाँ हैं। सभी ढोल नावें हैं। निष्कर्ष: I. कुछ दरवाज़े चिड़ियाँ नहीं हैं। II. सभी चिड़ियाँ ढोल हैं। III. कुछ चिड़ियाँ दरवाज़े हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष III अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो दरवाज़ा, चिड़िया, नाव और ढोल है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: ऐसी वस्तु जो दरवाज़ा, चिड़िया और नाव है पर ढोल नहीं है; ऐसी वस्तु जो नाव और ढोल है पर दरवाज़ा या चिड़िया नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। III अनुसरण करता है: कुछ दरवाज़े चिड़ियाँ हैं से \"कुछ चिड़ियाँ दरवाज़े हैं\" प्राप्त होता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-192","question":"Statements: Some cats are not mangoes. All mangoes are roads. Some cats are birds. Conclusions: I. Some roads are cats. II. Some roads are mangoes. III. Some roads are not cats.","options":["Only conclusion II follows","Only conclusion III follows","Only conclusion I follows","Only conclusions I and II follow"],"answer":0,"explanation":"I does not follow: a diagram with something that is a cat and a bird but not a mango or a road; something that is a mango and a road but not a cat or a bird satisfies all the statements but makes it false. II follows: All mangoes are roads gives \"Some roads are mangoes\". III does not follow: a diagram with something that is a cat and a bird but not a mango or a road; something that is a cat, a mango and a road but not a bird satisfies all the statements but makes it false.","difficulty":"very-hard","questionHi":"कथन: कुछ बिल्लियाँ आम नहीं हैं। सभी आम सड़कें हैं। कुछ बिल्लियाँ चिड़ियाँ हैं। निष्कर्ष: I. कुछ सड़कें बिल्लियाँ हैं। II. कुछ सड़कें आम हैं। III. कुछ सड़कें बिल्लियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष III अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष I और II अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो बिल्ली और चिड़िया है पर आम या सड़क नहीं है; ऐसी वस्तु जो आम और सड़क है पर बिल्ली या चिड़िया नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: सभी आम सड़कें हैं से \"कुछ सड़कें आम हैं\" प्राप्त होता है। III अनुसरण नहीं करता: ऐसी वस्तु जो बिल्ली और चिड़िया है पर आम या सड़क नहीं है; ऐसी वस्तु जो बिल्ली, आम और सड़क है पर चिड़िया नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-193","question":"Statements: All rocks are cars. All apples are trees. All trees are rocks. Conclusions: I. All apples are cars. II. Some cars are apples. III. Some cars are trees.","options":["Only conclusions I and II follow","Only conclusions II and III follow","All three conclusions follow","Only conclusions I and III follow"],"answer":2,"explanation":"I follows: All trees are rocks and All rocks are cars gives \"All trees are cars\"; All apples are trees and All trees are cars gives \"All apples are cars\". II follows: All apples are trees gives \"Some apples are trees\"; All trees are rocks and All rocks are cars gives \"All trees are cars\"; Some apples are trees and All trees are cars gives \"Some apples are cars\"; Some apples are cars gives \"Some cars are apples\". III follows: All trees are rocks and All rocks are cars gives \"All trees are cars\"; All trees are cars gives \"Some cars are trees\".","difficulty":"very-hard","questionHi":"कथन: सभी चट्टानें कारें हैं। सभी सेब पेड़ हैं। सभी पेड़ चट्टानें हैं। निष्कर्ष: I. सभी सेब कारें हैं। II. कुछ कारें सेब हैं। III. कुछ कारें पेड़ हैं।","optionsHi":["केवल निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II और III अनुसरण करते हैं","तीनों निष्कर्ष अनुसरण करते हैं","केवल निष्कर्ष I और III अनुसरण करते हैं"],"explanationHi":"I अनुसरण करता है: सभी पेड़ चट्टानें हैं और सभी चट्टानें कारें हैं से \"सभी पेड़ कारें हैं\" प्राप्त होता है; सभी सेब पेड़ हैं और सभी पेड़ कारें हैं से \"सभी सेब कारें हैं\" प्राप्त होता है। II अनुसरण करता है: सभी सेब पेड़ हैं से \"कुछ सेब पेड़ हैं\" प्राप्त होता है; सभी पेड़ चट्टानें हैं और सभी चट्टानें कारें हैं से \"सभी पेड़ कारें हैं\" प्राप्त होता है; कुछ सेब पेड़ हैं और सभी पेड़ कारें हैं से \"कुछ सेब कारें हैं\" प्राप्त होता है; कुछ सेब कारें हैं से \"कुछ कारें सेब हैं\" प्राप्त होता है। III अनुसरण करता है: सभी पेड़ चट्टानें हैं और सभी चट्टानें कारें हैं से \"सभी पेड़ कारें हैं\" प्राप्त होता है; सभी पेड़ कारें हैं से \"कुछ कारें पेड़ हैं\" प्राप्त होता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-194","question":"Statements: Some cars are not boats. All drums are cars. All kites are boats. Conclusions: I. All cars are boats. II. All cars are kites. III. Some cars are drums.","options":["Only conclusions I and III follow","Only conclusion I follows","Only conclusions II and III follow","Only conclusion III follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a boat and a kite but not a drum or a car; something that is a drum and a car but not a boat or a kite satisfies all the statements but makes it false. II does not follow: a diagram with something that is a boat and a kite but not a drum or a car; something that is a drum and a car but not a boat or a kite satisfies all the statements but makes it false. III follows: All drums are cars gives \"Some cars are drums\".","difficulty":"very-hard","questionHi":"कथन: कुछ कारें नावें नहीं हैं। सभी ढोल कारें हैं। सभी पतंगें नावें हैं। निष्कर्ष: I. सभी कारें नावें हैं। II. सभी कारें पतंगें हैं। III. कुछ कारें ढोल हैं।","optionsHi":["केवल निष्कर्ष I और III अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II और III अनुसरण करते हैं","केवल निष्कर्ष III अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो नाव और पतंग है पर ढोल या कार नहीं है; ऐसी वस्तु जो ढोल और कार है पर नाव या पतंग नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: ऐसी वस्तु जो नाव और पतंग है पर ढोल या कार नहीं है; ऐसी वस्तु जो ढोल और कार है पर नाव या पतंग नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। III अनुसरण करता है: सभी ढोल कारें हैं से \"कुछ कारें ढोल हैं\" प्राप्त होता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-195","question":"Statements: Some chairs are boats. Some trains are rivers. All rivers are boats. Conclusions: I. Some chairs are not boats. II. Some rivers are trains. III. All chairs are boats.","options":["Only conclusion I follows","Only conclusion III follows","Only conclusions I and III follow","Only conclusion II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a river, a chair, a boat and a train satisfies all the statements but makes it false. II follows: Some trains are rivers gives \"Some rivers are trains\". III does not follow: a diagram with something that is a chair but not a river, a boat or a train; something that is a river, a chair, a boat and a train satisfies all the statements but makes it false.","difficulty":"very-hard","questionHi":"कथन: कुछ कुर्सियाँ नावें हैं। कुछ ट्रेनें नदियाँ हैं। सभी नदियाँ नावें हैं। निष्कर्ष: I. कुछ कुर्सियाँ नावें नहीं हैं। II. कुछ नदियाँ ट्रेनें हैं। III. सभी कुर्सियाँ नावें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष III अनुसरण करता है","केवल निष्कर्ष I और III अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो नदी, कुर्सी, नाव और ट्रेन है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कुछ ट्रेनें नदियाँ हैं से \"कुछ नदियाँ ट्रेनें हैं\" प्राप्त होता है। III अनुसरण नहीं करता: ऐसी वस्तु जो कुर्सी है पर नदी, नाव या ट्रेन नहीं है; ऐसी वस्तु जो नदी, कुर्सी, नाव और ट्रेन है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-196","question":"Statements: No drum is a bell. All bells are coins. All roads are coins. Conclusions: I. No bell is a drum. II. No bell is a coin. III. Some drums are roads.","options":["Only conclusion I follows","Only conclusions I and II follow","Only conclusion III follows","Only conclusions I and III follow"],"answer":0,"explanation":"I follows: No drum is a bell gives \"No bell is a drum\". II does not follow: a diagram with something that is a bell and a coin but not a drum or a road; something that is a drum, a road and a coin but not a bell satisfies all the statements but makes it false. III does not follow: a diagram with something that is a drum but not a bell, a road or a coin; something that is a bell, a road and a coin but not a drum satisfies all the statements but makes it false.","difficulty":"very-hard","questionHi":"कथन: कोई भी ढोल घंटी नहीं है। सभी घंटियाँ सिक्के हैं। सभी सड़कें सिक्के हैं। निष्कर्ष: I. कोई भी घंटी ढोल नहीं है। II. कोई भी घंटी सिक्का नहीं है। III. कुछ ढोल सड़कें हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष III अनुसरण करता है","केवल निष्कर्ष I और III अनुसरण करते हैं"],"explanationHi":"I अनुसरण करता है: कोई भी ढोल घंटी नहीं है से \"कोई भी घंटी ढोल नहीं है\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो घंटी और सिक्का है पर ढोल या सड़क नहीं है; ऐसी वस्तु जो ढोल, सड़क और सिक्का है पर घंटी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। III अनुसरण नहीं करता: ऐसी वस्तु जो ढोल है पर घंटी, सड़क या सिक्का नहीं है; ऐसी वस्तु जो घंटी, सड़क और सिक्का है पर ढोल नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-197","question":"Statements: Some boats are not rivers. All flowers are rivers. All tables are boats. Conclusions: I. Some tables are not boats. II. Some flowers are rivers. III. No boat is a flower.","options":["Only conclusions I and II follow","Only conclusion II follows","None of the conclusions follows","Only conclusions II and III follow"],"answer":1,"explanation":"I does not follow: a diagram with something that is a boat and a table but not a river or a flower; something that is a river and a flower but not a boat or a table satisfies all the statements but makes it false. II follows: All flowers are rivers gives \"Some flowers are rivers\". III does not follow: a diagram with something that is a boat and a table but not a river or a flower; something that is a boat, a river and a flower but not a table satisfies all the statements but makes it false.","difficulty":"very-hard","questionHi":"कथन: कुछ नावें नदियाँ नहीं हैं। सभी फूल नदियाँ हैं। सभी मेज़ें नावें हैं। निष्कर्ष: I. कुछ मेज़ें नावें नहीं हैं। II. कुछ फूल नदियाँ हैं। III. कोई भी नाव फूल नहीं है।","optionsHi":["केवल निष्कर्ष I और II अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","कोई भी निष्कर्ष अनुसरण नहीं करता","केवल निष्कर्ष II और III अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो नाव और मेज़ है पर नदी या फूल नहीं है; ऐसी वस्तु जो नदी और फूल है पर नाव या मेज़ नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: सभी फूल नदियाँ हैं से \"कुछ फूल नदियाँ हैं\" प्राप्त होता है। III अनुसरण नहीं करता: ऐसी वस्तु जो नाव और मेज़ है पर नदी या फूल नहीं है; ऐसी वस्तु जो नाव, नदी और फूल है पर मेज़ नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"three-plus-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-198","question":"Statements: No chair is a bell. All nests are chairs. Conclusions: I. All bells being chairs is a possibility. II. No bell being a chair is a possibility.","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":1,"explanation":"I does not follow: in every diagram that fits the statements this is impossible. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a bell but not a chair or a nest; something that is a chair and a nest but not a bell).","difficulty":"hard","questionHi":"कथन: कोई भी कुर्सी घंटी नहीं है। सभी घोंसले कुर्सियाँ हैं। निष्कर्ष: I. संभव है कि सभी घंटियाँ कुर्सियाँ हों। II. संभव है कि कोई भी घंटी कुर्सी न हो।","optionsHi":["निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो घंटी है पर कुर्सी या घोंसला नहीं है; ऐसी वस्तु जो कुर्सी और घोंसला है पर घंटी नहीं है)।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-199","question":"Statements: Some stars are lamps. No car is a lamp. Conclusions: I. No star being a lamp is a possibility. II. Some cars not being lamps is a possibility.","options":["Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow"],"answer":0,"explanation":"I does not follow: in every diagram that fits the statements this is impossible. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a star and a lamp but not a car; something that is a car but not a star or a lamp).","difficulty":"hard","questionHi":"कथन: कुछ तारे लैंप हैं। कोई भी कार लैंप नहीं है। निष्कर्ष: I. संभव है कि कोई भी तारा लैंप न हो। II. संभव है कि कुछ कारें लैंप न हों।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो तारा और लैंप है पर कार नहीं है; ऐसी वस्तु जो कार है पर तारा या लैंप नहीं है)।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-200","question":"Statements: All birds are lamps. All lamps are roads. Conclusions: I. Some roads not being birds is a possibility. II. No road being a lamp is a possibility.","options":["Only conclusion II follows","Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow"],"answer":1,"explanation":"I follows as a possibility: a valid diagram exists in which it is true (members: something that is a road but not a bird or a lamp; something that is a bird, a road and a lamp). II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: सभी चिड़ियाँ लैंप हैं। सभी लैंप सड़कें हैं। निष्कर्ष: I. संभव है कि कुछ सड़कें चिड़ियाँ न हों। II. संभव है कि कोई भी सड़क लैंप न हो।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो सड़क है पर चिड़िया या लैंप नहीं है; ऐसी वस्तु जो चिड़िया, सड़क और लैंप है)। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-201","question":"Statements: All buses are ropes. Some buses are lamps. Conclusions: I. Some buses not being ropes is a possibility. II. Some ropes being buses is a possibility.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows"],"answer":3,"explanation":"I does not follow: in every diagram that fits the statements this is impossible. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a rope, a bus and a lamp).","difficulty":"hard","questionHi":"कथन: सभी बसें रस्सियाँ हैं। कुछ बसें लैंप हैं। निष्कर्ष: I. संभव है कि कुछ बसें रस्सियाँ न हों। II. संभव है कि कुछ रस्सियाँ बसें हों।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो रस्सी, बस और लैंप है)।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-202","question":"Statements: Some books are pens. All buses are books. Conclusions: I. No book being a bus is a possibility. II. All books being buses is a possibility.","options":["Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow"],"answer":0,"explanation":"I does not follow: in every diagram that fits the statements this is impossible. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a pen, a bus and a book).","difficulty":"hard","questionHi":"कथन: कुछ किताबें कलमें हैं। सभी बसें किताबें हैं। निष्कर्ष: I. संभव है कि कोई भी किताब बस न हो। II. संभव है कि सभी किताबें बसें हों।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो कलम, बस और किताब है)।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-203","question":"Statements: No bus is a cat. No bus is a star. Conclusions: I. Some stars being cats is a possibility. II. All buses being stars is a possibility.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows"],"answer":2,"explanation":"I follows as a possibility: a valid diagram exists in which it is true (members: something that is a star and a cat but not a bus; something that is a bus but not a star or a cat). II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: कोई भी बस बिल्ली नहीं है। कोई भी बस तारा नहीं है। निष्कर्ष: I. संभव है कि कुछ तारे बिल्लियाँ हों। II. संभव है कि सभी बसें तारे हों।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो तारा और बिल्ली है पर बस नहीं है; ऐसी वस्तु जो बस है पर तारा या बिल्ली नहीं है)। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-204","question":"Statements: All bells are nests. All chairs are nests. Conclusions: I. All nests being chairs is a possibility. II. No bell being a nest is a possibility.","options":["Only conclusion II follows","Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":2,"explanation":"I follows as a possibility: a valid diagram exists in which it is true (members: something that is a nest, a chair and a bell). II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: सभी घंटियाँ घोंसले हैं। सभी कुर्सियाँ घोंसले हैं। निष्कर्ष: I. संभव है कि सभी घोंसले कुर्सियाँ हों। II. संभव है कि कोई भी घंटी घोंसला न हो।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो घोंसला, कुर्सी और घंटी है)। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-205","question":"Statements: Some apples are not stars. Some roads are stars. Conclusions: I. No road being an apple is a possibility. II. No star being a road is a possibility.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Only conclusion II follows","Both conclusions I and II follow"],"answer":0,"explanation":"I follows as a possibility: a valid diagram exists in which it is true (members: something that is an apple but not a star or a road; something that is a star and a road but not an apple). II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: कुछ सेब तारे नहीं हैं। कुछ सड़कें तारे हैं। निष्कर्ष: I. संभव है कि कोई भी सड़क सेब न हो। II. संभव है कि कोई भी तारा सड़क न हो।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो सेब है पर तारा या सड़क नहीं है; ऐसी वस्तु जो तारा और सड़क है पर सेब नहीं है)। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"possibility","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-206","question":"Statements: Only a few trains are drums. Only a few mangoes are drums. Conclusions: I. Only a few trains are mangoes. II. Only a few trains being drums is a possibility.","options":["Only conclusion II follows","Only conclusion I follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":0,"explanation":"I does not follow: a diagram with something that is a train and a mango but not a drum; something that is a train, a drum and a mango satisfies all the statements but makes it false. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a train and a mango but not a drum; something that is a train, a drum and a mango).","difficulty":"very-hard","questionHi":"कथन: केवल कुछ ट्रेनें ढोल हैं। केवल कुछ आम ढोल हैं। निष्कर्ष: I. केवल कुछ ट्रेनें आम हैं। II. केवल संभव है कि कुछ ट्रेनें ढोल हों।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो ट्रेन और आम है पर ढोल नहीं है; ऐसी वस्तु जो ट्रेन, ढोल और आम है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो ट्रेन और आम है पर ढोल नहीं है; ऐसी वस्तु जो ट्रेन, ढोल और आम है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-207","question":"Statements: All books are rivers. Only a few boats are books. Conclusions: I. No boat is a book. II. Some boats not being rivers is a possibility.","options":["Both conclusions I and II follow","Only conclusion II follows","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":1,"explanation":"I does not follow: a diagram with something that is a boat but not a river or a book; something that is a river, a book and a boat satisfies all the statements but makes it false. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a boat but not a river or a book; something that is a river, a book and a boat).","difficulty":"hard","questionHi":"कथन: सभी किताबें नदियाँ हैं। केवल कुछ नावें किताबें हैं। निष्कर्ष: I. कोई भी नाव किताब नहीं है। II. संभव है कि कुछ नावें नदियाँ न हों।","optionsHi":["निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो नाव है पर नदी या किताब नहीं है; ऐसी वस्तु जो नदी, किताब और नाव है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो नाव है पर नदी या किताब नहीं है; ऐसी वस्तु जो नदी, किताब और नाव है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-208","question":"Statements: No kite is a clock. Only a few boats are clocks. Conclusions: I. All boats are kites. II. No boat being a clock is a possibility.","options":["Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":0,"explanation":"I does not follow: a diagram with something that is a kite and a boat but not a clock; something that is a boat and a clock but not a kite satisfies all the statements but makes it false. II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: कोई भी पतंग घड़ी नहीं है। केवल कुछ नावें घड़ियाँ हैं। निष्कर्ष: I. सभी नावें पतंगें हैं। II. संभव है कि कोई भी नाव घड़ी न हो।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो पतंग और नाव है पर घड़ी नहीं है; ऐसी वस्तु जो नाव और घड़ी है पर पतंग नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-209","question":"Statements: Some drums are pens. Only a few tables are pens. Conclusions: I. Some tables are not drums. II. Only a few tables being drums is a possibility.","options":["Only conclusion II follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows"],"answer":0,"explanation":"I does not follow: a diagram with something that is a table and a drum but not a pen; something that is a pen, a table and a drum satisfies all the statements but makes it false. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a table but not a pen or a drum; something that is a pen, a table and a drum).","difficulty":"hard","questionHi":"कथन: कुछ ढोल कलमें हैं। केवल कुछ मेज़ें कलमें हैं। निष्कर्ष: I. कुछ मेज़ें ढोल नहीं हैं। II. केवल संभव है कि कुछ मेज़ें ढोल हों।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो मेज़ और ढोल है पर कलम नहीं है; ऐसी वस्तु जो कलम, मेज़ और ढोल है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो मेज़ है पर कलम या ढोल नहीं है; ऐसी वस्तु जो कलम, मेज़ और ढोल है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-210","question":"Statements: Only a few rivers are books. Only a few books are pens. Conclusions: I. All rivers are pens. II. Some books being pens is a possibility.","options":["Neither conclusion I nor II follows","Only conclusion II follows","Only conclusion I follows","Both conclusions I and II follow"],"answer":1,"explanation":"I does not follow: a diagram with something that is a pen and a book but not a river; something that is a river but not a pen or a book; something that is a book and a river but not a pen satisfies all the statements but makes it false. II follows as a possibility: a valid diagram exists in which it is true (members: something that is a pen and a book but not a river; something that is a river but not a pen or a book; something that is a book and a river but not a pen).","difficulty":"very-hard","questionHi":"कथन: केवल कुछ नदियाँ किताबें हैं। केवल कुछ किताबें कलमें हैं। निष्कर्ष: I. सभी नदियाँ कलमें हैं। II. संभव है कि कुछ किताबें कलमें हों।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो कलम और किताब है पर नदी नहीं है; ऐसी वस्तु जो नदी है पर कलम या किताब नहीं है; ऐसी वस्तु जो किताब और नदी है पर कलम नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो कलम और किताब है पर नदी नहीं है; ऐसी वस्तु जो नदी है पर कलम या किताब नहीं है; ऐसी वस्तु जो किताब और नदी है पर कलम नहीं है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-211","question":"Statements: Only a few coins are cups. Only a few coins are mangoes. Conclusions: I. Some coins are not cups. II. Some coins not being cups is a possibility.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows"],"answer":1,"explanation":"I follows: Only a few coins are cups gives \"Some coins are not cups\". II follows as a possibility: a valid diagram exists in which it is true (members: something that is a mango and a coin but not a cup; something that is a coin and a cup but not a mango).","difficulty":"very-hard","questionHi":"कथन: केवल कुछ सिक्के कप हैं। केवल कुछ सिक्के आम हैं। निष्कर्ष: I. कुछ सिक्के कप नहीं हैं। II. संभव है कि कुछ सिक्के कप न हों।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: केवल कुछ सिक्के कप हैं से \"कुछ सिक्के कप नहीं हैं\" प्राप्त होता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो आम और सिक्का है पर कप नहीं है; ऐसी वस्तु जो सिक्का और कप है पर आम नहीं है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-212","question":"Statements: Only a few trees are nests. All birds are trees. Conclusions: I. Some birds are not nests. II. Some birds not being trees is a possibility.","options":["Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":2,"explanation":"I does not follow: a diagram with something that is a tree but not a bird or a nest; something that is a bird, a nest and a tree satisfies all the statements but makes it false. II does not follow: in every diagram that fits the statements this is impossible.","difficulty":"hard","questionHi":"कथन: केवल कुछ पेड़ घोंसले हैं। सभी चिड़ियाँ पेड़ हैं। निष्कर्ष: I. कुछ चिड़ियाँ घोंसले नहीं हैं। II. संभव है कि कुछ चिड़ियाँ पेड़ न हों।","optionsHi":["निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो पेड़ है पर चिड़िया या घोंसला नहीं है; ऐसी वस्तु जो चिड़िया, घोंसला और पेड़ है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण नहीं करता: कथनों के अनुरूप प्रत्येक आरेख में यह असंभव है।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-213","question":"Statements: All dogs are cars. Only a few dogs are stars. Conclusions: I. Some cars are stars. II. Some cars being dogs is a possibility.","options":["Neither conclusion I nor II follows","Only conclusion I follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":2,"explanation":"I follows: Only a few dogs are stars gives \"Some stars are dogs\"; Some stars are dogs and All dogs are cars gives \"Some stars are cars\"; Some stars are cars gives \"Some cars are stars\". II follows as a possibility: a valid diagram exists in which it is true (members: something that is a car and a dog but not a star; something that is a car, a dog and a star).","difficulty":"hard","questionHi":"कथन: सभी कुत्ते कारें हैं। केवल कुछ कुत्ते तारे हैं। निष्कर्ष: I. कुछ कारें तारे हैं। II. संभव है कि कुछ कारें कुत्ते हों।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: केवल कुछ कुत्ते तारे हैं से \"कुछ तारे कुत्ते हैं\" प्राप्त होता है; कुछ तारे कुत्ते हैं और सभी कुत्ते कारें हैं से \"कुछ तारे कारें हैं\" प्राप्त होता है; कुछ तारे कारें हैं से \"कुछ कारें तारे हैं\" प्राप्त होता है। II संभावना के रूप में अनुसरण करता है: एक वैध आरेख बन सकता है जिसमें यह सत्य है (सदस्य: ऐसी वस्तु जो कार और कुत्ता है पर तारा नहीं है; ऐसी वस्तु जो कार, कुत्ता और तारा है)।","subtopic":"only-a-few","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-214","question":"Statements: Some cars are trees. No car is a shirt. Conclusions: I. Some trees are cars. II. Some shirts are trees.","options":["Only conclusion II follows","Both conclusions I and II follow","Neither conclusion I nor II follows","Only conclusion I follows"],"answer":3,"explanation":"I follows: Some cars are trees gives \"Some trees are cars\". II does not follow: a diagram with something that is a shirt but not a tree or a car; something that is a tree and a car but not a shirt satisfies all the statements but makes it false.","difficulty":"hard","questionHi":"कथन: कुछ कारें पेड़ हैं। कोई भी कार कमीज़ नहीं है। निष्कर्ष: I. कुछ पेड़ कारें हैं। II. कुछ कमीज़ें पेड़ हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: कुछ कारें पेड़ हैं से \"कुछ पेड़ कारें हैं\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो कमीज़ है पर पेड़ या कार नहीं है; ऐसी वस्तु जो पेड़ और कार है पर कमीज़ नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-215","question":"Statements: No apple is a flower. Some gates are apples. Conclusions: I. Some gates are not flowers. II. Some apples are flowers.","options":["Neither conclusion I nor II follows","Only conclusion II follows","Only conclusion I follows","Both conclusions I and II follow"],"answer":2,"explanation":"I follows: Some gates are apples and No apple is a flower gives \"Some gates are not flowers\". II does not follow: a diagram with something that is a flower but not an apple or a gate; something that is an apple and a gate but not a flower satisfies all the statements but makes it false.","difficulty":"hard","questionHi":"कथन: कोई भी सेब फूल नहीं है। कुछ दरवाज़े सेब हैं। निष्कर्ष: I. कुछ दरवाज़े फूल नहीं हैं। II. कुछ सेब फूल हैं।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण करता है: कुछ दरवाज़े सेब हैं और कोई भी सेब फूल नहीं है से \"कुछ दरवाज़े फूल नहीं हैं\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो फूल है पर सेब या दरवाज़ा नहीं है; ऐसी वस्तु जो सेब और दरवाज़ा है पर फूल नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-216","question":"Statements: All buses are cars. No kite is a bus. Conclusions: I. Some buses are cars. II. Some kites are not cars.","options":["Neither conclusion I nor II follows","Only conclusion I follows","Only conclusion II follows","Both conclusions I and II follow"],"answer":1,"explanation":"I follows: All buses are cars gives \"Some buses are cars\". II does not follow: a diagram with something that is a car and a bus but not a kite; something that is a car and a kite but not a bus satisfies all the statements but makes it false.","difficulty":"hard","questionHi":"कथन: सभी बसें कारें हैं। कोई भी पतंग बस नहीं है। निष्कर्ष: I. कुछ बसें कारें हैं। II. कुछ पतंगें कारें नहीं हैं।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं"],"explanationHi":"I अनुसरण करता है: सभी बसें कारें हैं से \"कुछ बसें कारें हैं\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो कार और बस है पर पतंग नहीं है; ऐसी वस्तु जो कार और पतंग है पर बस नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-217","question":"Statements: All cats are ropes. No rope is a boat. Conclusions: I. Some cats are not boats. II. Some cats are not ropes.","options":["Only conclusion I follows","Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion II follows"],"answer":0,"explanation":"I follows: All cats are ropes gives \"Some cats are ropes\"; Some cats are ropes and No rope is a boat gives \"Some cats are not boats\". II does not follow: a diagram with something that is a cat and a rope but not a boat; something that is a boat but not a cat or a rope satisfies all the statements but makes it false.","difficulty":"hard","questionHi":"कथन: सभी बिल्लियाँ रस्सियाँ हैं। कोई भी रस्सी नाव नहीं है। निष्कर्ष: I. कुछ बिल्लियाँ नावें नहीं हैं। II. कुछ बिल्लियाँ रस्सियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण करता है: सभी बिल्लियाँ रस्सियाँ हैं से \"कुछ बिल्लियाँ रस्सियाँ हैं\" प्राप्त होता है; कुछ बिल्लियाँ रस्सियाँ हैं और कोई भी रस्सी नाव नहीं है से \"कुछ बिल्लियाँ नावें नहीं हैं\" प्राप्त होता है। II अनुसरण नहीं करता: ऐसी वस्तु जो बिल्ली और रस्सी है पर नाव नहीं है; ऐसी वस्तु जो नाव है पर बिल्ली या रस्सी नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-218","question":"Statements: No bird is a shirt. No bus is a shirt. Conclusions: I. No bird is a bus. II. Some shirts are not birds.","options":["Only conclusion II follows","Both conclusions I and II follow","Only conclusion I follows","Neither conclusion I nor II follows"],"answer":0,"explanation":"I does not follow: a diagram with something that is a bird and a bus but not a shirt; something that is a shirt but not a bird or a bus satisfies all the statements but makes it false. II follows: No bird is a shirt gives \"Some shirts are not birds\".","difficulty":"hard","questionHi":"कथन: कोई भी चिड़िया कमीज़ नहीं है। कोई भी बस कमीज़ नहीं है। निष्कर्ष: I. कोई भी चिड़िया बस नहीं है। II. कुछ कमीज़ें चिड़ियाँ नहीं हैं।","optionsHi":["केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो चिड़िया और बस है पर कमीज़ नहीं है; ऐसी वस्तु जो कमीज़ है पर चिड़िया या बस नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कोई भी चिड़िया कमीज़ नहीं है से \"कुछ कमीज़ें चिड़ियाँ नहीं हैं\" प्राप्त होता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-219","question":"Statements: Some nests are not flowers. All nests are trains. Conclusions: I. Some nests are flowers. II. Some trains are not flowers.","options":["Only conclusion I follows","Only conclusion II follows","Both conclusions I and II follow","Neither conclusion I nor II follows"],"answer":1,"explanation":"I does not follow: a diagram with something that is a flower but not a nest or a train; something that is a nest and a train but not a flower satisfies all the statements but makes it false. II follows: it is true in every diagram that fits the statements.","difficulty":"hard","questionHi":"कथन: कुछ घोंसले फूल नहीं हैं। सभी घोंसले ट्रेनें हैं। निष्कर्ष: I. कुछ घोंसले फूल हैं। II. कुछ ट्रेनें फूल नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो फूल है पर घोंसला या ट्रेन नहीं है; ऐसी वस्तु जो घोंसला और ट्रेन है पर फूल नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: यह कथनों से बनने वाले प्रत्येक आरेख में सत्य है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-220","question":"Statements: No kite is a river. Some rivers are gates. Conclusions: I. Some gates are not rivers. II. Some kites are not rivers.","options":["Neither conclusion I nor II follows","Both conclusions I and II follow","Only conclusion I follows","Only conclusion II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a river and a gate but not a kite; something that is a kite but not a river or a gate satisfies all the statements but makes it false. II follows: No kite is a river gives \"Some kites are not rivers\".","difficulty":"hard","questionHi":"कथन: कोई भी पतंग नदी नहीं है। कुछ नदियाँ दरवाज़े हैं। निष्कर्ष: I. कुछ दरवाज़े नदियाँ नहीं हैं। II. कुछ पतंगें नदियाँ नहीं हैं।","optionsHi":["न तो निष्कर्ष I और न ही II अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","केवल निष्कर्ष I अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो नदी और दरवाज़ा है पर पतंग नहीं है; ऐसी वस्तु जो पतंग है पर नदी या दरवाज़ा नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कोई भी पतंग नदी नहीं है से \"कुछ पतंगें नदियाँ नहीं हैं\" प्राप्त होता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-221","question":"Statements: No apple is a flower. No flower is a boat. Conclusions: I. Some apples are boats. II. Some flowers are not apples.","options":["Only conclusion I follows","Both conclusions I and II follow","Neither conclusion I nor II follows","Only conclusion II follows"],"answer":3,"explanation":"I does not follow: a diagram with something that is a flower but not a boat or an apple; something that is a boat but not a flower or an apple; something that is an apple but not a flower or a boat satisfies all the statements but makes it false. II follows: No apple is a flower gives \"Some flowers are not apples\".","difficulty":"hard","questionHi":"कथन: कोई भी सेब फूल नहीं है। कोई भी फूल नाव नहीं है। निष्कर्ष: I. कुछ सेब नावें हैं। II. कुछ फूल सेब नहीं हैं।","optionsHi":["केवल निष्कर्ष I अनुसरण करता है","निष्कर्ष I और II दोनों अनुसरण करते हैं","न तो निष्कर्ष I और न ही II अनुसरण करता है","केवल निष्कर्ष II अनुसरण करता है"],"explanationHi":"I अनुसरण नहीं करता: ऐसी वस्तु जो फूल है पर नाव या सेब नहीं है; ऐसी वस्तु जो नाव है पर फूल या सेब नहीं है; ऐसी वस्तु जो सेब है पर फूल या नाव नहीं है वाला आरेख सभी कथनों को संतुष्ट करता है, फिर भी इसे असत्य बनाता है। II अनुसरण करता है: कोई भी सेब फूल नहीं है से \"कुछ फूल सेब नहीं हैं\" प्राप्त होता है।","subtopic":"negative-statements","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-222","question":"Which pair of statements, taken together, makes the conclusion \"Some roads are not trees\" definitely follow?","options":["No rope is a road; Some trees are ropes","No road is a rope; No rope is a tree","All trees are ropes; No road is a rope","Some ropes are not trees; All roads are ropes"],"answer":2,"explanation":"Correct pair: No road is a rope gives \"Some roads are not ropes\"; Some roads are not ropes and All trees are ropes gives \"Some roads are not trees\". Another pair does not work: with something that is a rope but not a tree or a road; something that is a tree, a rope and a road its statements hold but the conclusion is false.","difficulty":"hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कुछ सड़कें पेड़ नहीं हैं\" निश्चित रूप से निकलता है?","optionsHi":["कोई भी रस्सी सड़क नहीं है; कुछ पेड़ रस्सियाँ हैं","कोई भी सड़क रस्सी नहीं है; कोई भी रस्सी पेड़ नहीं है","सभी पेड़ रस्सियाँ हैं; कोई भी सड़क रस्सी नहीं है","कुछ रस्सियाँ पेड़ नहीं हैं; सभी सड़कें रस्सियाँ हैं"],"explanationHi":"सही युग्म: कोई भी सड़क रस्सी नहीं है से \"कुछ सड़कें रस्सियाँ नहीं हैं\" प्राप्त होता है; कुछ सड़कें रस्सियाँ नहीं हैं और सभी पेड़ रस्सियाँ हैं से \"कुछ सड़कें पेड़ नहीं हैं\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो रस्सी है पर पेड़ या सड़क नहीं है; ऐसी वस्तु जो पेड़, रस्सी और सड़क है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-223","question":"Which pair of statements, taken together, makes the conclusion \"No tree is an apple\" definitely follow?","options":["Some apples are not trains; Some trees are not trains","Some trains are apples; All trees are trains","All trees are trains; No train is an apple","All trees are trains; Some apples are trains"],"answer":2,"explanation":"Correct pair: All trees are trains and No train is an apple gives \"No tree is an apple\". Another pair does not work: with something that is an apple, a train and a tree its statements hold but the conclusion is false.","difficulty":"very-hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कोई भी पेड़ सेब नहीं है\" निश्चित रूप से निकलता है?","optionsHi":["कुछ सेब ट्रेनें नहीं हैं; कुछ पेड़ ट्रेनें नहीं हैं","कुछ ट्रेनें सेब हैं; सभी पेड़ ट्रेनें हैं","सभी पेड़ ट्रेनें हैं; कोई भी ट्रेन सेब नहीं है","सभी पेड़ ट्रेनें हैं; कुछ सेब ट्रेनें हैं"],"explanationHi":"सही युग्म: सभी पेड़ ट्रेनें हैं और कोई भी ट्रेन सेब नहीं है से \"कोई भी पेड़ सेब नहीं है\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो सेब, ट्रेन और पेड़ है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-224","question":"Which pair of statements, taken together, makes the conclusion \"Some books are not tables\" definitely follow?","options":["Some clocks are tables; No clock is a book","No clock is a table; All clocks are books","No clock is a table; Some books are not clocks","Some clocks are not books; No table is a clock"],"answer":1,"explanation":"Correct pair: All clocks are books gives \"Some books are clocks\"; Some books are clocks and No clock is a table gives \"Some books are not tables\". Another pair does not work: with something that is a clock but not a book or a table; something that is a book and a table but not a clock its statements hold but the conclusion is false.","difficulty":"very-hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कुछ किताबें मेज़ें नहीं हैं\" निश्चित रूप से निकलता है?","optionsHi":["कुछ घड़ियाँ मेज़ें हैं; कोई भी घड़ी किताब नहीं है","कोई भी घड़ी मेज़ नहीं है; सभी घड़ियाँ किताबें हैं","कोई भी घड़ी मेज़ नहीं है; कुछ किताबें घड़ियाँ नहीं हैं","कुछ घड़ियाँ किताबें नहीं हैं; कोई भी मेज़ घड़ी नहीं है"],"explanationHi":"सही युग्म: सभी घड़ियाँ किताबें हैं से \"कुछ किताबें घड़ियाँ हैं\" प्राप्त होता है; कुछ किताबें घड़ियाँ हैं और कोई भी घड़ी मेज़ नहीं है से \"कुछ किताबें मेज़ें नहीं हैं\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो घड़ी है पर किताब या मेज़ नहीं है; ऐसी वस्तु जो किताब और मेज़ है पर घड़ी नहीं है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-225","question":"Which pair of statements, taken together, makes the conclusion \"No cup is a car\" definitely follow?","options":["No car is a hill; No cup is a hill","All hills are cars; Some cups are not hills","No cup is a hill; All cars are hills","Some cups are not hills; Some cars are not hills"],"answer":2,"explanation":"Correct pair: No cup is a hill gives \"No hill is a cup\"; All cars are hills and No hill is a cup gives \"No car is a cup\"; No car is a cup gives \"No cup is a car\". Another pair does not work: with something that is a cup and a car but not a hill; something that is a hill and a car but not a cup its statements hold but the conclusion is false.","difficulty":"very-hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कोई भी कप कार नहीं है\" निश्चित रूप से निकलता है?","optionsHi":["कोई भी कार पहाड़ी नहीं है; कोई भी कप पहाड़ी नहीं है","सभी पहाड़ियाँ कारें हैं; कुछ कप पहाड़ियाँ नहीं हैं","कोई भी कप पहाड़ी नहीं है; सभी कारें पहाड़ियाँ हैं","कुछ कप पहाड़ियाँ नहीं हैं; कुछ कारें पहाड़ियाँ नहीं हैं"],"explanationHi":"सही युग्म: कोई भी कप पहाड़ी नहीं है से \"कोई भी पहाड़ी कप नहीं है\" प्राप्त होता है; सभी कारें पहाड़ियाँ हैं और कोई भी पहाड़ी कप नहीं है से \"कोई भी कार कप नहीं है\" प्राप्त होता है; कोई भी कार कप नहीं है से \"कोई भी कप कार नहीं है\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो कप और कार है पर पहाड़ी नहीं है; ऐसी वस्तु जो पहाड़ी और कार है पर कप नहीं है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-226","question":"Which pair of statements, taken together, makes the conclusion \"Some stars are cups\" definitely follow?","options":["Some cups are not bulbs; Some bulbs are stars","All cups are bulbs; All bulbs are stars","No bulb is a cup; No bulb is a star","Some stars are not bulbs; No bulb is a cup"],"answer":1,"explanation":"Correct pair: All cups are bulbs and All bulbs are stars gives \"All cups are stars\"; All cups are stars gives \"Some stars are cups\". Another pair does not work: with something that is a cup but not a bulb or a star; something that is a bulb and a star but not a cup its statements hold but the conclusion is false.","difficulty":"hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कुछ तारे कप हैं\" निश्चित रूप से निकलता है?","optionsHi":["कुछ कप बल्ब नहीं हैं; कुछ बल्ब तारे हैं","सभी कप बल्ब हैं; सभी बल्ब तारे हैं","कोई भी बल्ब कप नहीं है; कोई भी बल्ब तारा नहीं है","कुछ तारे बल्ब नहीं हैं; कोई भी बल्ब कप नहीं है"],"explanationHi":"सही युग्म: सभी कप बल्ब हैं और सभी बल्ब तारे हैं से \"सभी कप तारे हैं\" प्राप्त होता है; सभी कप तारे हैं से \"कुछ तारे कप हैं\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो कप है पर बल्ब या तारा नहीं है; ऐसी वस्तु जो बल्ब और तारा है पर कप नहीं है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-227","question":"Which pair of statements, taken together, makes the conclusion \"Some trains are not mangoes\" definitely follow?","options":["No coin is a mango; No coin is a train","All trains are coins; Some coins are not mangoes","Some coins are mangoes; Some trains are coins","No train is a coin; All mangoes are coins"],"answer":3,"explanation":"Correct pair: No train is a coin gives \"Some trains are not coins\"; Some trains are not coins and All mangoes are coins gives \"Some trains are not mangoes\". Another pair does not work: with something that is a mango, a coin and a train its statements hold but the conclusion is false.","difficulty":"very-hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कुछ ट्रेनें आम नहीं हैं\" निश्चित रूप से निकलता है?","optionsHi":["कोई भी सिक्का आम नहीं है; कोई भी सिक्का ट्रेन नहीं है","सभी ट्रेनें सिक्के हैं; कुछ सिक्के आम नहीं हैं","कुछ सिक्के आम हैं; कुछ ट्रेनें सिक्के हैं","कोई भी ट्रेन सिक्का नहीं है; सभी आम सिक्के हैं"],"explanationHi":"सही युग्म: कोई भी ट्रेन सिक्का नहीं है से \"कुछ ट्रेनें सिक्के नहीं हैं\" प्राप्त होता है; कुछ ट्रेनें सिक्के नहीं हैं और सभी आम सिक्के हैं से \"कुछ ट्रेनें आम नहीं हैं\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो आम, सिक्का और ट्रेन है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
  {"id":"reason-syllogism-228","question":"Which pair of statements, taken together, makes the conclusion \"Some books are not drums\" definitely follow?","options":["Some birds are drums; All books are birds","Some birds are not drums; Some birds are not books","No drum is a bird; Some books are birds","Some birds are drums; Some books are not birds"],"answer":2,"explanation":"Correct pair: No drum is a bird gives \"No bird is a drum\"; Some books are birds and No bird is a drum gives \"Some books are not drums\". Another pair does not work: with something that is a bird but not a book or a drum; something that is a book and a drum but not a bird its statements hold but the conclusion is false.","difficulty":"very-hard","questionHi":"निम्नलिखित में से किस कथन-युग्म को एक साथ लेने पर निष्कर्ष \"कुछ किताबें ढोल नहीं हैं\" निश्चित रूप से निकलता है?","optionsHi":["कुछ चिड़ियाँ ढोल हैं; सभी किताबें चिड़ियाँ हैं","कुछ चिड़ियाँ ढोल नहीं हैं; कुछ चिड़ियाँ किताबें नहीं हैं","कोई भी ढोल चिड़िया नहीं है; कुछ किताबें चिड़ियाँ हैं","कुछ चिड़ियाँ ढोल हैं; कुछ किताबें चिड़ियाँ नहीं हैं"],"explanationHi":"सही युग्म: कोई भी ढोल चिड़िया नहीं है से \"कोई भी चिड़िया ढोल नहीं है\" प्राप्त होता है; कुछ किताबें चिड़ियाँ हैं और कोई भी चिड़िया ढोल नहीं है से \"कुछ किताबें ढोल नहीं हैं\" प्राप्त होता है। एक अन्य युग्म सफल नहीं होता: ऐसी वस्तु जो चिड़िया है पर किताब या ढोल नहीं है; ऐसी वस्तु जो किताब और ढोल है पर चिड़िया नहीं है होने पर उसके कथन सत्य रहते हैं पर निष्कर्ष असत्य हो जाता है।","subtopic":"reverse-syllogism","source":"IBPS PO Mains · SBI PO · SSC CGL"},
];

